INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35d6ba2a-dc45-4b4e-bcc9-5aca45d051a3', '哭左偃（題擬）', '哭左偃（題擬）', '1b0614f1-7c7f-42b3-8a10-6396eff28a1b', '唐', '["堂親垂白日，稚子欲行時。","（見《增修詩話總龜》卷四引《雅言雜錄》。","）（按：王操入宋後詩存者尚多，茲不備錄。","）。"]', '["堂親垂白日，稚子欲行时。","（见《增修诗話總龟》卷四引《雅言杂錄》。","）（按：王操入宋後诗存者尚多，茲不備錄。","）。"]', '诗', 'shi', '', NULL, '哭左偃（題擬） 王操 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc5bcd61-07e0-4b16-b56d-8265a2c13fa8', '碧流院（題擬）', '碧流院（題擬）', '42d41e60-9aae-449e-82a4-27c9b031db3c', '唐', '["石骨生泉冷，流來澗沼湄。","幽禽鳴竹砌，遊客步階陲。","滃鬱杉松碧，陰稠煙靄緇。","古風吟不足，嗟恨老蒼髭。","（見宋潛說友《咸淳臨安志》卷八十五。","）（按：碧流院，吳越王更名碧沼。","此詩不詳作年，題仍舊名。","又稜約卒於乾寧、天復間，以其爲錢鏐佐屬，故收歸吳越。","）。"]', '["石骨生泉冷，流来澗沼湄。","幽禽鳴竹砌，游客步階陲。","滃鬱杉松碧，陰稠煙靄緇。","古风吟不足，嗟恨老蒼髭。","（见宋潛说友《咸淳臨安志》卷八十五。","）（按：碧流院，吳越王更名碧沼。","此诗不詳作年，題仍旧名。","又稜約卒於乾寧、天复间，以其爲錢鏐佐屬，故收归吳越。","）。"]', '诗', 'shi', '', NULL, '碧流院（題擬） 杜稜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccb8c0c1-89d9-4bbe-9174-35f0201b0964', '鞠歌行', '鞠歌行', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["麗莫似漢宮妃，謙莫似黃家女。","黃女持謙齒髮高，漢妃恃麗天庭去。","人生容德不自保，聖人安用推天道。","君不見，蔡澤嵌枯詭怪之形狀，大言直取秦丞相；又不見，田千秋才智不出人，一朝富貴如有神。","二侯行事在方冊，泣麟老人終困厄。","夜光抱恨良歎（一作「璞」）悲，日月逝矣吾何之。","（見《文苑英華》卷二○三。","）（按：《全唐詩》卷一八五收作李白詩，殆沿明刻本《文苑英華》之誤。","中華書局影印本此卷爲宋刻，前爲李白同題詩，後即此首，署「羅隱」，確鑿無誤。","）。"]', '["丽莫似漢宮妃，謙莫似黄家女。","黄女持謙齒髮高，漢妃恃丽天庭去。","人生容德不自保，聖人安用推天道。","君不见，蔡澤嵌枯詭怪之形狀，大言直取秦丞相；又不见，田千秋才智不出人，一朝富貴如有神。","二侯行事在方冊，泣麟老人終困厄。","夜光抱恨良歎（一作「璞」）悲，日月逝矣吾何之。","（见《文苑英华》卷二○三。","）（按：《全唐诗》卷一八五收作李白诗，殆沿明刻本《文苑英华》之誤。","中华书局影印本此卷爲宋刻，前爲李白同題诗，後即此首，署「羅隐」，確鑿無誤。","）。"]', '诗', 'shi', '', NULL, '鞠歌行 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed522f34-3f55-45cb-9a35-b5deeb3ab78b', '宿法華寺', '宿法华寺', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["心與空林共杳冥，孤燈寒竹自熒熒。","不知何處小乘客，一夜風前聞誦經。","（見《會稽掇英總集》卷八。","）。"]', '["心與空林共杳冥，孤灯寒竹自熒熒。","不知何处小乘客，一夜风前闻誦經。","（见《會稽掇英總集》卷八。","）。"]', '诗', 'shi', '', NULL, '宿法華寺 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8ecf538-d0df-4d4f-8bcc-d2ffca2cf958', '上亭驛（題擬）', '上亭驛（題擬）', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["細（《輿地紀勝》、《天中記》作「山」）雨霏微宿上亭，雨中因感（《輿地紀勝》、《天中記》作「想」）雨淋鈴。","貴爲天子猶魂斷，窮著荷衣好涕零。","劍水多端何處去，巴猿無賴不堪聽。","少年辛苦今飄蕩，空（一作「深」）媿先生教聚螢。","（見宋王灼《碧鷄漫志》卷五。","）（按：《全唐詩》卷六六五據《天中記》收首二句，《全唐詩續補遺》卷十六據《輿地紀勝》卷一八六收前四句，均不全，今重錄之。","）。"]', '["細（《輿地紀勝》、《天中記》作「山」）雨霏微宿上亭，雨中因感（《輿地紀勝》、《天中記》作「想」）雨淋鈴。","貴爲天子猶魂斷，窮著荷衣好涕零。","劍水多端何处去，巴猿無賴不堪听。","少年辛苦今飄蕩，空（一作「深」）媿先生教聚螢。","（见宋王灼《碧鷄漫志》卷五。","）（按：《全唐诗》卷六六五據《天中記》收首二句，《全唐诗續補遺》卷十六據《輿地紀勝》卷一八六收前四句，均不全，今重錄之。","）。"]', '诗', 'shi', '', NULL, '上亭驛（題擬） 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0da0d39e-a1dd-405d-a4d8-f2da3a413aca', '題石門', '題石门', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["靈巖一竅何年鑿？混沌初開有此門。","探藥仙人何處去，山中不改舊乾坤。","（《宛陵郡志備要》。","此首從《鄭州大學學報》一九八六年六期李之亮《〈羅隱年譜〉補正》一文所輯收入。","）。"]', '["靈巖一竅何年鑿？混沌初开有此门。","探藥仙人何处去，山中不改旧乾坤。","（《宛陵郡志備要》。","此首從《鄭州大学学報》一九八六年六期李之亮《〈羅隐年譜〉補正》一文所輯收入。","）。"]', '诗', 'shi', '', NULL, '題石門 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5065b2f-16eb-47ad-aa50-886d06a42ec2', '吳公約神道碑附詩', '吳公約神道碑附诗', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["吳山蒼蒼，吳水泱泱。","降生英靈，爲公爲王。","以嚴師旅，以奠封疆。","派有別者，我亦鷹揚。","取直之功，捍巢之績。","雖從本軍，實展良畫。","踐歷禁旅，光揚事迹。","乃自西佳，遷於硤石。","上君東代，諸將西征，賈其餘通，資其銳兵。","稽山霧廓，京口波清。","再從貂冕，始拜冬卿。","吳會紛紜，淮[右]（石）（從雍文華校本改）奔競。","驅其涷餒，犯我疆境。","躬勵精卒，恭承上命。","雪霽松貞，風中草勁。","元戎承制，聖主酬勞。","大起名重，司元望高。","優游渥澤，出入官曹。","所謂鷄省，全資豹韜。","恭仰府城，載崇吾圉。","惟力是助，厥功以舉。","雲矗千堵，土攢萬杵。","率以資產，役以軍旅。","乃頒異寵，乃正華資。","大國綱紀，雄藩羽儀。","牀間牛鬬，杯裏蛇疑。","天胡可測，神亦難知。","有仁於時，有功於物。","一代殊勳，二品清秩。","不謂不達，何獲何失。","瑞馬神羊，金箱玉室。","（出《全唐文》卷八九七。","）（〖1〗碑云：「君嗣子以隱鄉里之舊，請銘其墓。","而復以詩一章，文其美於道之隅。","」）。"]', '["吳山蒼蒼，吳水泱泱。","降生英靈，爲公爲王。","以嚴師旅，以奠封疆。","派有別者，我亦鷹揚。","取直之功，捍巢之績。","雖從本軍，實展良畫。","踐歷禁旅，光揚事迹。","乃自西佳，遷於硤石。","上君东代，諸將西征，賈其餘通，資其銳兵。","稽山霧廓，京口波清。","再從貂冕，始拜冬卿。","吳會紛紜，淮[右]（石）（從雍文华校本改）奔競。","驱其涷餒，犯我疆境。","躬勵精卒，恭承上命。","雪霽松貞，风中草勁。","元戎承制，聖主酬勞。","大起名重，司元望高。","優游渥澤，出入官曹。","所謂鷄省，全資豹韜。","恭仰府城，載崇吾圉。","惟力是助，厥功以舉。","云矗千堵，土攢万杵。","率以資產，役以軍旅。","乃頒異寵，乃正华資。","大国綱紀，雄藩羽儀。","牀间牛鬬，杯裏蛇疑。","天胡可測，神亦难知。","有仁於时，有功於物。","一代殊勳，二品清秩。","不謂不達，何獲何失。","瑞马神羊，金箱玉室。","（出《全唐文》卷八九七。","）（〖1〗碑云：「君嗣子以隐乡里之旧，請銘其墓。","而复以诗一章，文其美於道之隅。","」）。"]', '诗', 'shi', '', NULL, '吳公約神道碑附詩 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b49f5aa3-7dff-407f-aacc-b6e71c4db8d1', '繡', '繡', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["一片絲羅輕似水，洞房西室女工勞。","花隨玉指添春色，鳥逐金針長羽毛。","蜀錦謾誇聲自貴，越綾虛說價猶高。","可中用作鴛鴦被，紅葉枝枝不礙刀。","（見雍文華校本《羅隱集·甲乙集》，又見《四庫全書》本《羅昭諫集》。","）（按：《全唐詩》卷六五六收此詩，缺三字，今重錄。","雍文華所據爲清張瓚瑞榴堂《羅昭諫集》。","）。"]', '["一片絲羅轻似水，洞房西室女工勞。","花隨玉指添春色，鸟逐金針长羽毛。","蜀錦謾誇声自貴，越綾虛说價猶高。","可中用作鴛鴦被，紅葉枝枝不礙刀。","（见雍文华校本《羅隐集·甲乙集》，又见《四庫全书》本《羅昭諫集》。","）（按：《全唐诗》卷六五六收此诗，缺三字，今重錄。","雍文华所據爲清張瓚瑞榴堂《羅昭諫集》。","）。"]', '诗', 'shi', '', NULL, '繡 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e0ff9b3-92f9-42cd-89a0-ec2e0d7b4d06', '詠柳', '詠柳', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["裊裊和煙映玉樓，半垂橋上半垂流。","今年漸見枝條密，惱亂春風卒未休。","（見蜀何光遠《鑑誡錄》卷七《亡國音》。","）（按：《全唐詩》卷六六三收隱《柳》詩，係據《甲乙集》卷九所錄，與最早記載本詩的《鑑誡錄》相較，有十三字不同。","今重錄。","）。"]', '["裊裊和煙映玉楼，半垂橋上半垂流。","今年漸见枝條密，惱亂春风卒未休。","（见蜀何光远《鑑誡錄》卷七《亡国音》。","）（按：《全唐诗》卷六六三收隐《柳》诗，係據《甲乙集》卷九所錄，與最早記載本诗的《鑑誡錄》相較，有十三字不同。","今重錄。","）。"]', '诗', 'shi', '', NULL, '詠柳 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83252864-bba3-4423-bff1-fa54fca51573', '過梁震居留題', '過梁震居留題', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["道院迎仙客，書堂隱相儒。","庭栽棲鳳竹，池養化龍魚。","（見《堯山堂外紀》卷三九、《全浙詩話》卷八。","）（按：隱卒開平間，震至後康時始在荆南握重權。","詩疑出僞托。","）。"]', '["道院迎仙客，书堂隐相儒。","庭栽棲鳳竹，池養化龙鱼。","（见《堯山堂外紀》卷三九、《全浙诗話》卷八。","）（按：隐卒开平间，震至後康时始在荆南握重權。","诗疑出僞托。","）。"]', '诗', 'shi', '', NULL, '過梁震居留題 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac714e5d-7f73-462f-9662-4c30abe55265', '送竈詩', '送竈诗', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["一盞清茶一縷煙，竈君皇帝上青天。","玉皇若問人間事，爲道文章不值錢。","（《堅瓠甲集》卷二。","又見《全浙詩話》卷八。","）（按：此篇似亦出後人附託。","）。"]', '["一盞清茶一縷煙，竈君皇帝上青天。","玉皇若问人间事，爲道文章不值錢。","（《堅瓠甲集》卷二。","又见《全浙诗話》卷八。","）（按：此篇似亦出後人附託。","）。"]', '诗', 'shi', '', NULL, '送竈詩 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f90aa5c2-14f4-4aad-8642-66cfad89975d', '下杜城', '下杜城', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["來往城南十八年，賴家橋上潏河邊。","村醪香美脫衣典，幾度落花相對眠。","（《類編長安志》卷九。","）。"]', '["来往城南十八年，賴家橋上潏河邊。","村醪香美脫衣典，幾度落花相对眠。","（《類編长安志》卷九。","）。"]', '诗', 'shi', '', NULL, '下杜城 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d6226f0-3d66-4da4-9629-42214387240a', '華嚴寺', '华嚴寺', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["華嚴[西]（而）轉遶朱坡，每到春時日夕過。","曾向姚家園裏醉，牡丹紅紫數千窠。","（同前。","）。"]', '["华嚴[西]（而）轉遶朱坡，每到春时日夕過。","曾向姚家园裏醉，牡丹紅紫數千窠。","（同前。","）。"]', '诗', 'shi', '', NULL, '華嚴寺 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28872669-59a8-4cd8-bd41-fa065dce3267', '遊北湖', '游北湖', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["醒心亭下水涵天，吏部風流三百年。","（見《輿地紀勝》卷五十七《郴州》。","）。"]', '["醒心亭下水涵天，吏部风流三百年。","（见《輿地紀勝》卷五十七《郴州》。","）。"]', '诗', 'shi', '', NULL, '遊北湖 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65a9b2ba-30bc-476c-922a-40add4f526a5', '鳳凰臺', '鳳凰台', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["昔云丹穴鳳，翔集高臺端。","（同前。","）。"]', '["昔云丹穴鳳，翔集高台端。","（同前。","）。"]', '诗', 'shi', '', NULL, '鳳凰臺 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4d051dc-aa99-48d1-8205-d05885b5be39', '下第詩', '下第诗', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["簾捲殘陽鳴鳥鵲，花飛何處好樓臺。","（見明胡應麟《詩藪·內編》卷六。","）。"]', '["簾捲殘陽鳴鸟鵲，花飞何处好楼台。","（见明胡應麟《诗藪·內編》卷六。","）。"]', '诗', 'shi', '', NULL, '下第詩 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c74c46c0-1260-47bf-b1c9-f474863db70a', '句 一', '句 一', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["曹韓沙嘴團，銅陵出狀元。","（見影印天一閣藏本《嘉靖池州府志》卷一。","）。"]', '["曹韓沙嘴團，銅陵出狀元。","（见影印天一閣藏本《嘉靖池州府志》卷一。","）。"]', '诗', 'shi', '', NULL, '句 一 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e1785f1-2e13-4e7f-b00a-52eb07f5ad5a', '句 二', '句 二', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["飲水魚心知冷暖，濯纓人足識炎涼。","（《天都載》。","）。"]', '["饮水鱼心知冷暖，濯纓人足識炎涼。","（《天都載》。","）。"]', '诗', 'shi', '', NULL, '句 二 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('751349f5-6ec5-4fff-bc1a-3b93888febec', '句 三', '句 三', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["桃李無言應笑我，二年塵土滿漁航。","（《五色線》。","）。"]', '["桃李無言應笑我，二年塵土满漁航。","（《五色線》。","）。"]', '诗', 'shi', '', NULL, '句 三 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('277b6d07-84d6-4cf2-b7be-1b56ff5e0432', '句 四', '句 四', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["馬上抱雞鬬三市，袖中携劍五陵遊。","（《蕘山堂》。","以上六句均見明閔元衢《羅江東外紀》。","）（按：自《下第詩》以降，皆據雍文華校點本《羅隱集》所輯佚句迻錄。","）。"]', '["马上抱雞鬬三市，袖中携劍五陵游。","（《蕘山堂》。","以上六句均见明閔元衢《羅江东外紀》。","）（按：自《下第诗》以降，皆據雍文华校点本《羅隐集》所輯佚句迻錄。","）。"]', '诗', 'shi', '', NULL, '句 四 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b874242-9696-4dfe-ab73-bc20a1df112b', '句 五', '句 五', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["一列珠簾不下鈎。","（《後村千家詩》卷十六聞人祥正《集句》引。","）。"]', '["一列珠簾不下鈎。","（《後村千家诗》卷十六闻人祥正《集句》引。","）。"]', '诗', 'shi', '', NULL, '句 五 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65353a75-d60b-4f5a-be85-efc6a23ba6bf', '歌 一', '歌 一', 'dc606179-ea05-4193-9992-8e6cd242aab4', '唐', '["只箇心心心是佛，十方世界最靈物。","縱橫妙用可憐生，一切不如心真實。"]', '["只箇心心心是佛，十方世界最靈物。","縱橫妙用可怜生，一切不如心真實。"]', '诗', 'shi', '', NULL, '歌 一 契此 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1d59678-e6eb-40a0-bcc8-2d800c916622', '歌 二', '歌 二', 'dc606179-ea05-4193-9992-8e6cd242aab4', '唐', '["騰騰自在無所爲，閑閑究竟出家兒。","若睹目前真大道，不見纖毫也大奇。","。"]', '["腾腾自在無所爲，闲闲究竟出家兒。","若睹目前真大道，不见纖毫也大奇。","。"]', '诗', 'shi', '', NULL, '歌 二 契此 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4968a968-2c4b-4421-81d1-99163fed2475', '歌 三', '歌 三', 'dc606179-ea05-4193-9992-8e6cd242aab4', '唐', '["萬法何殊心何異，何勞更用尋經義。","心王本自絕多知，智者只明無學地。","（以上三首又見《宗鏡錄》卷十八。","）。"]', '["万法何殊心何異，何勞更用尋經義。","心王本自絕多知，智者只明無学地。","（以上三首又见《宗镜錄》卷十八。","）。"]', '诗', 'shi', '', NULL, '歌 三 契此 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d088aadc-d51e-4b51-8c2e-1ad218f4d50f', '歌 四', '歌 四', 'dc606179-ea05-4193-9992-8e6cd242aab4', '唐', '["非凡非聖復若乎，不彊分別聖情孤。","無價心珠本圓淨，凡是異相妄空呼。"]', '["非凡非聖复若乎，不彊分別聖情孤。","無價心珠本圓淨，凡是異相妄空呼。"]', '诗', 'shi', '', NULL, '歌 四 契此 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cba4861-41ee-4b72-ad9c-be92e8576645', '歌 五', '歌 五', 'dc606179-ea05-4193-9992-8e6cd242aab4', '唐', '["人能弘道道分明，無量清高稱道情。","攜錫若登故國路，莫愁諸處不聞聲。","（按：以上五首，《景德傳燈錄》原連爲一首。","今參《宗鏡錄》及《明州定應大師布袋和尚傳》分作五首。","）。"]', '["人能弘道道分明，無量清高稱道情。","携錫若登故国路，莫愁諸处不闻声。","（按：以上五首，《景德傳灯錄》原連爲一首。","今參《宗镜錄》及《明州定應大師布袋和尚傳》分作五首。","）。"]', '诗', 'shi', '', NULL, '歌 五 契此 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88595216-c74a-4e0a-b699-b94342efe93b', '偈', '偈', 'dc606179-ea05-4193-9992-8e6cd242aab4', '唐', '["一鉢千家飯，孤身萬里遊。","青目覩人少，問路白雲頭。","（此首又見《石倉歷代詩選》卷一一一。","）。"]', '["一鉢千家飯，孤身万里游。","青目覩人少，问路白云头。","（此首又见《石倉歷代诗選》卷一一一。","）。"]', '诗', 'shi', '', NULL, '偈 契此 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0503f285-33c1-45e2-b97f-31c8265a3dbb', '臨滅偈（題擬）', '臨滅偈（題擬）', 'dc606179-ea05-4193-9992-8e6cd242aab4', '唐', '["彌勒真彌勒，分（《布袋和尚傳》作「化」）身千百億。","時時示時（《布袋和尚傳》作「世」、《雞肋編》卷中作「識世」）人，時人終（《雞肋編》作「總」、《五燈會元》作「自」、《布袋和尚傳》作「俱」）不識。","（以上諸首均見《景德傳燈錄》卷二十七、《五燈會元》卷二、《卍續藏》本《明州定應大師布袋和尚傳》〖元人曇噩作〗。","）（按：《布袋和尚傳》云此爲其滅後作，末題九字云：「不得狀吾相，此即是真。","」）。"]', '["彌勒真彌勒，分（《布袋和尚傳》作「化」）身千百億。","时时示时（《布袋和尚傳》作「世」、《雞肋編》卷中作「識世」）人，时人終（《雞肋編》作「總」、《五灯會元》作「自」、《布袋和尚傳》作「俱」）不識。","（以上諸首均见《景德傳灯錄》卷二十七、《五灯會元》卷二、《卍續藏》本《明州定應大師布袋和尚傳》〖元人曇噩作〗。","）（按：《布袋和尚傳》云此爲其滅後作，末題九字云：「不得狀吾相，此即是真。","」）。"]', '诗', 'shi', '', NULL, '臨滅偈（題擬） 契此 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72acafd9-e977-4d32-90cb-c9b8d479892c', '偈 一', '偈 一', 'dc606179-ea05-4193-9992-8e6cd242aab4', '唐', '["是非憎愛多世偏多，子細思量奈我何。","寬却肚腸須（《布袋和尚傳》、《明州岳林寺志》作「皮常」）忍辱，豁開心地任從他（《明州岳林寺志》作「放開笑中暗消磨」，《布袋和尚傳》「笑口」作「泆日」，似誤。","）若逢知己須依分，縱遇冤家也共和。","若能了此心頭事（《布袋和尚傳》、《明州岳林寺志》作「能使此心無絓礙」），自然證得六波羅。"]', '["是非憎愛多世偏多，子細思量奈我何。","寬却肚腸須（《布袋和尚傳》、《明州岳林寺志》作「皮常」）忍辱，豁开心地任從他（《明州岳林寺志》作「放开笑中暗消磨」，《布袋和尚傳》「笑口」作「泆日」，似誤。","）若逢知己須依分，縱遇冤家也共和。","若能了此心头事（《布袋和尚傳》、《明州岳林寺志》作「能使此心無絓礙」），自然證得六波羅。"]', '诗', 'shi', '', NULL, '偈 一 契此 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d045992b-8472-4282-9b97-c94abb1db7d7', '偈 二', '偈 二', 'dc606179-ea05-4193-9992-8e6cd242aab4', '唐', '["我有一布袋，虛空無罣礙。","展（《布袋和尚傳》作「打」）開遍十方，入時觀自在。","。"]', '["我有一布袋，虛空無罣礙。","展（《布袋和尚傳》作「打」）开遍十方，入时观自在。","。"]', '诗', 'shi', '', NULL, '偈 二 契此 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a00451e8-fa00-4ce6-84b5-af2aca97c595', '偈 三', '偈 三', 'dc606179-ea05-4193-9992-8e6cd242aab4', '唐', '["吾有三寶堂，裏空（《明州岳林寺志》作「有」）無色相。","不高亦不低，無遮亦無障。","學者體不如，求者難得樣。","智慧（《布袋和尚傳》作「者」）解安排，千中（《布袋和尚傳》、《明州岳林寺志》作「古」）無一匠。","四門四果生，十方盡供養。"]', '["吾有三寶堂，裏空（《明州岳林寺志》作「有」）無色相。","不高亦不低，無遮亦無障。","学者體不如，求者难得樣。","智慧（《布袋和尚傳》作「者」）解安排，千中（《布袋和尚傳》、《明州岳林寺志》作「古」）無一匠。","四门四果生，十方尽供養。"]', '诗', 'shi', '', NULL, '偈 三 契此 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be2116fb-2e63-409d-bfe6-0b9cfe908e65', '偈 四', '偈 四', 'dc606179-ea05-4193-9992-8e6cd242aab4', '唐', '["吾有一軀佛，世人皆不識。","不塑亦不裝，不雕亦不刻。","無一滴灰泥（《布袋和尚傳》作「無一塊泥土」），無一點彩色。","人畫畫不成。","賊偷偷不得。","體相本自然，清淨非拂拭（《布袋和尚傳》作「常皎潔」）。","雖然是一軀，分身千百億。","（以上四首均見《五燈會元》卷二、《明州定應大師布袋和尚傳》、《明州岳林寺志》〖清戴明琮撰〗卷三。","）。"]', '["吾有一軀佛，世人皆不識。","不塑亦不裝，不雕亦不刻。","無一滴灰泥（《布袋和尚傳》作「無一塊泥土」），無一点彩色。","人畫畫不成。","賊偷偷不得。","體相本自然，清淨非拂拭（《布袋和尚傳》作「常皎潔」）。","雖然是一軀，分身千百億。","（以上四首均见《五灯會元》卷二、《明州定應大師布袋和尚傳》、《明州岳林寺志》〖清戴明琮撰〗卷三。","）。"]', '诗', 'shi', '', NULL, '偈 四 契此 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60634195-17ee-4c1c-948b-b32403ac76a1', '偈 五', '偈 五', 'dc606179-ea05-4193-9992-8e6cd242aab4', '唐', '["[手]（牛）（從《明州岳林寺志》改）捏青苗種福田，低頭便見水中天。","六根清淨方成稻，退步（《明州岳林寺志》作「後」）原來是向前。"]', '["[手]（牛）（從《明州岳林寺志》改）捏青苗種福田，低头便见水中天。","六根清淨方成稻，退步（《明州岳林寺志》作「後」）原来是向前。"]', '诗', 'shi', '', NULL, '偈 五 契此 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d044fd2-b910-4415-a253-1d8173ae0177', '偈 六', '偈 六', 'dc606179-ea05-4193-9992-8e6cd242aab4', '唐', '["由貪淪墮世波中，拾却貪嗔禮大雄。","直截凡情無所得，圓明寂照汝心宗。"]', '["由貪淪墮世波中，拾却貪嗔禮大雄。","直截凡情無所得，圓明寂照汝心宗。"]', '诗', 'shi', '', NULL, '偈 六 契此 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77755e66-4969-4a64-b09a-f6ce017bf934', '偈 七', '偈 七', 'dc606179-ea05-4193-9992-8e6cd242aab4', '唐', '["奔南走北欲何爲？百歲光陰頃刻衰。","自性靈知須急悟，莫教平地陷風雷。"]', '["奔南走北欲何爲？百歲光陰頃刻衰。","自性靈知須急悟，莫教平地陷风雷。"]', '诗', 'shi', '', NULL, '偈 七 契此 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d14fc1b-c364-475a-9b1a-f531cadb9da1', '偈 八', '偈 八', 'dc606179-ea05-4193-9992-8e6cd242aab4', '唐', '["趣利求名空自忙，利名二字陷人坑。","疾須返照娘生面，一片靈心是覺王。"]', '["趣利求名空自忙，利名二字陷人坑。","疾須返照娘生面，一片靈心是覺王。"]', '诗', 'shi', '', NULL, '偈 八 契此 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5089859-5bec-4d0b-ae5f-94efe8342e2a', '偈 九', '偈 九', 'dc606179-ea05-4193-9992-8e6cd242aab4', '唐', '["圓覺靈明超太虛，目前萬物不差殊。","十方法界都包盡，惟有真如也太迂。"]', '["圓覺靈明超太虛，目前万物不差殊。","十方法界都包尽，惟有真如也太迂。"]', '诗', 'shi', '', NULL, '偈 九 契此 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a04bf059-a919-4c7c-ba6d-c642f0406b07', '偈 十', '偈 十', 'dc606179-ea05-4193-9992-8e6cd242aab4', '唐', '["汝心即正（《明州岳林寺志》作「聖」）智，何須問次第。","聖凡都不到，空花映日飛。"]', '["汝心即正（《明州岳林寺志》作「聖」）智，何須问次第。","聖凡都不到，空花映日飞。"]', '诗', 'shi', '', NULL, '偈 十 契此 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4751d321-c48d-4b84-beb5-63b677e166db', '偈 十一', '偈 十一', 'dc606179-ea05-4193-9992-8e6cd242aab4', '唐', '["關非內外絕中央，禪思宏深體大方。"]', '["关非內外絕中央，禪思宏深體大方。"]', '诗', 'shi', '', NULL, '偈 十一 契此 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4df2457-c3aa-48f8-9570-b1b3d5309e32', '偈 十二', '偈 十二', 'dc606179-ea05-4193-9992-8e6cd242aab4', '唐', '["肩挑[日]（明）（從《明州岳林寺志》改）月橫街去，把定乾坤莫放渠。","遇聖遇凡俱坐斷，寂光勝地可安居。"]', '["肩挑[日]（明）（從《明州岳林寺志》改）月橫街去，把定乾坤莫放渠。","遇聖遇凡俱坐斷，寂光勝地可安居。"]', '诗', 'shi', '', NULL, '偈 十二 契此 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f27d687f-bc35-47c7-811a-a5cca5bb784a', '偈 十三', '偈 十三', 'dc606179-ea05-4193-9992-8e6cd242aab4', '唐', '["無生無死佛家風，不墮古今莫定蹤。","觸處圓明常湛寂，龍華雞足兩無從。"]', '["無生無死佛家风，不墮古今莫定蹤。","觸处圓明常湛寂，龙华雞足兩無從。"]', '诗', 'shi', '', NULL, '偈 十三 契此 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('467ceb36-4140-44c1-8408-b777253cfa19', '偈 十四', '偈 十四', 'dc606179-ea05-4193-9992-8e6cd242aab4', '唐', '["碧水映孤峰，寒潭迎皎月。","爾我不知宗，須彌足底越。","。"]', '["碧水映孤峰，寒潭迎皎月。","爾我不知宗，須彌足底越。","。"]', '诗', 'shi', '', NULL, '偈 十四 契此 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f2621db-ef13-45bb-8812-4ad0da20b77b', '偈 十五', '偈 十五', 'dc606179-ea05-4193-9992-8e6cd242aab4', '唐', '["汝水若還清，汝身被水溺。","汝柴若還燥，汝身被火燎。","燎溺病同途，大夢原未覺。","汝能鞭起懸，空靈覺心反。","覆看渠非深，奧神光獨耀。","性真常現成，公案方知道。","便能穩坐毗盧，頂上吹清調。","（以上十一首，均見《卍續藏經》本《明州定應大師布袋和尚傳》附元釋廣如撰《布袋和尚後序》。","除「圓覺靈明超太虛」、「關非內外絕中央」、「汝水若還清」三首外的八首，又見於《明州岳林寺志》卷三。"]', '["汝水若還清，汝身被水溺。","汝柴若還燥，汝身被火燎。","燎溺病同途，大梦原未覺。","汝能鞭起懸，空靈覺心反。","覆看渠非深，奧神光独耀。","性真常現成，公案方知道。","便能穩坐毗盧，頂上吹清調。","（以上十一首，均见《卍續藏經》本《明州定應大師布袋和尚傳》附元釋廣如撰《布袋和尚後序》。","除「圓覺靈明超太虛」、「关非內外絕中央」、「汝水若還清」三首外的八首，又见於《明州岳林寺志》卷三。"]', '诗', 'shi', '', NULL, '偈 十五 契此 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f7e6ebe-0c83-4513-b185-dbc951bbc8ee', '偈 十六', '偈 十六', 'dc606179-ea05-4193-9992-8e6cd242aab4', '唐', '["白屋安貧終暫計，夕陽歸路豈知還？","蓮花佛國深深處，出世芳蹤不可攀。","（《奉化縣補義志》卷三。","）（按：《明州岳林寺志》六卷，奉化戴明琮撰成於康熙二十六年。","《奉化縣補義志》十卷，民國元年蔣堯裳撰。","二書均藏於奉化縣文物室，承張靖龍同志錄示。","）。"]', '["白屋安貧終暫計，夕陽归路豈知還？","蓮花佛国深深处，出世芳蹤不可攀。","（《奉化縣補義志》卷三。","）（按：《明州岳林寺志》六卷，奉化戴明琮撰成於康熙二十六年。","《奉化縣補義志》十卷，民国元年蔣堯裳撰。","二书均藏於奉化縣文物室，承張靖龙同志錄示。","）。"]', '诗', 'shi', '', NULL, '偈 十六 契此 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5731527-dbad-451a-ad24-e17952fedc00', '頌布袋和尚', '頌布袋和尚', '34089fdd-2099-4fee-adec-52b9ce702f56', '唐', '["兜率宮中阿逸多，不離天界降娑婆。","相逢爲我安心訣，萬劫千生一剎那。","（《明州岳林寺志》卷三。","）。"]', '["兜率宮中阿逸多，不離天界降娑婆。","相逢爲我安心訣，万劫千生一剎那。","（《明州岳林寺志》卷三。","）。"]', '诗', 'shi', '', NULL, '頌布袋和尚 蔣宗簡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34c13a86-6ffc-4438-9832-5e317f5b8d9d', '', '', '06913e78-7c99-46c4-aec4-53e4863bdf85', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 薛正明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('994066a9-b4b1-43d8-8249-85bbf2602764', '遊南雁蕩', '游南雁蕩', '06913e78-7c99-46c4-aec4-53e4863bdf85', '唐', '["遐僻山深自晦明，峨峨千態畫難成。","半空高掛龍湫瀑，萬仞宏開金石城。","日射嵐光輕鎖黛，泉飛竹徑細鳴箏。","隱山無路停驂問，拂拂清風兩腋生。","（見周喟《南雁蕩山志》卷七引鄭思恭《崇禎南雁山志》。","）（按：薛正明逸詩及小傳，承張靖龍同志錄示。","）。"]', '["遐僻山深自晦明，峨峨千態畫难成。","半空高掛龙湫瀑，万仞宏开金石城。","日射嵐光轻鎖黛，泉飞竹徑細鳴箏。","隐山無路停驂问，拂拂清风兩腋生。","（见周喟《南雁蕩山志》卷七引鄭思恭《崇禎南雁山志》。","）（按：薛正明逸诗及小傳，承張靖龙同志錄示。","）。"]', '诗', 'shi', '', NULL, '遊南雁蕩 薛正明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67e74460-e7c4-4b9b-b7eb-81f72b898b62', '偈', '偈', '6c84211c-b05a-483b-91e5-e1cef3afd557', '唐', '["雲幽一隻箭，虛空無背面。","射去遍十方，要且無人見。","（《五燈會元》卷六。","）。"]', '["云幽一隻箭，虛空無背面。","射去遍十方，要且無人见。","（《五灯會元》卷六。","）。"]', '诗', 'shi', '', NULL, '偈 重惲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1aff199d-ca05-4b60-9eb5-4a5c02f7dc0d', '遺詩', '遺诗', '95fbb208-2dda-4752-8d51-467dcf322fd8', '唐', '["有箇仙人騎白鶴，曾隨王母到瀛洲。","于今鶴去仙人遠，天際白雲空自浮。","（《槜李詩繫》卷三○。","）。"]', '["有箇仙人騎白鹤，曾隨王母到瀛洲。","于今鹤去仙人远，天際白云空自浮。","（《槜李诗繫》卷三○。","）。"]', '诗', 'shi', '', NULL, '遺詩 錢朗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4af13209-ffaa-4d4f-a07e-0a4291353fa4', '頌', '頌', '60ee4cc8-85bf-4669-bdd7-6222d828aacb', '唐', '["盲聾瘖瘂是仙陀，滿眼時人不柰何。","祇向目前須體妙，身心萬象與森羅。","（《景德傳燈錄》卷二十一、《五燈會元》卷八。","）。"]', '["盲聾瘖瘂是仙陀，满眼时人不柰何。","祇向目前須體妙，身心万象與森羅。","（《景德傳灯錄》卷二十一、《五灯會元》卷八。","）。"]', '诗', 'shi', '', NULL, '頌 重機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dfc798a-b13f-4c05-8fef-74045bec3543', '問諸學流偈', '问諸学流偈', '905de861-9f06-462b-972d-d7310057a9c9', '唐', '["若道法皆如幻有，造諸過惡應無咎。","云何所作業不忘，而藉佛慈興接誘。","（《景德傳燈錄》卷二十一、《五燈會元》卷八。","）。"]', '["若道法皆如幻有，造諸過惡應無咎。","云何所作業不忘，而藉佛慈兴接誘。","（《景德傳灯錄》卷二十一、《五灯會元》卷八。","）。"]', '诗', 'shi', '', NULL, '問諸學流偈 師靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b112ed2a-84f0-41e0-96a5-dfce864c9ad5', '', '', '076d3332-b7e5-490b-a153-f9f4e3c42c88', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 小靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8072158c-1327-4ca8-ab6b-9c4228307885', '答師靜', '答師静', '076d3332-b7e5-490b-a153-f9f4e3c42c88', '唐', '["幻人興幻幻輪圍，幻業能招幻所治。","不了幻生諸幻苦，覺知如幻幻無爲。","（同前。","）。"]', '["幻人兴幻幻輪圍，幻業能招幻所治。","不了幻生諸幻苦，覺知如幻幻無爲。","（同前。","）。"]', '诗', 'shi', '', NULL, '答師靜 小靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de9ee6b3-f1ca-4173-ab91-44b2cbcd1fee', '頌', '頌', '5a478d5f-c4a9-4f40-acf8-bc928623f0ca', '唐', '["虎頭生角人難措，石火電光須密布。","假饒烈士也應難，懵底那能解差（《五燈會元》作「回」）互。","（見《景德傳燈錄》卷二十三、《五燈會元》卷八。","）。"]', '["虎头生角人难措，石火電光須密布。","假饒烈士也應难，懵底那能解差（《五灯會元》作「回」）互。","（见《景德傳灯錄》卷二十三、《五灯會元》卷八。","）。"]', '诗', 'shi', '', NULL, '頌 義昭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfbf0efe-2260-42f2-9bcb-da34efd88974', '於清風樓齋坐久舉目忽覩日光豁然頓曉而有偈', '於清风楼斋坐久舉目忽覩日光豁然頓晓而有偈', 'b29701e2-7375-4306-8703-64ac6590cb92', '唐', '["清風樓上赴官齋，此日平生眼豁開。","方信普通年遠事，不從葱嶺帶將來。"]', '["清风楼上赴官斋，此日平生眼豁开。","方信普通年远事，不從葱嶺带將来。"]', '诗', 'shi', '', NULL, '於清風樓齋坐久舉目忽覩日光豁然頓曉而有偈 師鼐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f2a064b-2007-49fe-996b-939438915ce4', '臨終示偈', '臨終示偈', 'b29701e2-7375-4306-8703-64ac6590cb92', '唐', '["眼光隨色盡，耳識逐聲消。","還源無別旨，今日與明朝。","（均見《五燈會元》卷七。","）。"]', '["眼光隨色尽，耳識逐声消。","還源無別旨，今日與明朝。","（均见《五灯會元》卷七。","）。"]', '诗', 'shi', '', NULL, '臨終示偈 師鼐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ea9674d-a4b0-4bfc-baae-c9a9f29989c9', '三種病人頌', '三種病人頌', 'b29701e2-7375-4306-8703-64ac6590cb92', '唐', '["盲聾喑啞格調高，是何境界自担荷。","昔日曾嚮玄沙道，笑殺張三李四歌。","（見《祖堂集》卷十一。","）。"]', '["盲聾喑啞格調高，是何境界自担荷。","昔日曾嚮玄沙道，笑殺張三李四歌。","（见《祖堂集》卷十一。","）。"]', '诗', 'shi', '', NULL, '三種病人頌 師鼐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('477fdb1d-d234-4302-8a9e-dd875d373601', '浮石寺', '浮石寺', '877437b6-387a-4543-b86a-b3b8c77ee162', '唐', '["灧灧霞光映碧流，潭灣深處有龍湫。","危樓百尺臨江渚，石在波心千古浮。","（見同治十一年刊區作霖纂《餘干縣志》卷十八。","）。"]', '["灧灧霞光映碧流，潭灣深处有龙湫。","危楼百尺臨江渚，石在波心千古浮。","（见同治十一年刊區作霖纂《餘干縣志》卷十八。","）。"]', '诗', 'shi', '', NULL, '浮石寺 錢鏐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc96a5d8-f44f-46b7-970a-a1b237b4a31c', '題羅昭諫新建小樓二絕 一', '題羅昭諫新建小楼二絕 一', '877437b6-387a-4543-b86a-b3b8c77ee162', '唐', '["結構叨憑柱石材，敢期幢蓋此徘徊。","陽春曲調高難和，盡日焚香倚隗臺。"]', '["結構叨憑柱石材，敢期幢蓋此徘徊。","陽春曲調高难和，尽日焚香倚隗台。"]', '诗', 'shi', '', NULL, '題羅昭諫新建小樓二絕 一 錢鏐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b1caa0b-8b8d-40c1-ae59-cbbba75b67ba', '題羅昭諫新建小樓二絕 二', '題羅昭諫新建小楼二絕 二', '877437b6-387a-4543-b86a-b3b8c77ee162', '唐', '["玳簪珠履愧菲材，時凭欄干首重回。","只待淮妖剪除後，別傾巵酒賀行臺。","（清嘉慶刊本《誠應武肅王集》卷四。","）。"]', '["玳簪珠履愧菲材，时凭欄干首重回。","只待淮妖剪除後，別傾巵酒賀行台。","（清嘉慶刊本《誠應武肅王集》卷四。","）。"]', '诗', 'shi', '', NULL, '題羅昭諫新建小樓二絕 二 錢鏐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3910ceec-e0de-4208-9721-b12a0ddb2313', '頌', '頌', '3a1d04ea-035e-47ce-a700-a0c17fb84d1d', '唐', '["一向隨他走，又成我不是。","設爾不與摩，傷著他牽匱。","欲得省要會，二途俱莫綴。","。"]', '["一向隨他走，又成我不是。","設爾不與摩，傷著他牽匱。","欲得省要會，二途俱莫綴。","。"]', '诗', 'shi', '', NULL, '頌 道怤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47312476-0004-404e-b88d-522861c67dad', '答僧問好晴好雨頌（題擬）', '答僧问好晴好雨頌（題擬）', '3a1d04ea-035e-47ce-a700-a0c17fb84d1d', '唐', '["好晴好雨奇行持，若隨語會落今時。","談玄只要塵中妙，得妙還同不惜伊。"]', '["好晴好雨奇行持，若隨語會落今时。","談玄只要塵中妙，得妙還同不惜伊。"]', '诗', 'shi', '', NULL, '答僧問好晴好雨頌（題擬） 道怤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11a36d5e-55b9-4004-8527-8c5b831f9be4', '象骨山頌', '象骨山頌', '3a1d04ea-035e-47ce-a700-a0c17fb84d1d', '唐', '["密密誰知要，明明許也無。","森蘿含本性，山嶽盡如如。"]', '["密密誰知要，明明許也無。","森蘿含本性，山嶽尽如如。"]', '诗', 'shi', '', NULL, '象骨山頌 道怤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc4725f3-2a08-40ed-9e9a-f2d1e41ec064', '答僧問十二時中如何行李頌（題擬）', '答僧问十二时中如何行李頌（題擬）', '3a1d04ea-035e-47ce-a700-a0c17fb84d1d', '唐', '["當此支荷得，勝於歷却（疑應作「劫」）功。","多途終不是，一路妙圓通。"]', '["當此支荷得，勝於歷却（疑應作「劫」）功。","多途終不是，一路妙圓通。"]', '诗', 'shi', '', NULL, '答僧問十二時中如何行李頌（題擬） 道怤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14eb8222-c819-419d-9d01-405c370edda5', '省超偈（題擬）', '省超偈（題擬）', '3a1d04ea-035e-47ce-a700-a0c17fb84d1d', '唐', '["省超之時不守住，更須騰身後前機。","太虛不㝵金烏運，霄漢寧妨玉兔飛。"]', '["省超之时不守住，更須腾身後前機。","太虛不㝵金烏運，霄漢寧妨玉兔飞。"]', '诗', 'shi', '', NULL, '省超偈（題擬） 道怤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52a63b16-4e1d-45b9-971f-63726c116459', '僧乞示入藂林徑直之路答以此頌（題擬）', '僧乞示入藂林徑直之路答以此頌（題擬）', '3a1d04ea-035e-47ce-a700-a0c17fb84d1d', '唐', '["我適抑不已，汝須不當急。","機竪尚虧投，影沒大難及。"]', '["我適抑不已，汝須不當急。","機竪尚虧投，影沒大难及。"]', '诗', 'shi', '', NULL, '僧乞示入藂林徑直之路答以此頌（題擬） 道怤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f23e9197-6e93-4f88-ba11-f4cfb1dff492', '談體頌', '談體頌', '3a1d04ea-035e-47ce-a700-a0c17fb84d1d', '唐', '["體含衆像像分明，離體含形形轉精。","清明妙淨誰能弁，釋迦掩室竭羅城。"]', '["體含衆像像分明，離體含形形轉精。","清明妙淨誰能弁，釋迦掩室竭羅城。"]', '诗', 'shi', '', NULL, '談體頌 道怤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99ed0f91-a7e8-49b8-8839-c7ebf4851ad0', '歎景禪吟', '歎景禪吟', '3a1d04ea-035e-47ce-a700-a0c17fb84d1d', '唐', '["歎汝景禪去何速，雖不同道當眼明。","箇今永却不曾虧，地水火風還故國。","好也好，也大奇，忙忙宇宙幾人知，瑩淨寧閑追路絕，青山綠嶂白雲馳。","歌好歌，笑好笑，誰肯便作此中調。","難提既與君凑機，其肯無不諧其要。","格志異，氣骨高，森蘿咸會一靈毫。","雖然示作皆同電，出岫藏峰徒思勞。","希奇地，劍吹毛，脫罩騰籠任性遊。","此界他界如水月，幾般應跡妙逍遙。"]', '["歎汝景禪去何速，雖不同道當眼明。","箇今永却不曾虧，地水火风還故国。","好也好，也大奇，忙忙宇宙幾人知，瑩淨寧闲追路絕，青山綠嶂白云驰。","歌好歌，笑好笑，誰肯便作此中調。","难提既與君凑機，其肯無不諧其要。","格志異，氣骨高，森蘿咸會一靈毫。","雖然示作皆同電，出岫藏峰徒思勞。","希奇地，劍吹毛，脫罩腾籠任性游。","此界他界如水月，幾般應跡妙逍遙。"]', '诗', 'shi', '', NULL, '歎景禪吟 道怤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25c73935-d1a8-4d71-a8b7-a0f3e1f87a35', '悟玄頌', '悟玄頌', '3a1d04ea-035e-47ce-a700-a0c17fb84d1d', '唐', '["有路省人心，學玄者好尋。","旋機現體骨，何用更沉吟。","莫嫌淺不食，猶勝意思深。","魚若有龍骨，大小盡堪任。","（以上九首均見《祖堂集》卷十。","）。"]', '["有路省人心，学玄者好尋。","旋機現體骨，何用更沉吟。","莫嫌淺不食，猶勝意思深。","鱼若有龙骨，大小尽堪任。","（以上九首均见《祖堂集》卷十。","）。"]', '诗', 'shi', '', NULL, '悟玄頌 道怤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36caff5c-18c5-4af8-84fe-74110cf3b04c', '示後學偈', '示後学偈', 'ef8b9ea3-a388-4e96-82eb-0219c1ae00ce', '唐', '["入門須有語，不語病拪蘆。","應須滿口道，莫教帶有無。"]', '["入门須有語，不語病拪蘆。","應須满口道，莫教带有無。"]', '诗', 'shi', '', NULL, '示後學偈 令參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d04e5d6b-5791-4f1f-86bc-7511f7a79b56', '明照和尚和後再作（題擬）', '明照和尚和後再作（題擬）', 'ef8b9ea3-a388-4e96-82eb-0219c1ae00ce', '唐', '["入門如電拂，後土合知無。","迴頭却問我，終是病拪蘆。"]', '["入门如電拂，後土合知無。","迴头却问我，終是病拪蘆。"]', '诗', 'shi', '', NULL, '明照和尚和後再作（題擬） 令參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bfd92e8-6763-45f1-8e97-27dbd7dc1706', '勸學偈', '勸学偈', 'ef8b9ea3-a388-4e96-82eb-0219c1ae00ce', '唐', '["苦哉甚苦哉，波裏覓乾灰。","勸君收取手，正與摩時倈。","（以上三首均見《祖堂集》卷十。","）。"]', '["苦哉甚苦哉，波裏覓乾灰。","勸君收取手，正與摩时倈。","（以上三首均见《祖堂集》卷十。","）。"]', '诗', 'shi', '', NULL, '勸學偈 令參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c20f52b9-60df-4d93-ae5d-dd5de5cb633c', '偈', '偈', 'cbfbf37c-4a03-4cde-bb66-6265843d6083', '唐', '["蕭然獨處意沉吟，誰信無絃發妙音。","終日法堂惟靜坐，更無人問本來心。","（見《五燈會元》卷八、《全閩詩話》卷十二引《閩書》。","）。"]', '["蕭然独处意沉吟，誰信無絃發妙音。","終日法堂惟静坐，更無人问本来心。","（见《五灯會元》卷八、《全閩诗話》卷十二引《閩书》。","）。"]', '诗', 'shi', '', NULL, '偈 神祿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac4ce0c8-25fb-4bb8-9c76-df32a93e9800', '遊鴈蕩', '游鴈蕩', '9ee0024d-b8bc-4d33-a52c-868b8f1b5342', '唐', '["東風驛路馬蹄香，曉起行春到夕陽。","三月鶯啼花柳寺，幾家人住水雲鄉。","名山不用問樵字，清世何須憂廟廊。","且脫[綸巾]（輪軒）（從《南雁蕩山志》改）隨洞客，紫簫吹月夜天涼。","（見民國十四年符璋等纂《平陽縣志》卷九五。","題下原注：「舊志。","」）（按：元㺷，《平陽縣志》作「元球」。","《十國春秋》卷八三本傳注云：「按《晉高祖實錄》、《十國紀年》作元球、元珦以罪誅，今從《吳越備史》、《九國志》作元㺷。","」今從其說。","張靖龍云：見周喟《南雁蕩山志》卷七引鄭思恭《崇禎南雁山志》。","又見《乾隆平陽縣志》卷二，題作《游雁蕩山詩》，綸巾作輪軒。","）。"]', '["东风驛路马蹄香，晓起行春到夕陽。","三月鶯啼花柳寺，幾家人住水云乡。","名山不用问樵字，清世何須憂廟廊。","且脫[綸巾]（輪軒）（從《南雁蕩山志》改）隨洞客，紫簫吹月夜天涼。","（见民国十四年符璋等纂《平陽縣志》卷九五。","題下原注：「旧志。","」）（按：元㺷，《平陽縣志》作「元球」。","《十国春秋》卷八三本傳注云：「按《晉高祖實錄》、《十国紀年》作元球、元珦以罪誅，今從《吳越備史》、《九国志》作元㺷。","」今從其说。","張靖龙云：见周喟《南雁蕩山志》卷七引鄭思恭《崇禎南雁山志》。","又见《乾隆平陽縣志》卷二，題作《游雁蕩山诗》，綸巾作輪軒。","）。"]', '诗', 'shi', '', NULL, '遊鴈蕩 錢元㺷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b4b9618-83b7-4e62-bb01-cc4b20e8fda5', '索茗題巨觥（題擬）', '索茗題巨觥（題擬）', '504d535e-b48a-4d62-80f4-5359e03f57ac', '唐', '["未見甘心氏，先嘗苦口師。","（見《說郛》卷六一《清異錄》。","）（〖1〗《清異錄》：「光業最耽茗事。","一日，中表請嘗新柑，簪紱叢集。","纔至未顧尊罍，而呼茶甚急。","徑進一巨觥，題詩曰〖詩略〗。","」）。"]', '["未见甘心氏，先嘗苦口師。","（见《说郛》卷六一《清異錄》。","）（〖1〗《清異錄》：「光業最耽茗事。","一日，中表請嘗新柑，簪紱叢集。","纔至未顧尊罍，而呼茶甚急。","徑進一巨觥，題诗曰〖诗略〗。","」）。"]', '诗', 'shi', '', NULL, '索茗題巨觥（題擬） 皮光業 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d290db6e-1f91-40fa-90b9-fb31ea983395', '和麗天和尚頌', '和丽天和尚頌', 'edc8da40-6bf2-4079-999a-bf6ffc00f94b', '唐', '["遍周沙界聖伽藍，觸處文殊共話談。","若有門上覓消息，誰能敢道翠山嵒。","（均見《祖堂集》卷十一。","）。"]', '["遍周沙界聖伽藍，觸处文殊共話談。","若有门上覓消息，誰能敢道翠山嵒。","（均见《祖堂集》卷十一。","）。"]', '诗', 'shi', '', NULL, '和麗天和尚頌 靈照 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b93b98f-5c26-47d2-ad65-8ba979b1117e', '', '', 'a5d5514f-4ce7-4d02-9cf9-7ca439657d05', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 麗天和尚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19fad08a-6666-4032-9a4c-fdabe23ac7bd', '無著對文殊話頌', '無著对文殊話頌', 'a5d5514f-4ce7-4d02-9cf9-7ca439657d05', '唐', '["清涼感現聖伽藍，親對文殊接話談。","言下不通好消息，迴頭祇見翠山嵒。","（同前。","）。"]', '["清涼感現聖伽藍，親对文殊接話談。","言下不通好消息，迴头祇见翠山嵒。","（同前。","）。"]', '诗', 'shi', '', NULL, '無著對文殊話頌 麗天和尚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6f489ec-8467-44d4-81fe-b978f0a928f1', '入古寺作（題擬）', '入古寺作（題擬）', '672a95df-5821-4738-8e5d-08fb19556633', '唐', '["此寺何年造，問僧僧不知。","繫馬枯松下，拂塵讀古碑。","（《祖堂集》卷十一。","）（按：《祖堂集》引靈照語云：「措多入古寺，問僧：『此寺名什摩？","』其僧不知名額，措多遂作一詩曰〖詩略〗。","」疑措多即措大，非人名。","）。"]', '["此寺何年造，问僧僧不知。","繫马枯松下，拂塵读古碑。","（《祖堂集》卷十一。","）（按：《祖堂集》引靈照語云：「措多入古寺，问僧：『此寺名什摩？","』其僧不知名額，措多遂作一诗曰〖诗略〗。","」疑措多即措大，非人名。","）。"]', '诗', 'shi', '', NULL, '入古寺作（題擬） 措多 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ea394cd-b382-4b84-b04c-7f490d612ee3', '游南雁蕩', '游南雁蕩', '238d709f-58e3-4063-b2ee-997bf607eb3d', '唐', '["十年曾作雁山期，今日來看似故知。","好鳥隔林歌侑酒，飛花繞筆索題詩。","雲霞眼底原無物，丘壑胸中似有奇。","蘿月松風清似水，何妨游衍咏歸遲。","（見周喟《南雁蕩山志》卷七引陳玭《嘉靖南雁山志》、鄭思恭《崇禎南雁山志》。","此詩承張靖龍同志錄示。","）。"]', '["十年曾作雁山期，今日来看似故知。","好鸟隔林歌侑酒，飞花繞笔索題诗。","云霞眼底原無物，丘壑胸中似有奇。","蘿月松风清似水，何妨游衍咏归遲。","（见周喟《南雁蕩山志》卷七引陳玭《嘉靖南雁山志》、鄭思恭《崇禎南雁山志》。","此诗承張靖龙同志錄示。","）。"]', '诗', 'shi', '', NULL, '游南雁蕩 錢弘儇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4022a35f-79c9-4e86-96e5-01d564e5ce60', '始遷青溪望吳興故里', '始遷青溪望吳兴故里', 'c4cbdc77-983a-480f-8471-d613c3658bc6', '唐', '["平生願嗣叔庠微，誰識飄零事已非。","霅水遠從雲外隔，澄江獨向月中歸。","煙橫野渡行舟穩，露下衡門步屐稀。","潮夕不通音問杳，故鄉冷落釣魚磯。","（光緒十年刊李詩纂《淳安縣志》卷十五，原署：「周吳黨。","」）。"]', '["平生願嗣叔庠微，誰識飄零事已非。","霅水远從云外隔，澄江独向月中归。","煙橫野渡行舟穩，露下衡门步屐稀。","潮夕不通音问杳，故乡冷落釣鱼磯。","（光緒十年刊李诗纂《淳安縣志》卷十五，原署：「周吳黨。","」）。"]', '诗', 'shi', '', NULL, '始遷青溪望吳興故里 吳黨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fb0f0f3-d828-4bf9-95ac-0a40aa450f68', '偈 一', '偈 一', '1b543cba-095d-4c38-8602-a82e61cfa0af', '唐', '["明招一拍和人希，此是真宗上妙機。","石火瞥然何處去，朝生鳳子合應知。"]', '["明招一拍和人希，此是真宗上妙機。","石火瞥然何处去，朝生鳳子合應知。"]', '诗', 'shi', '', NULL, '偈 一 德謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1f78d7c-abe0-4f41-9f9c-2a18817afd1b', '偈 二', '偈 二', '1b543cba-095d-4c38-8602-a82e61cfa0af', '唐', '["驀刀叢裏逞全威，汝等應當（《五燈會元》作「諸人」）善護持。","火裏鐵牛生犢子，臨歧誰解湊吾機。","（見《景德傳燈錄》卷二十三、《五燈會元》卷八。","）。"]', '["驀刀叢裏逞全威，汝等應當（《五灯會元》作「諸人」）善護持。","火裏鐵牛生犢子，臨歧誰解湊吾機。","（见《景德傳灯錄》卷二十三、《五灯會元》卷八。","）。"]', '诗', 'shi', '', NULL, '偈 二 德謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1945c0a-00cb-4865-baf7-4182aa03c79d', '和翠巖和尚示後學偈', '和翠巖和尚示後学偈', '1b543cba-095d-4c38-8602-a82e61cfa0af', '唐', '["入門通後土，正眼密呈珠。","當機如電拂，方免病拪蘆。","（《祖堂集》卷十，原署明照和尚，「照」應作「招」。","）。"]', '["入门通後土，正眼密呈珠。","當機如電拂，方免病拪蘆。","（《祖堂集》卷十，原署明照和尚，「照」應作「招」。","）。"]', '诗', 'shi', '', NULL, '和翠巖和尚示後學偈 德謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10fcbab8-4181-4793-ac35-13b912b432af', '頌', '頌', 'da09776b-70f5-4654-9326-763fb6672cec', '唐', '["暫下高峰已顯揚，般若圓（《五燈會元》作「圜」）通遍十方。","人天浩浩無差別，法界縱橫處處彰。","（見《景德傳燈錄》卷二十五、《五燈會元》卷十。","）。"]', '["暫下高峰已显揚，般若圓（《五灯會元》作「圜」）通遍十方。","人天浩浩無差別，法界縱橫处处彰。","（见《景德傳灯錄》卷二十五、《五灯會元》卷十。","）。"]', '诗', 'shi', '', NULL, '頌 德韶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0dccdd7-3c91-4041-b3ea-dce0a7fa36bd', '偈', '偈', 'b5d6a5de-af8c-4f70-a862-87fdf13be101', '唐', '["汝問西來意，且過遮（《五燈會元》作「這」）邊立。","昨夜三更時，雨打虛空濕。","電影豁（《五燈會元》作「忽」）然明，不似蚰蜒急。","（見《景德傳燈錄》卷二十六、《五燈會元》卷十。","）。"]', '["汝问西来意，且過遮（《五灯會元》作「這」）邊立。","昨夜三更时，雨打虛空濕。","電影豁（《五灯會元》作「忽」）然明，不似蚰蜒急。","（见《景德傳灯錄》卷二十六、《五灯會元》卷十。","）。"]', '诗', 'shi', '', NULL, '偈 永安 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0461a52-91a9-4916-9608-b441ada35438', '偈', '偈', 'ad47c3d7-ce30-45ae-b853-bdae1a505324', '唐', '["烈士鋒前少人陪，雲雷擊鼓劍輪開。","誰是大雄師子種，滿身鋒刃但出來。","（《景德傳燈錄》卷二四、《五燈會元》卷八。","）。"]', '["烈士鋒前少人陪，云雷擊鼓劍輪开。","誰是大雄師子種，满身鋒刃但出来。","（《景德傳灯錄》卷二四、《五灯會元》卷八。","）。"]', '诗', 'shi', '', NULL, '偈 契從 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02773090-45db-4103-9086-d12bbb713a3c', '頌', '頌', 'c9b6d14c-04d1-4303-ab3c-29675219a555', '唐', '["決在臨鋒處，天然師子機。","嚬呻出三界，非祖莫能知。","（同前。","）。"]', '["決在臨鋒处，天然師子機。","嚬呻出三界，非祖莫能知。","（同前。","）。"]', '诗', 'shi', '', NULL, '頌 瑜禪師 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1531d1fa-20ca-4ed0-87ea-d232e01d63c3', '頌', '頌', 'd78ed56f-4d5b-474e-a844-7d2b7be6c24d', '唐', '["未透徹，不須呈，十方世界廓然明。","孤峰頂上通機照，不用看他北斗星。","（同前。","）。"]', '["未透徹，不須呈，十方世界廓然明。","孤峰頂上通機照，不用看他北斗星。","（同前。","）。"]', '诗', 'shi', '', NULL, '頌 保初 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e028d1d6-feea-437f-97fc-81257bbfb6ca', '贈華山陳希夷', '贈华山陳希夷', '8f5c3ce2-63f5-4495-b7ca-e9a6ac900a4c', '唐', '["□□□□□□□，□□□□□□□。","曾逢毛女話何事，應見巨靈開此山。","濃睡過春花滿地，靜林中夜月當關。","紛紛詔下忽東去，空使蒲輪倦往還。","（《過庭錄》。","）（按：《過庭錄》云此詩爲「文正祖唐公」作，北宋時曾刻石，首聯缺。","《宋詩紀事》卷五誤以作者姓名爲范唐公。","）。"]', '["□□□□□□□，□□□□□□□。","曾逢毛女話何事，應见巨靈开此山。","濃睡過春花满地，静林中夜月當关。","紛紛詔下忽东去，空使蒲輪倦往還。","（《過庭錄》。","）（按：《過庭錄》云此诗爲「文正祖唐公」作，北宋时曾刻石，首聯缺。","《宋诗紀事》卷五誤以作者姓名爲范唐公。","）。"]', '诗', 'shi', '', NULL, '贈華山陳希夷 范贊時 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a7ab35b-8b96-48f3-9083-bd2190867ad4', '句', '句', 'f1a0b890-faca-4395-805a-12ab3ca6ff08', '唐', '["別淚已多紅蠟淚，離盃須滿綠荷盃。","（《兩浙金石志》卷四和凝《大晉故天下兵馬都元帥守尚書令吳越國王諡文穆錢公神道碑》引。","）（〖1〗《錢公神道碑》：「天福六年，王以弟兄歸任，絲竹張筵，因抒嘉篇，久吟警句。","〖詩略〗詩罷酒闌，情傷疾作。","」）。"]', '["別泪已多紅蠟泪，離盃須满綠荷盃。","（《兩浙金石志》卷四和凝《大晉故天下兵马都元帥守尚书令吳越国王諡文穆錢公神道碑》引。","）（〖1〗《錢公神道碑》：「天福六年，王以弟兄归任，絲竹張筵，因抒嘉篇，久吟警句。","〖诗略〗诗罷酒闌，情傷疾作。","」）。"]', '诗', 'shi', '', NULL, '句 錢元瓘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80d68014-d9cf-459b-82a0-e2b206e457b7', '舟中', '舟中', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["一水浮千棹，悠悠來去人。","纜開湘浦岸，帆落楚江濱。","風色東西變，潮痕旦暮新。","只茲澄漢色，幾度化爲塵。"]', '["一水浮千棹，悠悠来去人。","纜开湘浦岸，帆落楚江濱。","风色东西变，潮痕旦暮新。","只茲澄漢色，幾度化爲塵。"]', '诗', 'shi', '', NULL, '舟中 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a2d25c1-74fe-43af-bff9-d62bac5c5c9e', '野游', '野游', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["獨步出衡茅，寒雲著地交。","燒平多敗穴，葉落見危巢。","（見南宋錢唐陳起《增廣聖宋高僧詩選後集》卷中，《南宋羣賢小集》第二十五冊，嘉慶六年石門顧氏讀畫齋刊本。","）。"]', '["独步出衡茅，寒云著地交。","燒平多敗穴，葉落见危巢。","（见南宋錢唐陳起《增廣聖宋高僧诗選後集》卷中，《南宋羣賢小集》第二十五冊，嘉慶六年石门顧氏读畫斋刊本。","）。"]', '诗', 'shi', '', NULL, '野游 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a67ebbd-bfdb-4aeb-b773-a30d03fff69b', '金鷄峯', '金鷄峯', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["松蘿高鎮夏長寒，透出羣峯畫恐難。","造化功成彰五德，洞天雲散露花冠。"]', '["松蘿高鎮夏长寒，透出羣峯畫恐难。","造化功成彰五德，洞天云散露花冠。"]', '诗', 'shi', '', NULL, '金鷄峯 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad244c13-afef-4a8e-b3d1-b7d0377055ae', '蛾眉峯', '蛾眉峯', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["盤空勢險露巖根，深洞聲寒落石泉。","好是雨餘江上見，水雲僧出認西天。"]', '["盤空勢險露巖根，深洞声寒落石泉。","好是雨餘江上见，水云僧出認西天。"]', '诗', 'shi', '', NULL, '蛾眉峯 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58fad443-2c81-439e-8831-9a1284a289ed', '積翠峯', '積翠峯', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["翠壓羣峯地形直，落日猿聲在空碧。","天風吹散斷崖雲，古松長露三秋色。","。"]', '["翠壓羣峯地形直，落日猿声在空碧。","天风吹散斷崖云，古松长露三秋色。","。"]', '诗', 'shi', '', NULL, '積翠峯 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7165181d-a1a1-4fae-acff-cca6e0d3532a', '凌雲峯', '凌云峯', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["煙蘿高巘勢凌雲，影瀉斜陽出海門。","曾與支公探隱去，夜寒雷雨上方聞。"]', '["煙蘿高巘勢凌云，影瀉斜陽出海门。","曾與支公探隐去，夜寒雷雨上方闻。"]', '诗', 'shi', '', NULL, '凌雲峯 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70b94b19-79d5-40e5-bd8f-dae5e93cff40', '白馬峯', '白马峯', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["湖外層峰瀉危樓，天際陰陰長寒木。","南北行人望莫窮，秋雲一片橫幽谷。","（見南宋張淏《寶慶續會稽志》卷四「姜山」條。","《乾隆紹興府志》卷四、《光緒餘姚縣志》卷二亦載此五首詩，字句頗有異同。","）。"]', '["湖外層峰瀉危楼，天際陰陰长寒木。","南北行人望莫窮，秋云一片橫幽谷。","（见南宋張淏《寶慶續會稽志》卷四「姜山」條。","《乾隆紹兴府志》卷四、《光緒餘姚縣志》卷二亦載此五首诗，字句頗有異同。","）。"]', '诗', 'shi', '', NULL, '白馬峯 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf919a31-604b-40ae-a90f-19fced6188cf', '永明山居詩（六十九首） 一', '永明山居诗（六十九首） 一', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["此事從來已絕疑，安然樂道合希夷。","依山偶得還源旨，拂石閑題出格詩。","水待凍開成細溜，薪從霜後拾枯枝。","因茲永斷攀緣意，誓與青松作老期。"]', '["此事從来已絕疑，安然乐道合希夷。","依山偶得還源旨，拂石闲題出格诗。","水待凍开成細溜，薪從霜後拾枯枝。","因茲永斷攀緣意，誓與青松作老期。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 一 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2861e59b-9ad1-4949-852f-56f7b5ad419f', '永明山居詩（六十九首） 二', '永明山居诗（六十九首） 二', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["古樹交盤簇徑深，闃無人到爲難尋。","祇知算計千般事，誰解消停一點心。","凍鎖瀑聲中夜斷，雲吞嶽影半天沈。","寒燈欲絕禪初起，透牖疎風觸短襟。"]', '["古樹交盤簇徑深，闃無人到爲难尋。","祇知算計千般事，誰解消停一点心。","凍鎖瀑声中夜斷，云吞嶽影半天沈。","寒灯欲絕禪初起，透牖疎风觸短襟。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 二 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57892422-223f-4538-9051-1592ce5f3c38', '永明山居詩（六十九首） 三', '永明山居诗（六十九首） 三', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["祇圖閑適樂簞瓢，莫訝煙霞道路遙。","龍穴定知潛碧海，鵬程終是望丹霄。","撥雲巖下來（《古今禪藻集》作「求」）泉脉，嚼草坡邊辨藥苗。","門鎖薜蘿無客至，庵前時有白雲朝。","（按：《古今禪藻集》卷十一收以上二首。","）。"]', '["祇圖闲適乐簞瓢，莫訝煙霞道路遙。","龙穴定知潛碧海，鵬程終是望丹霄。","撥云巖下来（《古今禪藻集》作「求」）泉脉，嚼草坡邊辨藥苗。","门鎖薜蘿無客至，庵前时有白云朝。","（按：《古今禪藻集》卷十一收以上二首。","）。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 三 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03ea8505-78ad-448a-a17c-82fab3b26d9d', '永明山居詩（六十九首） 四', '永明山居诗（六十九首） 四', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["貪生養命事皆同，獨坐閑居意頗慵。","入夏驅馳巢樹鵲，經春勞役探花蜂。","石爐香盡寒灰薄，鐵磬聲微古綉濃。","寂寂虛懷無一念，任從蒼蘚沒行踪。"]', '["貪生養命事皆同，独坐闲居意頗慵。","入夏驱驰巢樹鵲，經春勞役探花蜂。","石爐香尽寒灰薄，鐵磬声微古綉濃。","寂寂虛懷無一念，任從蒼蘚沒行踪。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 四 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aaca8ee-a0df-4ff9-9c8a-293252d10e46', '永明山居詩（六十九首） 五', '永明山居诗（六十九首） 五', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["心地須教合死灰，藏機泯迹絕梯媒。","芳蘭祇爲因香折，良木多從被直摧。","寒逼花枝紅未吐，日融水面綠全開。","支頤獨坐經窗下，一片雲閒入戶來。"]', '["心地須教合死灰，藏機泯迹絕梯媒。","芳蘭祇爲因香折，良木多從被直摧。","寒逼花枝紅未吐，日融水面綠全开。","支頤独坐經窗下，一片云閒入戶来。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 五 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39287f8c-d6f2-4638-869f-0111f3f1f442', '永明山居詩（六十九首） 六', '永明山居诗（六十九首） 六', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["達來何處更追尋，放曠誰論古與今。","風帶泉聲流谷口，雲和山影落潭心。","資身自有衣中寶，濟世誰藏室內金。","策杖偶來林下坐，鳥聲相和唱圓音。"]', '["達来何处更追尋，放曠誰論古與今。","风带泉声流谷口，云和山影落潭心。","資身自有衣中寶，濟世誰藏室內金。","策杖偶来林下坐，鸟声相和唱圓音。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 六 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c591022-b55d-41eb-af3a-adee927a9fab', '永明山居詩（六十九首） 七', '永明山居诗（六十九首） 七', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["事多興廢莫持論，唯有禪宗理可尊。","似訥始平分別路，如愚方塞是非門。","刳腸祇爲生靈智，剖舌多因強語言。","爭似息機高臥客，年來年去道長存。"]', '["事多兴廢莫持論，唯有禪宗理可尊。","似訥始平分別路，如愚方塞是非门。","刳腸祇爲生靈智，剖舌多因強語言。","爭似息機高臥客，年来年去道长存。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 七 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01b94f97-5e13-4e74-b35f-39273e5a9361', '永明山居詩（六十九首） 八', '永明山居诗（六十九首） 八', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["碧嶠經年常寂寂，更無閒事可相於。","超倫每效高僧行，得力難忘古佛書。","落葉亂渠凭水蕩，浮雲翳月倩風除。","方知懶與真空合，一衲閑披憇舊廬。"]', '["碧嶠經年常寂寂，更無閒事可相於。","超倫每效高僧行，得力难忘古佛书。","落葉亂渠凭水蕩，浮云翳月倩风除。","方知懶與真空合，一衲闲披憇旧廬。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 八 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ddd9ab9-ac90-4233-99c4-8e7cf0ba5482', '永明山居詩（六十九首） 九', '永明山居诗（六十九首） 九', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["幽齋獨坐絕參詳，兀爾何如驟世忙。","拯濟終憑宏願力，安閒須得守愚方。","柴門半掩花空落，苔徑虛踪草自荒。","最好靜中無一事，翛然唯得道芽長。"]', '["幽斋独坐絕參詳，兀爾何如驟世忙。","拯濟終憑宏願力，安閒須得守愚方。","柴门半掩花空落，苔徑虛踪草自荒。","最好静中無一事，翛然唯得道芽长。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 九 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('656e2677-3790-486b-9280-20aefa41e85f', '永明山居詩（六十九首） 十', '永明山居诗（六十九首） 十', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["曠然不被興亡墜，豁爾難教寵辱驚。","鼓角城遙無伺候，輪蹄路絕免逢迎。","暖眠紙帳茅堂密，穩坐蒲團石面平。","祇有此途爲上策。","更無餘事可關情。"]', '["曠然不被兴亡墜，豁爾难教寵辱驚。","鼓角城遙無伺候，輪蹄路絕免逢迎。","暖眠紙帳茅堂密，穩坐蒲團石面平。","祇有此途爲上策。","更無餘事可关情。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 十 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0205703c-5075-49bc-a85e-72058ad9b309', '永明山居詩（六十九首） 十一', '永明山居诗（六十九首） 十一', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["觸目堪嗟失路人，坦然王道却迷津。","井藤梗上存餘命，石火光中保幻身。","任老豈知頭頂白，忘緣誰覺世間春？","容顏枯槁元非病。","亭沼消疏不是貧。"]', '["觸目堪嗟失路人，坦然王道却迷津。","井藤梗上存餘命，石火光中保幻身。","任老豈知头頂白，忘緣誰覺世间春？","容顏枯槁元非病。","亭沼消疏不是貧。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 十一 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c827b42-a700-45b3-863f-b65f290bba55', '永明山居詩（六十九首） 十二', '永明山居诗（六十九首） 十二', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["言行相應宜此地，空談大隱也無端。","昇沈歧路非他得，生熟根機且自看。","瞋火微煙還漸息，貪泉餘潤亦消乾。","平生正直須甘取，虛幻門中莫自瞞。"]', '["言行相應宜此地，空談大隐也無端。","昇沈歧路非他得，生熟根機且自看。","瞋火微煙還漸息，貪泉餘潤亦消乾。","平生正直須甘取，虛幻门中莫自瞞。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 十二 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f1950c3-174d-4960-9072-b31193bd9924', '永明山居詩（六十九首） 十三', '永明山居诗（六十九首） 十三', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["怡和心境了然同，大道無私處處通。","舉世豈懷身後慮，誰人暫省事前空。","門開巖石千山月，簾捲溪樓一檻風。","羸體健來知藥力，緣心寂後覺神功。"]', '["怡和心境了然同，大道無私处处通。","舉世豈懷身後慮，誰人暫省事前空。","门开巖石千山月，簾捲溪楼一檻风。","羸體健来知藥力，緣心寂後覺神功。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 十三 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cd9e656-06ac-47c5-80b2-f87550745d8d', '永明山居詩（六十九首） 十四', '永明山居诗（六十九首） 十四', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["進退應須與智論，浮萍自在爲無根。","掃門何太拋途轍，解珮猶能棄渥恩。","草徑旋封迷舊迹，苔階亂織露新痕。","不唯此景供游賞。","無限煙蘿盡一吞。"]', '["進退應須與智論，浮萍自在爲無根。","掃门何太拋途轍，解珮猶能棄渥恩。","草徑旋封迷旧迹，苔階亂织露新痕。","不唯此景供游賞。","無限煙蘿尽一吞。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 十四 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80ba3ef8-5b30-4ba2-b0fa-c37e9c04ce28', '永明山居詩（六十九首） 十五', '永明山居诗（六十九首） 十五', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["塵網休重織是非，冥心何不合玄微。","莊周夢裏多迷旨，惠子漁中少見機。","拶路古松和凍折，盤空枯葉帶霜飛。","一言可達知音者，還得從吾此路歸。"]', '["塵網休重织是非，冥心何不合玄微。","莊周梦裏多迷旨，惠子漁中少见機。","拶路古松和凍折，盤空枯葉带霜飞。","一言可達知音者，還得從吾此路归。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 十五 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98753bae-3daa-4b83-a72c-b405460df45a', '永明山居詩（六十九首） 十六', '永明山居诗（六十九首） 十六', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["抱朴澄神蘊道光，石爐閒爇六時香。","曳空橫野雲和靜，逗石穿崖水自忙。","晚圃雨來葵葉嫩，晴坡燒後蕨苗長。","一心包盡乾坤內，莫把閒文更度量。"]', '["抱朴澄神蘊道光，石爐閒爇六时香。","曳空橫野云和静，逗石穿崖水自忙。","晚圃雨来葵葉嫩，晴坡燒後蕨苗长。","一心包尽乾坤內，莫把閒文更度量。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 十六 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eba88027-e8a3-438c-b43f-ccf04d44c214', '永明山居詩（六十九首） 十七', '永明山居诗（六十九首） 十七', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["松蘿閑鎖一身孤，履道安禪是密謨。","借問野雲誰斷續，思量春草自榮枯。","多見異獸心堪伏，來慣幽禽不用呼。","萬物盡從成熟得，莫教容易喪工夫。"]', '["松蘿闲鎖一身孤，履道安禪是密謨。","借问野云誰斷續，思量春草自榮枯。","多见異獸心堪伏，来慣幽禽不用呼。","万物尽從成熟得，莫教容易喪工夫。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 十七 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7a0b639-1837-48df-bdc3-fc6b2002e023', '永明山居詩（六十九首） 十八', '永明山居诗（六十九首） 十八', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["平生初志已酬之，懷抱怡然寂有歸。","古帙懶開緣得意，幽房長閉爲忘機。","數行鳥陣連雲沒，一帶泉聲隔嶺微。","道合古今渾總是，何須更慮昔年非。"]', '["平生初志已酬之，懷抱怡然寂有归。","古帙懶开緣得意，幽房长閉爲忘機。","數行鸟陣連云沒，一带泉声隔嶺微。","道合古今渾總是，何須更慮昔年非。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 十八 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa78ef0f-5331-41d1-8560-74de9b68dfc7', '永明山居詩（六十九首） 十九', '永明山居诗（六十九首） 十九', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["青山一坐萬緣休，努力應須與古儔。","散誕襟懷因絕趣，消疎活計爲無求。","花明小砌和春月，松暗前軒帶雨秋。","景像自開還自合，怡然何必更忘憂。"]', '["青山一坐万緣休，努力應須與古儔。","散誕襟懷因絕趣，消疎活計爲無求。","花明小砌和春月，松暗前軒带雨秋。","景像自开還自合，怡然何必更忘憂。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 十九 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('741b1e8d-9c9b-461e-b4db-115132481ac5', '永明山居詩（六十九首） 二十', '永明山居诗（六十九首） 二十', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["自甘疎拙懶經營，大道從來戒滿盈。","但起貪心迷有限，誰能觸目悟無生。","雲融遠景危峰小，風戛寒溪野艇橫。","禪後不妨敷六義。","祇圖歌出野人情。"]', '["自甘疎拙懶經營，大道從来戒满盈。","但起貪心迷有限，誰能觸目悟無生。","云融远景危峰小，风戛寒溪野艇橫。","禪後不妨敷六義。","祇圖歌出野人情。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 二十 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('586156c4-03b4-478d-b11b-1152c5b41ad0', '永明山居詩（六十九首） 二十一', '永明山居诗（六十九首） 二十一', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["忙處須閑淡處濃，世情疎後道情通。","了然得旨青冥外，兀爾虛心罔象中。","泉細石根飛不盡，雲濛山脚出無窮。","樵夫釣客雖閑散，未必真棲與我同。"]', '["忙处須闲淡处濃，世情疎後道情通。","了然得旨青冥外，兀爾虛心罔象中。","泉細石根飞不尽，云濛山脚出無窮。","樵夫釣客雖闲散，未必真棲與我同。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 二十一 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c6a3b05-ad48-4615-b3b1-0bc735735cbd', '永明山居詩（六十九首） 二十二', '永明山居诗（六十九首） 二十二', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["且停多事莫矜夸，寂寞門中有道華。","隈嶺靜同猿窟宅，栽松閑共鶴生涯。","榮來只愛添餘錄祿，春過誰能悟落花。","唯有臥雲塵外客，無思無慮老煙霞。"]', '["且停多事莫矜夸，寂寞门中有道华。","隈嶺静同猿窟宅，栽松闲共鹤生涯。","榮来只愛添餘錄祿，春過誰能悟落花。","唯有臥云塵外客，無思無慮老煙霞。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 二十二 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45f20773-14f1-4811-a382-f10b2804ba49', '永明山居詩（六十九首） 二十三', '永明山居诗（六十九首） 二十三', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["沈沈竹院鎖輕煙，淡淡霞光欲曙天，遇境偶吟情自逸，逢人話道意無偏。","古松交處眠青帳，細草濃時坐碧氈。","祇此逍遙何所得，蔬食寒寢度年年。"]', '["沈沈竹院鎖轻煙，淡淡霞光欲曙天，遇境偶吟情自逸，逢人話道意無偏。","古松交处眠青帳，細草濃时坐碧氈。","祇此逍遙何所得，蔬食寒寢度年年。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 二十三 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d47fdce6-83b9-46c9-9254-0813e45af7af', '永明山居詩（六十九首） 二十四', '永明山居诗（六十九首） 二十四', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["危嶺如登百尺樓，千般異景望中收。","浮生但向忙時過，萬事須從靜處休。","道直豈教容鬼怪，理平唯只使魔愁。","空門莫說無知己，滿目松蘿是我儔。"]', '["危嶺如登百尺楼，千般異景望中收。","浮生但向忙时過，万事須從静处休。","道直豈教容鬼怪，理平唯只使魔愁。","空门莫说無知己，满目松蘿是我儔。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 二十四 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f09bc48-c876-4acf-a597-c90c7184df60', '永明山居詩（六十九首） 二十五', '永明山居诗（六十九首） 二十五', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["巨浸層巒本自平，只緣人世強分明。","五侯門外悲歡意，長樂坡頭去住情。","學道不如忘有念，修身爭是了無生。","三祗功業猶難及，誰信塵勞直下明。"]', '["巨浸層巒本自平，只緣人世強分明。","五侯门外悲歡意，长乐坡头去住情。","学道不如忘有念，修身爭是了無生。","三祗功業猶难及，誰信塵勞直下明。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 二十五 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfd2c548-ae3f-41d2-8d69-a542f30391ff', '永明山居詩（六十九首） 二十六', '永明山居诗（六十九首） 二十六', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["霧鎖煙霾宴寂堂，含虛凝綠水雲鄉。","搜玄偈裏真風遠，招隱詩中野思長。","真柏最宜堆厚雪。","危花終怯下輕霜。","滔滔一點無依處，舉足方知盡道場。"]', '["霧鎖煙霾宴寂堂，含虛凝綠水云乡。","搜玄偈裏真风远，招隐诗中野思长。","真柏最宜堆厚雪。","危花終怯下轻霜。","滔滔一点無依处，舉足方知尽道場。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 二十六 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b82e758c-8d21-4606-b717-081b983b2c5e', '永明山居詩（六十九首） 二十七', '永明山居诗（六十九首） 二十七', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["投足煙巒養病軀，馳求終是用工夫。","千般有作皆從智，萬種無依自合愚。","意地已拋塵事業，心田唯種稻根株。","非時免見干人世，野食山袍自有謨。"]', '["投足煙巒養病軀，驰求終是用工夫。","千般有作皆從智，万種無依自合愚。","意地已拋塵事業，心田唯種稻根株。","非时免见干人世，野食山袍自有謨。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 二十七 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74fb9b4d-3281-408a-a099-4d10b06f681a', '永明山居詩（六十九首） 二十八', '永明山居诗（六十九首） 二十八', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["急景韶顏不可追，豈堪迴首暫思之。","浮雲已斷平生望，高節須存往日期。","庭樹任猿偷熟果，崖松停鶴惜高枝。"]', '["急景韶顏不可追，豈堪迴首暫思之。","浮云已斷平生望，高節須存往日期。","庭樹任猿偷熟果，崖松停鹤惜高枝。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 二十八 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('323bc192-d517-46b2-a626-3ec5ba001365', '永明山居詩（六十九首） 二十九', '永明山居诗（六十九首） 二十九', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["幽棲豈可事徒然，晝諷《蓮經》夜坐禪。","吟裏有聲皆實相，定中無境不虛玄。","直教似月臨千界，還遣如空度萬緣。","從此必知宏此志，免教虛擲愧前賢。"]', '["幽棲豈可事徒然，晝諷《蓮經》夜坐禪。","吟裏有声皆實相，定中無境不虛玄。","直教似月臨千界，還遣如空度万緣。","從此必知宏此志，免教虛擲愧前賢。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 二十九 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcf68588-3c6a-4b3c-814d-0792cf778ae4', '永明山居詩（六十九首） 三十', '永明山居诗（六十九首） 三十', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["何如深谷一遺人，宴坐經行不累身。","廢宅可嗟頻換主，凋叢愁見幾回春。","尖尖石笑煙籠碧，點點苔錢雨洗新。","堪笑古人非我意，居山多是避強秦。"]', '["何如深谷一遺人，宴坐經行不累身。","廢宅可嗟頻換主，凋叢愁见幾回春。","尖尖石笑煙籠碧，点点苔錢雨洗新。","堪笑古人非我意，居山多是避強秦。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 三十 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bcddb2a-b3f1-48de-bf40-1bfa66ef3064', '永明山居詩（六十九首） 三十一', '永明山居诗（六十九首） 三十一', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["有山有水更何憂，知足能令萬事休。","大道不從心外得，浮榮須向世間求。","冲開煙縷飛黃鳥，點破潭心漾白鷗。","好景盡歸余掌握，豈勞艱險訪瀛洲。"]', '["有山有水更何憂，知足能令万事休。","大道不從心外得，浮榮須向世间求。","冲开煙縷飞黄鸟，点破潭心漾白鷗。","好景尽归余掌握，豈勞艱險訪瀛洲。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 三十一 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2611200b-6e89-4d9c-bee9-f3f2ac485698', '永明山居詩（六十九首） 三十二', '永明山居诗（六十九首） 三十二', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["萬事從來祇自招，安危由己路非遙。","笙歌韻裏花先落，松檜枝間雲未消。","數下磬聲孤月夜，一爐香翥白雲朝。","誰人會我高棲意，門掩空庭思寂寥。"]', '["万事從来祇自招，安危由己路非遙。","笙歌韻裏花先落，松檜枝间云未消。","數下磬声孤月夜，一爐香翥白云朝。","誰人會我高棲意，门掩空庭思寂寥。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 三十二 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2dd5833-acb1-49fa-9c6d-c79cbc3332f3', '永明山居詩（六十九首） 三十三', '永明山居诗（六十九首） 三十三', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["萬象從來一徑通，但緣分別便西東。","遺簪祇爲情難盡，泣路方知意無窮。","偃仰不拋青嶂裏，往來多在白雲中。","平生分野應難比，澗飲林棲得古風。"]', '["万象從来一徑通，但緣分別便西东。","遺簪祇爲情难尽，泣路方知意無窮。","偃仰不拋青嶂裏，往来多在白云中。","平生分野應难比，澗饮林棲得古风。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 三十三 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('730079f2-718e-4e6e-bda2-85c2d3838ca6', '永明山居詩（六十九首） 三十四', '永明山居诗（六十九首） 三十四', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["遁逸從來格自高，莫將泰山比秋毫。","冷煙寒月真吾侶，瘦竹蒼松是我曹。","霜樹葉疎幽徑出，雲泉聲急曉風高。","唯當話道閑吟外，時得功夫補毳袍。"]', '["遁逸從来格自高，莫將泰山比秋毫。","冷煙寒月真吾侶，瘦竹蒼松是我曹。","霜樹葉疎幽徑出，云泉声急晓风高。","唯當話道闲吟外，时得功夫補毳袍。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 三十四 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc82021d-2b88-43e8-8f77-8f8010eea992', '永明山居詩（六十九首） 三十五', '永明山居诗（六十九首） 三十五', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["任運騰騰無所依，閑游長坐性怡怡。","疎林不遣閑人到，密意多應夜月知。","驟雨過時苔路滑，撥雲行處石橋危。","塵沙劫盡清風在，何假虛名上古碑。"]', '["任運腾腾無所依，闲游长坐性怡怡。","疎林不遣闲人到，密意多應夜月知。","驟雨過时苔路滑，撥云行处石橋危。","塵沙劫尽清风在，何假虛名上古碑。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 三十五 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8477f59-8f59-40df-9f45-c03e1fa27f95', '永明山居詩（六十九首） 三十六', '永明山居诗（六十九首） 三十六', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["抱拙藏鋒過暮年，高名何必指前賢。","祇於心上標空界，誰說壺中別有天。","鬱密遠林停宿霧，蕭騷疎竹掃寒煙。","從茲不更移瓶錫，身外無餘意了然。"]', '["抱拙藏鋒過暮年，高名何必指前賢。","祇於心上標空界，誰说壺中別有天。","鬱密远林停宿霧，蕭騷疎竹掃寒煙。","從茲不更移瓶錫，身外無餘意了然。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 三十六 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d849221c-b360-44ac-a964-4659a06810f1', '永明山居詩（六十九首） 三十七', '永明山居诗（六十九首） 三十七', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["息業怡神道最孤，藏名匿跡合良圖。","冥心難使龍神見，出語須教海岳枯。","雲駐庵前疑有意，鳥鳴庭際似相呼。","資持隨分安排了，最急應須與道俱。"]', '["息業怡神道最孤，藏名匿跡合良圖。","冥心难使龙神见，出語須教海岳枯。","云駐庵前疑有意，鸟鳴庭際似相呼。","資持隨分安排了，最急應須與道俱。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 三十七 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06d3a012-113f-4c6f-8f66-c27f9bc070d1', '永明山居詩（六十九首） 三十八', '永明山居诗（六十九首） 三十八', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["松陰疎冷罩寒門，靜見吾宗已絕倫。","驅得萬途歸理窟，更無一事出心源。","煙雲忽閉岩前洞，鷄犬時聞林下村。","放曠本來無別意，免教停海起波痕。"]', '["松陰疎冷罩寒门，静见吾宗已絕倫。","驱得万途归理窟，更無一事出心源。","煙云忽閉岩前洞，鷄犬时闻林下村。","放曠本来無別意，免教停海起波痕。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 三十八 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40428ee4-41f6-4353-8ad6-c7b8f00dc421', '永明山居詩（六十九首） 三十九', '永明山居诗（六十九首） 三十九', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["景虛情淡兩何依，抱一冥真絕萬機。","松韻餘風涼竹戶，柏搖殘露濕禪衣。","巖燈霧逼寒光小，石像塵昏古畫微。","得趣了然無所慮。","任緣終日送斜暉。"]', '["景虛情淡兩何依，抱一冥真絕万機。","松韻餘风涼竹戶，柏搖殘露濕禪衣。","巖灯霧逼寒光小，石像塵昏古畫微。","得趣了然無所慮。","任緣終日送斜暉。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 三十九 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7970eb1a-7ae1-4ceb-874a-e97086883075', '永明山居詩（六十九首） 四十', '永明山居诗（六十九首） 四十', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["遁迹無圖匿姓名，萬重山後葺茅亭。","隨情因事搜新偈，探妙窮微閱古經。","與道交時心絕念。","從緣感處物通靈。","應須長遠存高節。","屹屹喬松老更青。"]', '["遁迹無圖匿姓名，万重山後葺茅亭。","隨情因事搜新偈，探妙窮微閱古經。","與道交时心絕念。","從緣感处物通靈。","應須长远存高節。","屹屹喬松老更青。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 四十 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a907d7d-f930-421e-8735-3476bddef4f0', '永明山居詩（六十九首） 四十一', '永明山居诗（六十九首） 四十一', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["閑思塵世大悠哉，進趣門中盡可該。","拋却工夫平世路，枉勞心力構仙臺。","隘空雲水千重合，匝野煙霞一徑開。","幸有圓成平坦處，辛勤誰解望山來。"]', '["闲思塵世大悠哉，進趣门中尽可該。","拋却工夫平世路，枉勞心力構仙台。","隘空云水千重合，匝野煙霞一徑开。","幸有圓成平坦处，辛勤誰解望山来。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 四十一 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7942ddcf-1e1d-469f-83ec-b2dd5008c2fe', '永明山居詩（六十九首） 四十二', '永明山居诗（六十九首） 四十二', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["千途盡向空源出，萬景終歸一路通。","忽爾有心成大患，坦然無事却全功。","春開小岫調新綠，水漾漂霞蘸晚紅。","莫道境緣能幻惑，達來何處不消融。"]', '["千途尽向空源出，万景終归一路通。","忽爾有心成大患，坦然無事却全功。","春开小岫調新綠，水漾漂霞蘸晚紅。","莫道境緣能幻惑，達来何处不消融。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 四十二 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a92237cd-1543-4020-9353-daa5cbbeca9a', '永明山居詩（六十九首） 四十三', '永明山居诗（六十九首） 四十三', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["身心閑後思怡然，緬想難忘契道言。","千種却教歸淡薄，萬般須是到根源。","疎疎雨趁歸巢鳥，密密煙藏抱子猿。","禪罷吟來無一事，遠山驅景入茅軒。"]', '["身心闲後思怡然，緬想难忘契道言。","千種却教归淡薄，万般須是到根源。","疎疎雨趁归巢鸟，密密煙藏抱子猿。","禪罷吟来無一事，远山驱景入茅軒。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 四十三 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed1cf69a-6c27-45f0-8cdd-e6693e80955e', '永明山居詩（六十九首） 四十四', '永明山居诗（六十九首） 四十四', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["萬境閑來情淡淡，羣囂息後思微微。","當時白業無門入，今日玄關有路歸。","熟果不搖翻自落，生禽誰喚却驚飛。","到頭何用空忙得，任運應須待對機。"]', '["万境闲来情淡淡，羣囂息後思微微。","當时白業無门入，今日玄关有路归。","熟果不搖翻自落，生禽誰喚却驚飞。","到头何用空忙得，任運應須待对機。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 四十四 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33adf737-745a-448c-84ec-d560250464cc', '永明山居詩（六十九首） 四十五', '永明山居诗（六十九首） 四十五', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["擕筇閑步望山行，竟日逍遙任野情。","上嶺梯登危石側，渡溪橋踏古槎橫。","綠羅水皺巖根急，紅錦霞舒海面明。","一軸咏懷高尚意，援毫因事偶吟成。"]', '["擕筇闲步望山行，竟日逍遙任野情。","上嶺梯登危石側，渡溪橋踏古槎橫。","綠羅水皺巖根急，紅錦霞舒海面明。","一軸咏懷高尚意，援毫因事偶吟成。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 四十五 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95405dfc-9882-4ee0-b52f-97cd4422d6e4', '永明山居詩（六十九首） 四十六', '永明山居诗（六十九首） 四十六', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["負氣爭權事可悲，金貂綉轂盡何之。","唯聞野棘盤荒冢，祇見空陵疊壞碑，燈暗竹堂行道夜，煙昏石窟坐禪時，怡然自得真棲處，何用經營別路歧。"]', '["負氣爭權事可悲，金貂綉轂尽何之。","唯闻野棘盤荒冢，祇见空陵叠壞碑，灯暗竹堂行道夜，煙昏石窟坐禪时，怡然自得真棲处，何用經營別路歧。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 四十六 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a51e8d2-b22a-435f-9ce7-d2efb728161f', '永明山居詩（六十九首） 四十七', '永明山居诗（六十九首） 四十七', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["豪貴從他縱勝游，多歡終是復多愁。","茅茨舍宇偏安穩，糞掃衣裳最自由。","數片雲飛書案上，一條泉路臥床頭。","分明自有安身處，爭奈人間不肯休。"]', '["豪貴從他縱勝游，多歡終是复多愁。","茅茨舍宇偏安穩，糞掃衣裳最自由。","數片云飞书案上，一條泉路臥床头。","分明自有安身处，爭奈人间不肯休。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 四十七 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b8e3406-309e-447e-87ae-fb1d30a8b56d', '永明山居詩（六十九首） 四十八', '永明山居诗（六十九首） 四十八', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["高才宏略氣凌雲，世上浮名夢裏身。","蘇氏謾稱降六國，韓公休說捲三秦。","當朝雖立千年事，古廟唯存一聚塵。","畢竟思量渾大錯，何如林下養天真。"]', '["高才宏略氣凌云，世上浮名梦裏身。","蘇氏謾稱降六国，韓公休说捲三秦。","當朝雖立千年事，古廟唯存一聚塵。","畢竟思量渾大錯，何如林下養天真。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 四十八 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('092f8efd-b7f1-426a-a1ad-7b5476e8696e', '永明山居詩（六十九首） 四十九', '永明山居诗（六十九首） 四十九', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["高懷怡淡景相和，才到塵途事便多。","碧嶂好期長定計，朱門唯見暫時過。","雄雄負氣爭權路，岌岌新墳占野坡。","成敗分明剛不悟，未知凡俗意如何。"]', '["高懷怡淡景相和，才到塵途事便多。","碧嶂好期长定計，朱门唯见暫时過。","雄雄負氣爭權路，岌岌新墳占野坡。","成敗分明剛不悟，未知凡俗意如何。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 四十九 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7f9157a-998a-467d-bc35-00a4bc8d7a1d', '永明山居詩（六十九首） 五十', '永明山居诗（六十九首） 五十', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["得理元來行自成，萬般情斷一心冥。","樵人不到緣山僻，游客難逢爲嶽靈。","食蘖苦心何日就，看花醉眼幾時醒。","索然身外無餘物，雲滿前山水滿瓶。"]', '["得理元来行自成，万般情斷一心冥。","樵人不到緣山僻，游客难逢爲嶽靈。","食蘖苦心何日就，看花醉眼幾时醒。","索然身外無餘物，云满前山水满瓶。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 五十 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c60a659e-dbeb-4e98-b71b-4b00954ba932', '永明山居詩（六十九首） 五十一', '永明山居诗（六十九首） 五十一', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["名利梯媒事已忘，唯憑拙直定行藏。","探玄休煉長生藥，助道時抄歇食方。","溪汲古痕山雨漲，樹摧殘枿野風狂。","一言欲寄休迴首。","塵路如今事正忙。"]', '["名利梯媒事已忘，唯憑拙直定行藏。","探玄休煉长生藥，助道时抄歇食方。","溪汲古痕山雨漲，樹摧殘枿野风狂。","一言欲寄休迴首。","塵路如今事正忙。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 五十一 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbc1a70a-2986-40c0-a885-e875dcbd194e', '永明山居詩（六十九首） 五十二', '永明山居诗（六十九首） 五十二', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["豈是疎慵僻愛山，且圖餘事不相關。","休誇鳳詔千年貴，難敵禪扉半日閒。","透水戲魚隨浪沒，投巢孤鶴帶雲還。","自然得到無心地，寂寂虛堂一景閒。"]', '["豈是疎慵僻愛山，且圖餘事不相关。","休誇鳳詔千年貴，难敵禪扉半日閒。","透水戲鱼隨浪沒，投巢孤鹤带云還。","自然得到無心地，寂寂虛堂一景閒。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 五十二 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75d5c5e4-26d0-4ec8-91ef-b3f7fa0da727', '永明山居詩（六十九首） 五十三', '永明山居诗（六十九首） 五十三', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["林下安身別有方，營營何太路歧忙。","侯門夢過光陰促，禪室玄棲氣味長。","引水灌花春日媚，移林夾道暑天涼。","銜恩略報元功處，一炷晨風散後香。"]', '["林下安身別有方，營營何太路歧忙。","侯门梦過光陰促，禪室玄棲氣味长。","引水灌花春日媚，移林夾道暑天涼。","銜恩略報元功处，一炷晨风散後香。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 五十三 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4095b01-81c9-45a0-96be-8563428476cf', '永明山居詩（六十九首） 五十四', '永明山居诗（六十九首） 五十四', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["萬般惟道最堪依，一瞬榮枯萬古悲。","強笑低顏何忽忽，忘機絕慮自怡怡。","潛龍終要投深浦，巢鳥應須占健枝。","名利門中難立足，隱藏雲水更何之。"]', '["万般惟道最堪依，一瞬榮枯万古悲。","強笑低顏何忽忽，忘機絕慮自怡怡。","潛龙終要投深浦，巢鸟應須占健枝。","名利门中难立足，隐藏云水更何之。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 五十四 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee86a16e-c22d-4d8b-b8e8-22ba0c750ce3', '永明山居詩（六十九首） 五十五', '永明山居诗（六十九首） 五十五', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["退迹何人繼昔賢，凡途終是事謀先。","只知兢逐浮雲富，誰解驚嗟逝水年。","寒影半疎霜後樹，秋聲萬點雨中禪。","千般不更經營得，一榻無餘任自然。"]', '["退迹何人繼昔賢，凡途終是事謀先。","只知兢逐浮云富，誰解驚嗟逝水年。","寒影半疎霜後樹，秋声万点雨中禪。","千般不更經營得，一榻無餘任自然。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 五十五 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('159c8692-f4f9-4b09-ba8c-d5950bc6420d', '永明山居詩（六十九首） 五十六', '永明山居诗（六十九首） 五十六', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["野景陶情皆得意，凡夫舉目盡堪愁。","秦川幾度埋番骨，棘路還曾聳玉樓。","幻體不知波上沫，狂心須認鏡中頭。","浮生役役貪榮者，求到真空卒未休。"]', '["野景陶情皆得意，凡夫舉目尽堪愁。","秦川幾度埋番骨，棘路還曾聳玉楼。","幻體不知波上沫，狂心須認镜中头。","浮生役役貪榮者，求到真空卒未休。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 五十六 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e92ac1ac-1b67-441c-ad59-5b5870250c6f', '永明山居詩（六十九首） 五十七', '永明山居诗（六十九首） 五十七', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["一生占斷白雲鄉，適意孤高志自強。","報曉音聲棲鳥語，漏春消息早梅香。","吟經徐傍芙蕖岸，得偈閑書薜荔墻。","大道最親無達者，苦擕瓶錫叩禪堂。"]', '["一生占斷白云乡，適意孤高志自強。","報晓音声棲鸟語，漏春消息早梅香。","吟經徐傍芙蕖岸，得偈闲书薜荔墻。","大道最親無達者，苦擕瓶錫叩禪堂。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 五十七 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed445939-2c19-4d40-b810-2372c06343a0', '永明山居詩（六十九首） 五十八', '永明山居诗（六十九首） 五十八', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["養性攄情不記年，免尋雲水更參禪。","有心用處還應錯，無意看時却宛然。","析法尚嫌灰斷果，燒丹堪愍地行仙。","欲知此理誰人會，水自朝東月自圓。"]', '["養性攄情不記年，免尋云水更參禪。","有心用处還應錯，無意看时却宛然。","析法尚嫌灰斷果，燒丹堪愍地行仙。","欲知此理誰人會，水自朝东月自圓。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 五十八 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('466773dc-154e-4eb8-896e-f486bfe06cd6', '永明山居詩（六十九首） 五十九', '永明山居诗（六十九首） 五十九', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["世途從此免相關，萬慮潛消野思閑。","庵樹逼春花自吐，巖巢欲暮鳥空還。","門前霧閉疑無路，檻外雲開忽有山。","宴坐石巖樵徑絕，姓名應不到人間。"]', '["世途從此免相关，万慮潛消野思闲。","庵樹逼春花自吐，巖巢欲暮鸟空還。","门前霧閉疑無路，檻外云开忽有山。","宴坐石巖樵徑絕，姓名應不到人间。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 五十九 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7f6dbe3-1142-408b-b1b2-be122007194e', '永明山居詩（六十九首） 六十', '永明山居诗（六十九首） 六十', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["獨行獨坐任天然，幽隱難逢世網牽。","一志直教齊大道，萬般總是涉因緣。","水磨澗石平如鏡，春引巖藤直似弦。","虛幻已知休更續，蹄輪應不到山前。"]', '["独行独坐任天然，幽隐难逢世網牽。","一志直教齊大道，万般總是涉因緣。","水磨澗石平如镜，春引巖藤直似弦。","虛幻已知休更續，蹄輪應不到山前。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 六十 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e41570a-9d95-4b14-bf1a-42cc63d986a6', '永明山居詩（六十九首） 六十一', '永明山居诗（六十九首） 六十一', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["散誕疎狂得自然，免教拘迫事相牽。","潛龍不離滔滔水，孤鶴唯宜遠遠天。","透室寒光松檻月，逼人凉氣石渠泉。","非吾獨了西來意，竹祖桐孫盡入玄。"]', '["散誕疎狂得自然，免教拘迫事相牽。","潛龙不離滔滔水，孤鹤唯宜远远天。","透室寒光松檻月，逼人凉氣石渠泉。","非吾独了西来意，竹祖桐孫尽入玄。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 六十一 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2abf200e-aa98-420a-b5d8-ee6b5a31ae87', '永明山居詩（六十九首） 六十二', '永明山居诗（六十九首） 六十二', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["綠柳堤邊春色多，數樹重重裊翠蘿。","紅白花枝爭鬬發，晴陰天氣半相和。","中山謾醉千壺酒，易水徒悲一曲歌。","塵世無憑唯道外，榮枯瞬息盡消磨。"]', '["綠柳堤邊春色多，數樹重重裊翠蘿。","紅白花枝爭鬬發，晴陰天氣半相和。","中山謾醉千壺酒，易水徒悲一曲歌。","塵世無憑唯道外，榮枯瞬息尽消磨。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 六十二 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aaa0380b-4c34-410d-ad88-2cc2d22d317a', '永明山居詩（六十九首） 六十三', '永明山居诗（六十九首） 六十三', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["清平大業行皆奢，豈獨堯時聽所加。","豐儉由人天不遠，安危在智道非賒。","關津防害反爲害，法令除邪却長邪。","爭似無言敷密化，既能成國又成家。"]', '["清平大業行皆奢，豈独堯时听所加。","豐儉由人天不远，安危在智道非賒。","关津防害反爲害，法令除邪却长邪。","爭似無言敷密化，既能成国又成家。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 六十三 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6dcd21b3-bf07-4a9f-a1b2-aea66e0d6d21', '永明山居詩（六十九首） 六十四', '永明山居诗（六十九首） 六十四', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["焦翼枯鱗成底事，分明可驗莫愁哉。","君恩只可量功受，世利應須任運來。","豈信敗從成處得，誰知榮是辱邊媒。","但看越分誅求者，唯向身邊積禍胎。"]', '["焦翼枯鱗成底事，分明可驗莫愁哉。","君恩只可量功受，世利應須任運来。","豈信敗從成处得，誰知榮是辱邊媒。","但看越分誅求者，唯向身邊積禍胎。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 六十四 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40bdb028-73b7-4c87-acac-4cbaa35a63fb', '永明山居詩（六十九首） 六十五', '永明山居诗（六十九首） 六十五', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["棲真境界太玄鄉，靜見吾宗不可量。","好句只凭詩斷送，閑緣唯遣道消亡。","雨絲雲織輕條密，煙素風抽細縷長。","竟日虛懷無一事，金瓶秋水石爐香。"]', '["棲真境界太玄乡，静见吾宗不可量。","好句只凭诗斷送，闲緣唯遣道消亡。","雨絲云织轻條密，煙素风抽細縷长。","竟日虛懷無一事，金瓶秋水石爐香。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 六十五 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a70da201-c1cd-4ee0-83fa-5efbff7a70b7', '永明山居詩（六十九首） 六十六', '永明山居诗（六十九首） 六十六', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["得喪從來事甚均，任緣徒用苦勞神。","野蔬隨分堪充口，石室依稀可庇身。","碧海幾時無去棹，紅衢何日息征輪。","若教求道如求利，舉世渾成無事人。"]', '["得喪從来事甚均，任緣徒用苦勞神。","野蔬隨分堪充口，石室依稀可庇身。","碧海幾时無去棹，紅衢何日息征輪。","若教求道如求利，舉世渾成無事人。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 六十六 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a337703-7bf3-43c7-ad11-f4ed0c3cb025', '永明山居詩（六十九首） 六十七', '永明山居诗（六十九首） 六十七', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["數朝興廢狂風過，千載榮枯掣電飛，早向權門思息意，莫於塵世自沈機。","一條水引閑花出，萬里雲隨獨鶴歸。","最要身安成大道，免教他後始知非。"]', '["數朝兴廢狂风過，千載榮枯掣電飞，早向權门思息意，莫於塵世自沈機。","一條水引闲花出，万里云隨独鹤归。","最要身安成大道，免教他後始知非。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 六十七 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da47d0f0-8c20-410e-a62e-e3078663b064', '永明山居詩（六十九首） 六十八', '永明山居诗（六十九首） 六十八', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["幽棲帶郭半山峰，密意虛懷莫可同。","事到定中消息靜，景於吟處煉磨空。","玲瓏色淡松根月，敲磕聲清竹罅風。","獨坐獨行誰會我，羣星朝北水朝東。"]', '["幽棲带郭半山峰，密意虛懷莫可同。","事到定中消息静，景於吟处煉磨空。","玲瓏色淡松根月，敲磕声清竹罅风。","独坐独行誰會我，羣星朝北水朝东。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 六十八 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('036c0045-3116-4c82-ac11-2b71804e09fd', '永明山居詩（六十九首） 六十九', '永明山居诗（六十九首） 六十九', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["三度曾經游此地，從緣權順世間情。","登山雖有謝安志，遁迹慚無慧遠名。","翠疊寒枝松未老，影深幽徑竹新成。","莫言去住關懷抱，雲本無心水自清。","（見懺庵居士《高僧山居詩》，上海商務印書館民國二十三年綫裝鉛印本。","）（〖1〗張靖龍云：永明即延壽。","清釋際祥《淨慈寺志》〖《武林掌故叢編》第十三集〗卷十九附著述目中有「《永明壽禪師山居詩》，吳越僧延壽撰」等語。","卷十八明人李日華山居詩序中記載了永明山居詩的刻本來源，序後附錄佛國山人黃樹穀《集山居詩絕句》十首。","旁小字注曰：「集永明壽禪師詩句。","」其詞句與懺庵居士本全部相同。","集句詩後附載和詩諸公云，高峰妙法嗣布衲雍公，嘗居南屏，賡和《永明山居詩》六十九首，楚石梵琦有《和永明山居詩》，梅雪有《和永明山居詩》。","古春云：「永明壽禪師有詩六十九首，慶壽獨庵從和之。","」按元代天目山大覺正等寺布衲祖雍的和作，今存其一，見《西天目祖山志》卷五，步延壽山居詩其二韻。","又懺庵居士《高僧山居詩續編》載元代天台高僧無見先覩《和永明禪師〖山居詩〗韻》六十九首，步韻甚嚴。","從永明山居詩的內容來看，也屬智覺延壽所作無疑。","詳細考證參見拙作《延壽及其佚詩》，載《溫州師專學報》〖社會科學版〗一九八六年第三期。","按：日本《續藏經》本宋釋文沖《慧日永明寺智覺禪師自行錄》末附延壽著作總目，有《山居詩》一卷，當即指以上所錄諸詩。","此書所錄延壽所作詩尚有《詩讚》一卷、《物外集》十卷五百首、《吳越唱和詩》一卷、《光明會瑞應詩》一卷、《供養石橋羅漢一十會祥瑞詩》一卷、《雜歌》一卷、《布金歌》一卷、《定慧相資歌》一卷。","）。"]', '["三度曾經游此地，從緣權順世间情。","登山雖有謝安志，遁迹慚無慧远名。","翠叠寒枝松未老，影深幽徑竹新成。","莫言去住关懷抱，云本無心水自清。","（见懺庵居士《高僧山居诗》，上海商務印书館民国二十三年綫裝鉛印本。","）（〖1〗張靖龙云：永明即延壽。","清釋際祥《淨慈寺志》〖《武林掌故叢編》第十三集〗卷十九附著述目中有「《永明壽禪師山居诗》，吳越僧延壽撰」等語。","卷十八明人李日华山居诗序中記載了永明山居诗的刻本来源，序後附錄佛国山人黄樹穀《集山居诗絕句》十首。","旁小字注曰：「集永明壽禪師诗句。","」其词句與懺庵居士本全部相同。","集句诗後附載和诗諸公云，高峰妙法嗣布衲雍公，嘗居南屏，賡和《永明山居诗》六十九首，楚石梵琦有《和永明山居诗》，梅雪有《和永明山居诗》。","古春云：「永明壽禪師有诗六十九首，慶壽独庵從和之。","」按元代天目山大覺正等寺布衲祖雍的和作，今存其一，见《西天目祖山志》卷五，步延壽山居诗其二韻。","又懺庵居士《高僧山居诗續編》載元代天台高僧無见先覩《和永明禪師〖山居诗〗韻》六十九首，步韻甚嚴。","從永明山居诗的內容来看，也屬智覺延壽所作無疑。","詳細考證參见拙作《延壽及其佚诗》，載《溫州師專学報》〖社會科学版〗一九八六年第三期。","按：日本《續藏經》本宋釋文沖《慧日永明寺智覺禪師自行錄》末附延壽著作總目，有《山居诗》一卷，當即指以上所錄諸诗。","此书所錄延壽所作诗尚有《诗讚》一卷、《物外集》十卷五百首、《吳越唱和诗》一卷、《光明會瑞應诗》一卷、《供養石橋羅漢一十會祥瑞诗》一卷、《杂歌》一卷、《布金歌》一卷、《定慧相資歌》一卷。","）。"]', '诗', 'shi', '', NULL, '永明山居詩（六十九首） 六十九 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9a805a0-55b5-4cc5-afd2-2e5d3a94ca71', '偈 一', '偈 一', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["孤猿叫落中巖月，野客吟殘半夜燈。","此境此時誰得意？白雲深處坐禪僧。","（《五燈會元》卷十。","）（按：張靖龍云：見清嚴行恂《康熙雪竇寺志》卷三「中峯庵」條，題作《夜坐詩》。","）。"]', '["孤猿叫落中巖月，野客吟殘半夜灯。","此境此时誰得意？白云深处坐禪僧。","（《五灯會元》卷十。","）（按：張靖龙云：见清嚴行恂《康熙雪竇寺志》卷三「中峯庵」條，題作《夜坐诗》。","）。"]', '诗', 'shi', '', NULL, '偈 一 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6ed5112-f50c-4826-9df7-9565b9f8b608', '偈 二', '偈 二', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["欲識永明旨，門前一湖水。","日照光明生，風來波浪起。","（見《景德傳燈錄》卷二十六、《五燈會元》卷十。","）。"]', '["欲識永明旨，门前一湖水。","日照光明生，风来波浪起。","（见《景德傳灯錄》卷二十六、《五灯會元》卷十。","）。"]', '诗', 'shi', '', NULL, '偈 二 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('330a9978-8bda-47be-b38d-244de2e80880', '定慧相資歌', '定慧相資歌', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["祖教宗中有二門，十度萬行稱爲尊。","初名止觀助新學，後成定慧菩提根。","唯一法，似雙分，法性寂然體真止，寂而常照妙根存。","定爲父，慧爲母，能孕千聖之門戶。","增長根力養聖胎，念念出生成佛祖。","定爲將，慧爲相，能弼心王成無上。","永作羣生證道門，即是古佛菩提樣。","定如月，光爍外道邪星滅。","能挑智炬轉分明，滋潤道芽除愛結。","慧如日，照破無明之暗室。","能令邪見愚夫禪，盡成般若波羅蜜。","少時默，殺那靜，漸漸增修成正定。","諸聖較量功不多，終見靈臺之妙性。","瞥聞法，纔歷耳，能熏識藏覺種起。","一念回光正智開，須臾成佛法如是。","禪定力，不思義，變凡爲聖殺那時。","無邊生死根由斷，積劫塵勞巢穴墮。","湛心水，淨意珠，光吞萬象爍千途。","抉開己眼無瑕翳，三界元無一法拘。","覺觀賊，應時剋，攀緣病，倐然淨。","蕩念垢兮洗惑塵，顯法身兮堅慧命。","如斷山，若停海，天翻地覆終無改。","瑩似琉璃含寶月，倐然無寄而無待。","般若慧，莫能量，自然隨處現心光。","萬行門中爲導首，一切時中稱法王。","竭苦海，碎邪山，妄雲卷盡片時間。","貧女室中金頓現，壯士額上珠潛還。","斬癡網，截慾流，大雄威猛更無儔。","能令鐵床銅柱冷，頓使魔怨業果休。","和諍訟，成孝義，普現羣生超佛智。","邊邪惡慧盡朝宗，螻蟻鯤鵬齊受記。","偏修定，純陽爛物刳正命。","若將正慧照禪那，自然萬法明如鏡。","偏修慧，純陽枯物成迂滯。","須憑妙定助觀門，如月分明除霧翳。","勸等學，無偏修，從來一體無二頭。","似禽兩翼飛空界，如車二輪乘白牛。","即向梵途登覺岸，便於業海泛慈舟。","或事定，制之一處無不竟；或理定，唯當直下觀心性；或事觀，明諸法相生籌算；或理觀，頓了無一無那畔。","定即慧，非一非二非心計；慧即定，不同不別絕觀聽；或雙運，即寂而照通真訓；或俱泯，非定非慧超常準。","一塵入定衆塵起，般若門中成法爾。","童子身中三昧時，老人身分談真軌。","能觀一境萬境同，近塵遠剎無不通。","真如路上論生死，無明海裏演圓宗。","眼根能作鼻佛事，色塵入定香塵起。","心境常同見自差，誰言不信波元水。","非寂非照絕言思，而寂而照功無比。","權實雙行闡正途，體用更資含妙旨。","勸諸子，勿虛棄，光陰如箭如流水。","散亂全因缺定門，愚盲祇爲虧真智。","真實言，虛入耳，千經萬論同標記。","定慧全功不暫忘，一念頓歸真覺地。","定須習，慧須聞，勿使靈臺一點昏。","合抱之樹生毫末，積漸之功成寶尊。","獼猴學定生天界，女子纔思入道門。","自利利他因果備，若除定慧莫能論。","（《大正新刊大藏經》第四十八冊延壽《永明智覺禪師唯心訣》附收。","）。"]', '["祖教宗中有二门，十度万行稱爲尊。","初名止观助新学，後成定慧菩提根。","唯一法，似雙分，法性寂然體真止，寂而常照妙根存。","定爲父，慧爲母，能孕千聖之门戶。","增长根力養聖胎，念念出生成佛祖。","定爲將，慧爲相，能弼心王成無上。","永作羣生證道门，即是古佛菩提樣。","定如月，光爍外道邪星滅。","能挑智炬轉分明，滋潤道芽除愛結。","慧如日，照破無明之暗室。","能令邪见愚夫禪，尽成般若波羅蜜。","少时默，殺那静，漸漸增修成正定。","諸聖較量功不多，終见靈台之妙性。","瞥闻法，纔歷耳，能熏識藏覺種起。","一念回光正智开，須臾成佛法如是。","禪定力，不思義，变凡爲聖殺那时。","無邊生死根由斷，積劫塵勞巢穴墮。","湛心水，淨意珠，光吞万象爍千途。","抉开己眼無瑕翳，三界元無一法拘。","覺观賊，應时剋，攀緣病，倐然淨。","蕩念垢兮洗惑塵，显法身兮堅慧命。","如斷山，若停海，天翻地覆終無改。","瑩似琉璃含寶月，倐然無寄而無待。","般若慧，莫能量，自然隨处現心光。","万行门中爲導首，一切时中稱法王。","竭苦海，碎邪山，妄云卷尽片时间。","貧女室中金頓現，壯士額上珠潛還。","斬癡網，截慾流，大雄威猛更無儔。","能令鐵床銅柱冷，頓使魔怨業果休。","和諍訟，成孝義，普現羣生超佛智。","邊邪惡慧尽朝宗，螻蟻鯤鵬齊受記。","偏修定，純陽爛物刳正命。","若將正慧照禪那，自然万法明如镜。","偏修慧，純陽枯物成迂滯。","須憑妙定助观门，如月分明除霧翳。","勸等学，無偏修，從来一體無二头。","似禽兩翼飞空界，如车二輪乘白牛。","即向梵途登覺岸，便於業海泛慈舟。","或事定，制之一处無不竟；或理定，唯當直下观心性；或事观，明諸法相生籌算；或理观，頓了無一無那畔。","定即慧，非一非二非心計；慧即定，不同不別絕观听；或雙運，即寂而照通真訓；或俱泯，非定非慧超常準。","一塵入定衆塵起，般若门中成法爾。","童子身中三昧时，老人身分談真軌。","能观一境万境同，近塵远剎無不通。","真如路上論生死，無明海裏演圓宗。","眼根能作鼻佛事，色塵入定香塵起。","心境常同见自差，誰言不信波元水。","非寂非照絕言思，而寂而照功無比。","權實雙行闡正途，體用更資含妙旨。","勸諸子，勿虛棄，光陰如箭如流水。","散亂全因缺定门，愚盲祇爲虧真智。","真實言，虛入耳，千經万論同標記。","定慧全功不暫忘，一念頓归真覺地。","定須習，慧須闻，勿使靈台一点昏。","合抱之樹生毫末，積漸之功成寶尊。","獼猴学定生天界，女子纔思入道门。","自利利他因果備，若除定慧莫能論。","（《大正新刊大藏經》第四十八冊延壽《永明智覺禪師唯心訣》附收。","）。"]', '诗', 'shi', '', NULL, '定慧相資歌 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38fcb454-becf-4284-9824-1c899f8ee917', '遊上雪竇詩', '游上雪竇诗', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["下雪竇遊上雪竇，過雲峰後望雲峰。","如趨仙府經三島，似入天門徹九重。","無日不飛丹頂鶴，有時忽起隱潭龍。","祇因奉詔西歸去，此境何由得再逢。"]', '["下雪竇游上雪竇，過云峰後望云峰。","如趨仙府經三島，似入天门徹九重。","無日不飞丹頂鹤，有时忽起隐潭龙。","祇因奉詔西归去，此境何由得再逢。"]', '诗', 'shi', '', NULL, '遊上雪竇詩 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bc26e92-3c86-4a72-87c9-b172672d9b1c', '同于秘丞賦瀑泉詩', '同于秘丞賦瀑泉诗', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["大禹不知鑿，來源亦自成。","包應憐衆白，聲合讓孤清。","遠勢曾吞海，飛流欲噴鯨。","靈槎如可泛，天際問歸程。","（二首均錄自光緒三十四年刊張美翊纂《奉化縣志》卷四。","前首又見《古今圖書集成·山川典》卷一一○。","）（按：二詩原署「周僧智覺」。","同書卷三三《方外傳》云：「周知覺，名延壽，錢塘王氏子。","周廣順二年住雪竇，吳越錢氏崇信之。","著宗鏡錄一百卷。","」原注：「康乾志」。","）。"]', '["大禹不知鑿，来源亦自成。","包應怜衆白，声合讓孤清。","远勢曾吞海，飞流欲噴鯨。","靈槎如可泛，天際问归程。","（二首均錄自光緒三十四年刊張美翊纂《奉化縣志》卷四。","前首又见《古今圖书集成·山川典》卷一一○。","）（按：二诗原署「周僧智覺」。","同书卷三三《方外傳》云：「周知覺，名延壽，錢塘王氏子。","周廣順二年住雪竇，吳越錢氏崇信之。","著宗镜錄一百卷。","」原注：「康乾志」。","）。"]', '诗', 'shi', '', NULL, '同于秘丞賦瀑泉詩 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5229ce5-4ce9-4643-a62e-969aff448236', '武肅王有旨石橋設齋會進一詩 一', '武肅王有旨石橋設斋會進一诗 一', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["南有天台事可尊，孕靈含秀獨超羣。","重重曲澗侵危石，步步層巖踏碎雲。","金雀每從雲裏現，異香多向夜深聞。","當知此界非凡界，一道幽奇各自分。","。"]', '["南有天台事可尊，孕靈含秀独超羣。","重重曲澗侵危石，步步層巖踏碎云。","金雀每從云裏現，異香多向夜深闻。","當知此界非凡界，一道幽奇各自分。","。"]', '诗', 'shi', '', NULL, '武肅王有旨石橋設齋會進一詩 一 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f518757-f2ac-4faf-bc5c-5b2330bc8786', '武肅王有旨石橋設齋會進一詩 二', '武肅王有旨石橋設斋會進一诗 二', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["仙源佛窟有天台，今古嘉名遍九垓。","石磴嵌空神匠出，瀑泉雄壯雨聲來。","景強偏感高僧住，地勝能令遠思開。","一等翹誠依此處，自然靈貺作梯媒。"]', '["仙源佛窟有天台，今古嘉名遍九垓。","石磴嵌空神匠出，瀑泉雄壯雨声来。","景強偏感高僧住，地勝能令远思开。","一等翹誠依此处，自然靈貺作梯媒。"]', '诗', 'shi', '', NULL, '武肅王有旨石橋設齋會進一詩 二 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6ba18bc-ff0b-416a-ad70-fbc5248c5f32', '武肅王有旨石橋設齋會進一詩 三', '武肅王有旨石橋設斋會進一诗 三', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["智泉福海莫能逾，親自王恩運睿謨。","感現盡冥心境界，資持全固道根株。","石梁低翥紅鸚鵡，煙嶺高翔碧鷓鴣。","勝妙重復惟禱祝，永資軍庶息災虞。"]', '["智泉福海莫能逾，親自王恩運睿謨。","感現尽冥心境界，資持全固道根株。","石梁低翥紅鸚鵡，煙嶺高翔碧鷓鴣。","勝妙重复惟禱祝，永資軍庶息災虞。"]', '诗', 'shi', '', NULL, '武肅王有旨石橋設齋會進一詩 三 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21dfc946-1573-44b1-a217-f5f3f2aeb19f', '武肅王有旨石橋設齋會進一詩 四', '武肅王有旨石橋設斋會進一诗 四', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["凌晨迎請倍精誠，親散鮮花異處清。","羅漢攀枝呈梵相，巖僧倚樹現真形。","神幡雙出紅霞動，寶塔全開白氣生。","都爲王心標意切，滿空盈月瑞分明。"]', '["凌晨迎請倍精誠，親散鲜花異处清。","羅漢攀枝呈梵相，巖僧倚樹現真形。","神幡雙出紅霞动，寶塔全开白氣生。","都爲王心標意切，满空盈月瑞分明。"]', '诗', 'shi', '', NULL, '武肅王有旨石橋設齋會進一詩 四 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b4c7755-a347-4a6d-b4c2-39bd423c5566', '武肅王有旨石橋設齋會進一詩 五', '武肅王有旨石橋設斋會進一诗 五', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["幡花寶蓋滿清川，祈禱迎來聖半千。","莫道聖緣無影響，須知嘉會有因緣。","空中長似聞天樂，巖畔嘗疑有地仙。","何必更尋兜率去，重復靈應事昭然。"]', '["幡花寶蓋满清川，祈禱迎来聖半千。","莫道聖緣無影响，須知嘉會有因緣。","空中长似闻天乐，巖畔嘗疑有地仙。","何必更尋兜率去，重复靈應事昭然。"]', '诗', 'shi', '', NULL, '武肅王有旨石橋設齋會進一詩 五 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bb514ee-0de7-4847-bd46-1a7a353fe286', '武肅王有旨石橋設齋會進一詩 六', '武肅王有旨石橋設斋會進一诗 六', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["登雲步嶺涉煙程，好景隨心次第生。","聖者已符祥瑞事，地靈全副禱祈情。","洞深重疊拖雲濕，灘淺潺湲漱水清。","願滿事圓歸去路，便風相送片帆輕。","（見《四庫全書珍本初集》本宋林表民《天台前集別編》。","（按：《全唐詩》卷八五一收六詩，僅云爲「吳越僧」作。","今確定爲吳越釋延壽作。","）。"]', '["登云步嶺涉煙程，好景隨心次第生。","聖者已符祥瑞事，地靈全副禱祈情。","洞深重叠拖云濕，灘淺潺湲漱水清。","願满事圓归去路，便风相送片帆轻。","（见《四庫全书珍本初集》本宋林表民《天台前集別編》。","（按：《全唐诗》卷八五一收六诗，僅云爲「吳越僧」作。","今確定爲吳越釋延壽作。","）。"]', '诗', 'shi', '', NULL, '武肅王有旨石橋設齋會進一詩 六 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef14cfc5-2b28-474d-9282-a6f9e3e09981', '句 一', '句 一', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["言前體道乾坤窄，筆下搜吟海嶽枯。"]', '["言前體道乾坤窄，笔下搜吟海嶽枯。"]', '诗', 'shi', '', NULL, '句 一 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18d51aee-f00f-4dab-b773-61f63eb9e470', '句 二', '句 二', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["繞繡屏飛花外蝶，隔金籠語柳中鶯。"]', '["繞繡屏飞花外蝶，隔金籠語柳中鶯。"]', '诗', 'shi', '', NULL, '句 二 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0e16250-4328-4339-8d39-50f944d082ac', '句 三', '句 三', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["春雨閉花徑，晚雲生石樓。"]', '["春雨閉花徑，晚云生石楼。"]', '诗', 'shi', '', NULL, '句 三 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9488704d-1021-4964-822e-863801c0f284', '句 四', '句 四', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["草濃春徑狹，樹密晚窗陰。","（均見明刻本《吟窗雜錄》卷三十二《古今詩僧》。","）（按：延壽卒於開寶八年，時吳越雖已奉宋爲正朔，用其年號，而仍維持獨立。","吳越納土，爲延壽卒後三年之事。","諸書或以延壽爲宋人，實未諦。","）。"]', '["草濃春徑狹，樹密晚窗陰。","（均见明刻本《吟窗杂錄》卷三十二《古今诗僧》。","）（按：延壽卒於开寶八年，时吳越雖已奉宋爲正朔，用其年號，而仍維持独立。","吳越納土，爲延壽卒後三年之事。","諸书或以延壽爲宋人，實未諦。","）。"]', '诗', 'shi', '', NULL, '句 四 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98bafea7-91a5-4757-88db-d3a8adc34ed0', '題清樂亭', '題清乐亭', 'd573d0a1-b2b1-4c3a-87c2-664320f42f77', '唐', '["林亭虛敞依金地，終待休宦此結廬。","因共支公話空理，人中清樂更無如。","（見復旦大學圖書館藏舊抄本《至元嘉禾志》卷三十二。","）。"]', '["林亭虛敞依金地，終待休宦此結廬。","因共支公話空理，人中清乐更無如。","（见复旦大学圖书館藏旧抄本《至元嘉禾志》卷三十二。","）。"]', '诗', 'shi', '', NULL, '題清樂亭 錢師悅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a8fa92e-bd7e-44ea-9aa4-c83166650e95', '保安寺', '保安寺', 'eeeaaea3-abe8-41be-9c25-9e1791acea4f', '唐', '["擾擾塵埃白日忙，偶然來謁贊公房。","行登峻嶺躋攀倦，坐俯清泉笑傲涼。","林靜鳥聲酧客語，風來花氣逐人香。","此時已覺凡塵斷，分得高僧興味長。","（見《宋詩紀事補遺》卷二引《開化縣志》。","）。"]', '["擾擾塵埃白日忙，偶然来謁贊公房。","行登峻嶺躋攀倦，坐俯清泉笑傲涼。","林静鸟声酧客語，风来花氣逐人香。","此时已覺凡塵斷，分得高僧兴味长。","（见《宋诗紀事補遺》卷二引《开化縣志》。","）。"]', '诗', 'shi', '', NULL, '保安寺 江景防 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('def76611-0863-48cb-ae5e-ec01e455e0ab', '詩寄贈四明寶雲通法師（二首） 一', '诗寄贈四明寶云通法師（二首） 一', '8194198d-f1d2-421f-bba4-e32fd6b71b62', '唐', '["海角復天涯，形分道不賒。","燈清讀圜覺，香煖頂袈裟。","戒比珠無類（疑當作「纇」），心猶鏡斷瑕。","平生賴慈眼，南望一咨嗟。"]', '["海角复天涯，形分道不賒。","灯清读圜覺，香煖頂袈裟。","戒比珠無類（疑當作「纇」），心猶镜斷瑕。","平生賴慈眼，南望一咨嗟。"]', '诗', 'shi', '', NULL, '詩寄贈四明寶雲通法師（二首） 一 錢俶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0233493d-ee69-426c-891b-ce2909ea2be0', '詩寄贈四明寶雲通法師（二首） 二', '诗寄贈四明寶云通法師（二首） 二', '8194198d-f1d2-421f-bba4-e32fd6b71b62', '唐', '["相望幾千里，曠然違道情。","自茲成乍別，疑是隔浮生。","得旨探玄寂，無心競利名。","苑齋正秋夜，誰伴誦經聲。","（見《大正新脩大藏經》第四六冊南宋釋宗曉編《寶雲振祖集》。","）（按：此詩題下署「吳越國王錢俶」，末附嘉泰壬戌宗曉跋，敘得詩始末，文長不具錄。","通法師卒於宋太宗端拱改元之年，年六十三。","俶作此詩時已降宋否，尚難考詳。","）。"]', '["相望幾千里，曠然違道情。","自茲成乍別，疑是隔浮生。","得旨探玄寂，無心競利名。","苑斋正秋夜，誰伴誦經声。","（见《大正新脩大藏經》第四六冊南宋釋宗晓編《寶云振祖集》。","）（按：此诗題下署「吳越国王錢俶」，末附嘉泰壬戌宗晓跋，敘得诗始末，文长不具錄。","通法師卒於宋太宗端拱改元之年，年六十三。","俶作此诗时已降宋否，尚难考詳。","）。"]', '诗', 'shi', '', NULL, '詩寄贈四明寶雲通法師（二首） 二 錢俶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e87ebec-2da0-49b3-83dd-10f46d9a61cb', '寄題明月禪院（之二）', '寄題明月禪院（之二）', '7b402e8f-4ee8-4b5c-90ca-8d05a0e0bdeb', '唐', '["積翠湖心迤邐長，洞臺蕭寺兩交光。","鳥行黑點波濤白，楓葉紅蓮橘柚黃。","人我絕時偎樹石，是非來處接帆檣。","如何遂得追遊性，擺却營營不急忙。","（見范成大纂《吳郡志》卷三十三。","）（按：《吳郡志》錄贊寧詩二首，題作《寄題水月禪院》。","然同卷云：水月禪院，「天祐四年，刺史曹珪以『明月』名之，皇朝祥符間詔易今名。","」院名「水月」，在贊寧死後，克據舊名改題。","其一已收入《全唐詩補逸》卷十八。","）。"]', '["積翠湖心迤邐长，洞台蕭寺兩交光。","鸟行黑点波濤白，楓葉紅蓮橘柚黄。","人我絕时偎樹石，是非来处接帆檣。","如何遂得追游性，擺却營營不急忙。","（见范成大纂《吳郡志》卷三十三。","）（按：《吳郡志》錄贊寧诗二首，題作《寄題水月禪院》。","然同卷云：水月禪院，「天祐四年，刺史曹珪以『明月』名之，皇朝祥符间詔易今名。","」院名「水月」，在贊寧死後，克據旧名改題。","其一已收入《全唐诗補逸》卷十八。","）。"]', '诗', 'shi', '', NULL, '寄題明月禪院（之二） 贊寧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34939cde-adf8-4cc3-b069-3579ed22aaba', '悟空塔', '悟空塔', '7b402e8f-4ee8-4b5c-90ca-8d05a0e0bdeb', '唐', '["浮圖蕭瑟入虛空，一聚全身罔像中。","傳馬祖心開佛印，識龍潛主示神通。","毫光委墜江樓月，道氣馨香海岸風。","此地化緣才始盡，更於何處動魔宮？","（《海昌勝蹟志》卷一。","此首承陶敏先生錄示。","）。"]', '["浮圖蕭瑟入虛空，一聚全身罔像中。","傳马祖心开佛印，識龙潛主示神通。","毫光委墜江楼月，道氣馨香海岸风。","此地化緣才始尽，更於何处动魔宮？","（《海昌勝蹟志》卷一。","此首承陶敏先生錄示。","）。"]', '诗', 'shi', '', NULL, '悟空塔 贊寧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a699750-60bb-43a9-abf7-01428fddb13a', '夜吟', '夜吟', '7b402e8f-4ee8-4b5c-90ca-8d05a0e0bdeb', '唐', '["獨坐閑吟野思清，秋庭蕭索暮煙輕。","孤燈欲灺月未上，萬籟寂然蛩一聲。"]', '["独坐闲吟野思清，秋庭蕭索暮煙轻。","孤灯欲灺月未上，万籟寂然蛩一声。"]', '诗', 'shi', '', NULL, '夜吟 贊寧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc99cf85-7628-4a3b-bcf3-f05249745f25', '秋日寄人', '秋日寄人', '7b402e8f-4ee8-4b5c-90ca-8d05a0e0bdeb', '唐', '["白鳥行從山嘴沒，青鷗羣向水湄分。","松齋獨坐誰爲侶？數片斜飛檻外雲。","（以上二詩爲張靖龍同志提供，云見南宋陳起《增廣聖宋高僧詩選後集》卷上。","）。"]', '["白鸟行從山嘴沒，青鷗羣向水湄分。","松斋独坐誰爲侶？數片斜飞檻外云。","（以上二诗爲張靖龙同志提供，云见南宋陳起《增廣聖宋高僧诗選後集》卷上。","）。"]', '诗', 'shi', '', NULL, '秋日寄人 贊寧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57a8497e-9c6f-4d8f-9848-f9fac970c34a', '錢唐潮信詩', '錢唐潮信诗', '7b402e8f-4ee8-4b5c-90ca-8d05a0e0bdeb', '唐', '["午未未未申，申（《西湖遊覽志》作「寅」）卯卯辰辰，巳巳巳午午，朔望一般輪。","（見元陶宗儀《南村輟耕錄》卷十二。","）（按：明田汝成《西湖遊覽志》卷二四收此爲「杭人」詩。","）。"]', '["午未未未申，申（《西湖游覽志》作「寅」）卯卯辰辰，巳巳巳午午，朔望一般輪。","（见元陶宗儀《南村輟耕錄》卷十二。","）（按：明田汝成《西湖游覽志》卷二四收此爲「杭人」诗。","）。"]', '诗', 'shi', '', NULL, '錢唐潮信詩 贊寧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a7033d9-9781-46b3-b96e-22598795d06c', '句 一', '句 一', '7b402e8f-4ee8-4b5c-90ca-8d05a0e0bdeb', '唐', '["要路花爭發，閒門草易荒。","（見宋吳子良《荆溪林下偶談》卷二。","）。"]', '["要路花爭發，閒门草易荒。","（见宋吳子良《荆溪林下偶談》卷二。","）。"]', '诗', 'shi', '', NULL, '句 一 贊寧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d463535-2633-4b08-973a-f1ac31053ad8', '句 二', '句 二', '7b402e8f-4ee8-4b5c-90ca-8d05a0e0bdeb', '唐', '["山黛淺深春氣力，浪花開合水工夫。"]', '["山黛淺深春氣力，浪花开合水工夫。"]', '诗', 'shi', '', NULL, '句 二 贊寧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69352ce8-8ca5-40f7-b86a-e7c827ca9cbe', '句 三', '句 三', '7b402e8f-4ee8-4b5c-90ca-8d05a0e0bdeb', '唐', '["草濃春徑狹，樹密晚窗陰。","（均見《錦繡萬花谷後集》卷三《春門》。","）（按：「草濃」二句，《吟窗雜錄》作延壽詩。","未詳孰是，今互收。","）。"]', '["草濃春徑狹，樹密晚窗陰。","（均见《錦繡万花谷後集》卷三《春门》。","）（按：「草濃」二句，《吟窗杂錄》作延壽诗。","未詳孰是，今互收。","）。"]', '诗', 'shi', '', NULL, '句 三 贊寧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('560de09d-18d4-4898-b345-7beb9f5a4c01', '句 四', '句 四', '7b402e8f-4ee8-4b5c-90ca-8d05a0e0bdeb', '唐', '["何用密防奸。","（《江湖小集》卷五紹嵩《江浙紀行集句詩》引。","）。"]', '["何用密防奸。","（《江湖小集》卷五紹嵩《江浙紀行集句诗》引。","）。"]', '诗', 'shi', '', NULL, '句 四 贊寧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea66224d-5aba-4e09-80ef-cdad0dc061b0', '句 五', '句 五', '7b402e8f-4ee8-4b5c-90ca-8d05a0e0bdeb', '唐', '["與閑爲活計。","（同前。","）。"]', '["與闲爲活計。","（同前。","）。"]', '诗', 'shi', '', NULL, '句 五 贊寧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8dcc323a-9fff-42e3-8e23-486d87c341c0', '答慧文 一', '答慧文 一', '30f9aa95-a561-4570-b2eb-dc58cc5036d3', '唐', '["般若大神珠，分形萬萬億。","塵塵彰妙體，剎剎靜毗盧。"]', '["般若大神珠，分形万万億。","塵塵彰妙體，剎剎静毗盧。"]', '诗', 'shi', '', NULL, '答慧文 一 曉榮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('244ab2c7-e500-4acf-bae1-b0c7709a5b5a', '答慧文 二', '答慧文 二', '30f9aa95-a561-4570-b2eb-dc58cc5036d3', '唐', '["一念周沙界，日用萬般通。","湛然常寂滅，常展自家風。","（《五燈會元》卷十。","）。"]', '["一念周沙界，日用万般通。","湛然常寂滅，常展自家风。","（《五灯會元》卷十。","）。"]', '诗', 'shi', '', NULL, '答慧文 二 曉榮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a227892b-0932-4fc1-bf55-b2a0caf3da41', '頌', '頌', '6a383707-1406-4878-abaf-0e6065ac97ea', '唐', '["秋庭肅肅風颾颾，寒星列空蟾魄高。","搘頤靜坐神不勞，鳥窠無端吹布毛。","（同前。","）。"]', '["秋庭肅肅风颾颾，寒星列空蟾魄高。","搘頤静坐神不勞，鸟窠無端吹布毛。","（同前。","）。"]', '诗', 'shi', '', NULL, '頌 遇臻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01ad1311-3f37-41a0-9bb5-e7d489782d8a', '', '', '56b307ce-e037-403e-ab86-be931c3e7ea1', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 本先 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee4da0a7-ead2-42e5-b95c-543ea44e61d1', '非風幡動仁者心動頌', '非风幡动仁者心动頌', '56b307ce-e037-403e-ab86-be931c3e7ea1', '唐', '["非風幡動唯心動，自古相傳直至今。","今後水雲人欲曉，祖師直是好知音。"]', '["非风幡动唯心动，自古相傳直至今。","今後水云人欲晓，祖師直是好知音。"]', '诗', 'shi', '', NULL, '非風幡動仁者心動頌 本先 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea95db3f-9de6-4fef-9d65-c3d9494b95f9', '見色便見心頌', '见色便见心頌', '56b307ce-e037-403e-ab86-be931c3e7ea1', '唐', '["若是見色便見心，人來問著方難答。","更求道理說多般，孤負平生三事衲。"]', '["若是见色便见心，人来问著方难答。","更求道理说多般，孤負平生三事衲。"]', '诗', 'shi', '', NULL, '見色便見心頌 本先 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12013fe2-eebb-40a6-a66c-9a48f8a2d5d9', '明自己頌', '明自己頌', '56b307ce-e037-403e-ab86-be931c3e7ea1', '唐', '["曠大劫來祇如是，如是同天亦同地。","同地同天作麽形，作麽形兮無不是。","（同前。","）（按：以上三頌皆爲參德韶後作，德韶卒于吳越納土前，故收入。","）。"]', '["曠大劫来祇如是，如是同天亦同地。","同地同天作麽形，作麽形兮無不是。","（同前。","）（按：以上三頌皆爲參德韶後作，德韶卒于吳越納土前，故收入。","）。"]', '诗', 'shi', '', NULL, '明自己頌 本先 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e14e42e8-4e9f-4cdd-a920-a0637ea5c7cc', '聞墮薪有省偈', '闻墮薪有省偈', 'f142b4d1-b9ad-42a2-b121-bd6227d354c2', '唐', '["撲落非他物，縱橫不是塵。","山河及大地，全露法王身。","（同前。","）（按：此偈爲與德韶「普請次」作。","）。"]', '["撲落非他物，縱橫不是塵。","山河及大地，全露法王身。","（同前。","）（按：此偈爲與德韶「普請次」作。","）。"]', '诗', 'shi', '', NULL, '聞墮薪有省偈 洪壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ef6093f-1066-4b80-aabb-44c7e9be6d0b', '春日登大悲閣二首（一字至七字）', '春日登大悲閣二首（一字至七字）', 'e16e3744-66d1-40ee-a9c8-472d530ed264', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, '春日登大悲閣二首（一字至七字） 錢惟治 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6d9d152-f9d5-4c45-8134-22af151d4a77', '春日登大悲閣二首（一字至七字） 一', '春日登大悲閣二首（一字至七字） 一', 'e16e3744-66d1-40ee-a9c8-472d530ed264', '唐', '["閣，閣。","雕鏤，彩錯。","簇明霞，攅麗萼。","玉女窺牖，飛仙捧鐸。","沉煙燠寶香，媚水涵珠箔。","千山蓊鬱晴霽，萬井喧填曉郭。","登臨徙倚傍瓊欄，滿目春光煦寥廓。"]', '["閣，閣。","雕鏤，彩錯。","簇明霞，攅丽萼。","玉女窺牖，飞仙捧鐸。","沉煙燠寶香，媚水涵珠箔。","千山蓊鬱晴霽，万井喧填晓郭。","登臨徙倚傍瓊欄，满目春光煦寥廓。"]', '诗', 'shi', '', NULL, '春日登大悲閣二首（一字至七字） 一 錢惟治 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4eeb2bef-8498-410e-9b30-a4dfb59974f1', '春日登大悲閣二首（一字至七字） 二', '春日登大悲閣二首（一字至七字） 二', 'e16e3744-66d1-40ee-a9c8-472d530ed264', '唐', '["閣，閣。","般斤，郢作。","木從繩，工必度。","華飾藻繪，密施榱桷。","明蟾代寶燈，瑞靄爲珍箔。","欄危似倚高空，梯迥疑穿碧落。","有時閑上瞰人寰，自謂禽中騰一鶚。"]', '["閣，閣。","般斤，郢作。","木從繩，工必度。","华飾藻繪，密施榱桷。","明蟾代寶灯，瑞靄爲珍箔。","欄危似倚高空，梯迥疑穿碧落。","有时闲上瞰人寰，自謂禽中腾一鶚。"]', '诗', 'shi', '', NULL, '春日登大悲閣二首（一字至七字） 二 錢惟治 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66b52dc2-f6e8-4fee-a09c-effbb5444e02', '春日登大悲閣（四言回文）', '春日登大悲閣（四言回文）', 'e16e3744-66d1-40ee-a9c8-472d530ed264', '唐', '["春城滿望，曉閣閑登。","塵銷霽景，定出真僧。","人懷遠思，檻憑危層。","因圓果證，勝境斯興。","（均見明梁橋《冰川詩式》卷二。","）。"]', '["春城满望，晓閣闲登。","塵銷霽景，定出真僧。","人懷远思，檻憑危層。","因圓果證，勝境斯兴。","（均见明梁橋《冰川诗式》卷二。","）。"]', '诗', 'shi', '', NULL, '春日登大悲閣（四言回文） 錢惟治 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6c75cb7-2620-4c6e-a0e4-88f8323c4f5a', '山居詩', '山居诗', '622322f2-9a58-40f8-ab6a-6c70f24a3735', '唐', '["宿雨一番蔬甲嫩，春山幾焙茗旗香。","（見《玉壺清話》卷一。","）。"]', '["宿雨一番蔬甲嫩，春山幾焙茗旗香。","（见《玉壺清話》卷一。","）。"]', '诗', 'shi', '', NULL, '山居詩 黃夷簡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eaaca141-386f-4d3c-beb7-4c8ea14686a9', '', '', 'fd37bcba-4238-4e8a-8423-fa2000cb3867', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 錢昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f64a90f0-f211-4df3-94ef-038b0d51a17d', '昇山靈巖寺（題擬）', '昇山靈巖寺（題擬）', 'fd37bcba-4238-4e8a-8423-fa2000cb3867', '唐', '["松杉滿寺廊，欄杆倚高岡。","郡郭曉雲漠，禪齋春草長。","澗青連竹色，山靜帶茶香。","更有名僧在，茅菴住上方。","（見《淳熙三山志》卷三八。","）。"]', '["松杉满寺廊，欄杆倚高岡。","郡郭晓云漠，禪斋春草长。","澗青連竹色，山静带茶香。","更有名僧在，茅菴住上方。","（见《淳熙三山志》卷三八。","）。"]', '诗', 'shi', '', NULL, '昇山靈巖寺（題擬） 錢昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8644b42-e41b-42ae-bcd9-5cd2a6d226aa', '涵虛沼留題', '涵虛沼留題', 'fd37bcba-4238-4e8a-8423-fa2000cb3867', '唐', '["景致逼神仙，心幽道亦[玄]（元）。","僧閒來出世，松老不知年。","放馬眠巖草，移盃酌澗泉。","浮名如脫得，終老此雲邊。","（見影印文淵閣《四庫全書》本《福建通志》卷七七。","）。"]', '["景致逼神仙，心幽道亦[玄]（元）。","僧閒来出世，松老不知年。","放马眠巖草，移盃酌澗泉。","浮名如脫得，終老此云邊。","（见影印文淵閣《四庫全书》本《福建通志》卷七七。","）。"]', '诗', 'shi', '', NULL, '涵虛沼留題 錢昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78d19145-2526-4055-a5e6-52095d64a1f5', '留題巾山明慶塔院', '留題巾山明慶塔院', 'fd37bcba-4238-4e8a-8423-fa2000cb3867', '唐', '["數級崔嵬萬木中，最堪影勢似難同。","欄杆（《赤城志》作「闌干」）夜壓江心月，鈴鐸秋搖嶽頂風。","重疊畫簷遮世界，稀疎清磬徹虛空。","有時問著禪僧路，笑指丹霄去不窮。","（見《天台續集》卷下、《嘉定赤城志》卷十九。","）。"]', '["數級崔嵬万木中，最堪影勢似难同。","欄杆（《赤城志》作「闌干」）夜壓江心月，鈴鐸秋搖嶽頂风。","重叠畫簷遮世界，稀疎清磬徹虛空。","有时问著禪僧路，笑指丹霄去不窮。","（见《天台續集》卷下、《嘉定赤城志》卷十九。","）。"]', '诗', 'shi', '', NULL, '留題巾山明慶塔院 錢昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d10e620-a999-4e42-8af7-8027361df562', '送靈雲和尚頌（題擬）', '送靈云和尚頌（題擬）', '47bd7cf9-61c9-43b8-a06a-6c78d1681c7f', '唐', '["三十年來祇如常，葉落幾迴（卷十九作「幾迴葉落」）放毫光。","自（卷十九作「從」）此一去雲霄外，圓音體性應法王。","（見《祖堂集》卷十、卷十九。","）。"]', '["三十年来祇如常，葉落幾迴（卷十九作「幾迴葉落」）放毫光。","自（卷十九作「從」）此一去云霄外，圓音體性應法王。","（见《祖堂集》卷十、卷十九。","）。"]', '诗', 'shi', '', NULL, '送靈雲和尚頌（題擬） 師備 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8498db1-4a8b-4b1d-a8e1-09a4ee9a2daa', '偈 一', '偈 一', '47bd7cf9-61c9-43b8-a06a-6c78d1681c7f', '唐', '["三棒愚癡不思議，浩浩溶溶自打之。","行來目前明明道，七顛八倒是汝機。"]', '["三棒愚癡不思議，浩浩溶溶自打之。","行来目前明明道，七顛八倒是汝機。"]', '诗', 'shi', '', NULL, '偈 一 師備 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d5697b2-8402-4a24-9267-40773a8c0b3f', '偈 二', '偈 二', '47bd7cf9-61c9-43b8-a06a-6c78d1681c7f', '唐', '["用處妙理不換機，問來答得不思議。","應現常聞明知友，人人自在得功稀。"]', '["用处妙理不換機，问来答得不思議。","應現常闻明知友，人人自在得功稀。"]', '诗', 'shi', '', NULL, '偈 二 師備 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('244673e3-916f-49f7-a664-24bd669233c4', '偈 三', '偈 三', '47bd7cf9-61c9-43b8-a06a-6c78d1681c7f', '唐', '["再覩道友話清源，人人問道無不全。","法法恒然皆如是，四生九類體中圓。","（均見《祖堂集》卷十。","）。"]', '["再覩道友話清源，人人问道無不全。","法法恒然皆如是，四生九類體中圓。","（均见《祖堂集》卷十。","）。"]', '诗', 'shi', '', NULL, '偈 三 師備 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83a3c307-7229-4a2c-8c09-eec133bf842c', '頌 一', '頌 一', '47bd7cf9-61c9-43b8-a06a-6c78d1681c7f', '唐', '["玄沙遊徑別，時人切須知。","三冬陽氣盛，六月降霜時。","有語非關舌，無言切要辭（《五燈會元》卷七作「詞」）。","會我最後句，出世少人知。","。"]', '["玄沙游徑別，时人切須知。","三冬陽氣盛，六月降霜时。","有語非关舌，無言切要辞（《五灯會元》卷七作「词」）。","會我最後句，出世少人知。","。"]', '诗', 'shi', '', NULL, '頌 一 師備 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f4c6712-cee1-4e61-81fb-3115a2b55585', '頌 二', '頌 二', '47bd7cf9-61c9-43b8-a06a-6c78d1681c7f', '唐', '["奇哉一靈叟，那頓許吺吺（音兜）。","風起引箜篌，迷子爭頭湊。","設使緫不是，蝦蟆張大口。","開口不開口，終是犯靈叟。","欲識箇中意，南星真北斗。"]', '["奇哉一靈叟，那頓許吺吺（音兜）。","风起引箜篌，迷子爭头湊。","設使緫不是，蝦蟆張大口。","开口不开口，終是犯靈叟。","欲識箇中意，南星真北斗。"]', '诗', 'shi', '', NULL, '頌 二 師備 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf445ed0-4292-49f4-9338-13d7b9d8e48c', '頌 三', '頌 三', '47bd7cf9-61c9-43b8-a06a-6c78d1681c7f', '唐', '["萬里神光頂後相，沒頂之時何處望。","事己成，意已（《五燈會元》作「亦」）休，此箇從來（《五燈會元》作「來蹤」）觸處周。","智者聊聞猛（《五燈會元》作「撩著便」）提取，莫待須臾失却頭。","（均見《景德傳燈錄》卷二九。","）。"]', '["万里神光頂後相，沒頂之时何处望。","事己成，意已（《五灯會元》作「亦」）休，此箇從来（《五灯會元》作「来蹤」）觸处周。","智者聊闻猛（《五灯會元》作「撩著便」）提取，莫待須臾失却头。","（均见《景德傳灯錄》卷二九。","）。"]', '诗', 'shi', '', NULL, '頌 三 師備 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b75de42-aadd-440a-b929-2e19a873b399', '頌 四', '頌 四', '47bd7cf9-61c9-43b8-a06a-6c78d1681c7f', '唐', '["一二三四五，日輪正當午。","可憐大丈夫，先天爲心祖。","（《祖庭事苑》卷二。","）。"]', '["一二三四五，日輪正當午。","可怜大丈夫，先天爲心祖。","（《祖庭事苑》卷二。","）。"]', '诗', 'shi', '', NULL, '頌 四 師備 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2eb45bb4-e81d-4342-a3ac-dcab296d6ed7', '偶覩春時花蘂繁發忽然發悟喜不自勝乃作一偈', '偶覩春时花蘂繁發忽然發悟喜不自勝乃作一偈', 'f587413f-e7e9-4d10-8fd7-dc042ee83cfd', '唐', '["三十年來尋劍客，幾逢花發（《景德傳燈錄》作「落葉」）幾（《五燈會元》作「又」）抽枝。","（《祖堂集》卷十作「葉落幾迴再抽枝」。","）自從一見桃花後，直至如今更不疑。","（見《祖堂集》卷十九、卷十、《景德傳燈錄》卷十一、《五燈會元》卷四。","）。"]', '["三十年来尋劍客，幾逢花發（《景德傳灯錄》作「落葉」）幾（《五灯會元》作「又」）抽枝。","（《祖堂集》卷十作「葉落幾迴再抽枝」。","）自從一见桃花後，直至如今更不疑。","（见《祖堂集》卷十九、卷十、《景德傳灯錄》卷十一、《五灯會元》卷四。","）。"]', '诗', 'shi', '', NULL, '偶覩春時花蘂繁發忽然發悟喜不自勝乃作一偈 志懃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee036821-4d45-49cd-abd2-5bd011d2b82d', '偈', '偈', '1348429c-0cea-4506-af20-6c368c0aea53', '唐', '["迢葉上名（《五燈會元》作「行」）衣，披來須捷機。","纔分招的箭，密露不藏龜。","（見《景德傳燈錄》卷十七、《五燈會元》卷七。","）。"]', '["迢葉上名（《五灯會元》作「行」）衣，披来須捷機。","纔分招的箭，密露不藏龟。","（见《景德傳灯錄》卷十七、《五灯會元》卷七。","）。"]', '诗', 'shi', '', NULL, '偈 從範 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e65634e-de6f-4543-ab73-fbb5deac0086', '臨示寂聲鐘集衆說偈', '臨示寂声鐘集衆说偈', '282a80ef-1968-4a1f-a07f-eccc3dc76248', '唐', '["我逃世難來出家，宗師指示箇歇處。","住山聚衆三十年，尋常不欲輕分付。","今日分明說似君，我歛目時齊聽取。","（見《五燈會元》卷六。","）。"]', '["我逃世难来出家，宗師指示箇歇处。","住山聚衆三十年，尋常不欲轻分付。","今日分明说似君，我歛目时齊听取。","（见《五灯會元》卷六。","）。"]', '诗', 'shi', '', NULL, '臨示寂聲鐘集衆說偈 普聞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7abced8e-c238-46ab-83e8-f2edf0e26841', '住山後作（題從《小草齋詩話》卷四）', '住山後作（題從《小草斋诗話》卷四）', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["光陰倏忽（《小草齋詩話》作「迅速」）暫須臾，浮世那（《小草齋詩話》作「何」）能得久居。","出嶺年登（《祖庭事苑》卷四作「始年」）三十二，入閩（《祖庭事苑》作「如今」）蚤是四旬餘。","他非不用頻頻檢（《祖庭事苑》、《小草齋詩話》作「舉」），已過還（《祖庭事苑》作「當」）須旋旋除。","爲報滿朝（《小草齋詩話》作「報與滿朝」）朱紫道，閻王（《祖庭事苑》作「羅」）不怕佩金魚。","（按：《語錄》原缺題。","）。"]', '["光陰倏忽（《小草斋诗話》作「迅速」）暫須臾，浮世那（《小草斋诗話》作「何」）能得久居。","出嶺年登（《祖庭事苑》卷四作「始年」）三十二，入閩（《祖庭事苑》作「如今」）蚤是四旬餘。","他非不用頻頻檢（《祖庭事苑》、《小草斋诗話》作「舉」），已過還（《祖庭事苑》作「當」）須旋旋除。","爲報满朝（《小草斋诗話》作「報與满朝」）朱紫道，閻王（《祖庭事苑》作「羅」）不怕佩金鱼。","（按：《語錄》原缺題。","）。"]', '诗', 'shi', '', NULL, '住山後作（題從《小草齋詩話》卷四） 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efee5b76-a106-4dd7-9615-0a8cd295b8a1', '游檉洋', '游檉洋', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["青山無適莫，四畔無來路。","安居不到處，出身終有餘。"]', '["青山無適莫，四畔無来路。","安居不到处，出身終有餘。"]', '诗', 'shi', '', NULL, '游檉洋 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28037648-e19c-4519-9e74-c01b57e6e221', '因學人問事', '因学人问事', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["佗事佗人斷，己事己自裁。"]', '["佗事佗人斷，己事己自裁。"]', '诗', 'shi', '', NULL, '因學人問事 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52ff4d28-ecbd-443a-b4ad-3cb7e3eac642', '送澄沼', '送澄沼', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["忽告歸鄉去，崎嶇枉涉途。","雪嶺三秋外，澄沼一事無。"]', '["忽告归乡去，崎嶇枉涉途。","雪嶺三秋外，澄沼一事無。"]', '诗', 'shi', '', NULL, '送澄沼 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ef7fdcc-06c8-4acc-80eb-3c0cc3bf077f', '因讀寒山詩', '因读寒山诗', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["可憐寒山子，多言復多語。"]', '["可怜寒山子，多言复多語。"]', '诗', 'shi', '', NULL, '因讀寒山詩 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c02fc54c-d2dd-4acf-b75e-e187c7469a8b', '咏魚鼓二首 一', '咏鱼鼓二首 一', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["我暫作魚鼓，懸頭爲衆苦。","師僧喫茶飯，拈槌打我肚。","身雖披鱗甲，心中一物無。","鸕鷀橫溪望，我誓不入湖。"]', '["我暫作鱼鼓，懸头爲衆苦。","師僧喫茶飯，拈槌打我肚。","身雖披鱗甲，心中一物無。","鸕鷀橫溪望，我誓不入湖。"]', '诗', 'shi', '', NULL, '咏魚鼓二首 一 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e126ec74-bf49-413d-b423-91e6b9c189fd', '咏魚鼓二首 二', '咏鱼鼓二首 二', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["可憐魚鼓子，天生從地養。","粥飯不能{歹肖}，空肚作聲響。","時時驚僧睡，懶者煩惱長。","住持鬧喧喧，不如打游漾。"]', '["可怜鱼鼓子，天生從地養。","粥飯不能{歹肖}，空肚作声响。","时时驚僧睡，懶者煩惱长。","住持鬧喧喧，不如打游漾。"]', '诗', 'shi', '', NULL, '咏魚鼓二首 二 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa815192-9014-4dbe-97f1-a9d1523f2aff', '放牛', '放牛', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["早朝放牛承露草，直至日晝干飽好。","牛飽更無思食念，牛兒無事唱牛歌。","。"]', '["早朝放牛承露草，直至日晝干飽好。","牛飽更無思食念，牛兒無事唱牛歌。","。"]', '诗', 'shi', '', NULL, '放牛 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0ff47b8-174c-4afb-af15-ce8c8cf8b02a', '勸人 一', '勸人 一', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["莫道肯去易，肯去也大難。","虛空滿天下，迷人坐不安。"]', '["莫道肯去易，肯去也大难。","虛空满天下，迷人坐不安。"]', '诗', 'shi', '', NULL, '勸人 一 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7980ec79-4f96-4da4-a915-f92a9a5fc7b9', '勸人 二', '勸人 二', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["若切老婆心，勸君莫掠虛。","忽遇明眼人，相逢笑殺渠。"]', '["若切老婆心，勸君莫掠虛。","忽遇明眼人，相逢笑殺渠。"]', '诗', 'shi', '', NULL, '勸人 二 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67ffa7bd-b8dd-4613-af8c-98588b931a75', '勸人 三', '勸人 三', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["枯樹解藏龍，貪睡不聞鐘。","一朝侵早起，忽覺是何龍。"]', '["枯樹解藏龙，貪睡不闻鐘。","一朝侵早起，忽覺是何龙。"]', '诗', 'shi', '', NULL, '勸人 三 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c203e3e-0b92-4139-b3d1-21d73733ff21', '勸人 四', '勸人 四', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["低頭不見地，仰面不見天。","欲知白牛處（《林間錄》作「欲識金剛體」），但看髑髏前。","（《林間錄》卷上云此篇爲見亡僧後作。","）。"]', '["低头不见地，仰面不见天。","欲知白牛处（《林间錄》作「欲識金剛體」），但看髑髏前。","（《林间錄》卷上云此篇爲见亡僧後作。","）。"]', '诗', 'shi', '', NULL, '勸人 四 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e6f7a90-5af4-4224-b51c-338937a54195', '勸人 五', '勸人 五', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["達摩來路遠，汝莫辜負佗。","子細審思觀，忽然悟去好。"]', '["達摩来路远，汝莫辜負佗。","子細審思观，忽然悟去好。"]', '诗', 'shi', '', NULL, '勸人 五 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0eae219c-921f-4620-be28-b00e5ab5135d', '勸人 六', '勸人 六', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["人人盡有乾坤眼，莫隨妄境顛倒窺。","恒沙國土總吞盡，吞盡不我何旨旨。"]', '["人人尽有乾坤眼，莫隨妄境顛倒窺。","恒沙国土總吞尽，吞尽不我何旨旨。"]', '诗', 'shi', '', NULL, '勸人 六 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('079f0a5b-a6b6-40f2-8d63-bcb7e6c40865', '勸人 七', '勸人 七', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["枯木藏龍，雷動必驚。","驚者是少，不驚者多。"]', '["枯木藏龙，雷动必驚。","驚者是少，不驚者多。"]', '诗', 'shi', '', NULL, '勸人 七 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3574d08-8ea3-48f6-885b-5f396b43b216', '勸人 八', '勸人 八', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["絕頂白似雪，衆水一源深。","道場平如掌，我宗超佛心。"]', '["絕頂白似雪，衆水一源深。","道場平如掌，我宗超佛心。"]', '诗', 'shi', '', NULL, '勸人 八 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a035f82d-b58c-44c3-b9b1-3cb514bca40f', '勸人 九', '勸人 九', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["長江拋釣子，游魚帶絲絛。","恩重鉤頭餌，輕欺上祖歌。"]', '["长江拋釣子，游鱼带絲絛。","恩重鉤头餌，轻欺上祖歌。"]', '诗', 'shi', '', NULL, '勸人 九 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05d2172b-dc66-45c7-8880-08636c96560a', '勸人 十', '勸人 十', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["脚踏香積壠，頭枕馬鳴崎。","身臥白雲裏，神光萬里秘。","會我最後句，與汝同一枝。"]', '["脚踏香積壠，头枕马鳴崎。","身臥白云裏，神光万里秘。","會我最後句，與汝同一枝。"]', '诗', 'shi', '', NULL, '勸人 十 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('148bc950-f4b6-498c-b823-f69842f0b660', '勸人 十一', '勸人 十一', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["冬瓜長儱侗，葫蘆剔突圝。","玲瓏滿天下，覽子黑漫漫。"]', '["冬瓜长儱侗，葫蘆剔突圝。","玲瓏满天下，覽子黑漫漫。"]', '诗', 'shi', '', NULL, '勸人 十一 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e3974dd-97fa-492b-9659-b3eece0aaf8b', '勸人 十二', '勸人 十二', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["君不見（《祖堂集》卷七「不見」二字作「覓」）路邊華表柱，天下忙忙總一般。","琵琶柦棙（《祖堂集》作「拗捩」）隨手轉，廣陵妙曲無人彈。","若有人能解彈得，一彈彈盡天下曲。"]', '["君不见（《祖堂集》卷七「不见」二字作「覓」）路邊华表柱，天下忙忙總一般。","琵琶柦棙（《祖堂集》作「拗捩」）隨手轉，廣陵妙曲無人彈。","若有人能解彈得，一彈彈尽天下曲。"]', '诗', 'shi', '', NULL, '勸人 十二 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5841f3ab-791c-4be4-a2b9-bc6a52561558', '勸人 十三', '勸人 十三', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["世中（《祖堂集》卷七作「間」）有一事，奉勸學者取。","雖無半錢活，流傳歷劫富。"]', '["世中（《祖堂集》卷七作「间」）有一事，奉勸学者取。","雖無半錢活，流傳歷劫富。"]', '诗', 'shi', '', NULL, '勸人 十三 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7785e11b-147a-4e7b-8b52-03587ceaa792', '勸人 十四', '勸人 十四', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["登天不惜梯，遍地無行路。","包盡乾坤處，禪子火急悟。","（又見《祖堂集》卷七。","）。"]', '["登天不惜梯，遍地無行路。","包尽乾坤处，禪子火急悟。","（又见《祖堂集》卷七。","）。"]', '诗', 'shi', '', NULL, '勸人 十四 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7a81a56-62d6-4257-b990-6ee55e37fdd7', '勸人 十五', '勸人 十五', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["寅朝不肯起，貪坐昏黃晡。","魚被網[裹]（裏）（從《祖堂集》卷七改）却，脹（《祖堂集》作「張」）破獵師肚。"]', '["寅朝不肯起，貪坐昏黄晡。","鱼被網[裹]（裏）（從《祖堂集》卷七改）却，脹（《祖堂集》作「張」）破獵師肚。"]', '诗', 'shi', '', NULL, '勸人 十五 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c41c8dd-62c3-4e9c-93dc-19a0d6a44aa3', '勸人 十六', '勸人 十六', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["滿天不見路，萬里迷也沒。"]', '["满天不见路，万里迷也沒。"]', '诗', 'shi', '', NULL, '勸人 十六 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f65b1e2-ef89-459d-a250-e7956139011f', '勸人 十七', '勸人 十七', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["磨磚不成鏡，虛空終有月。","火急自提取，莫受多生屑。"]', '["磨磚不成镜，虛空終有月。","火急自提取，莫受多生屑。"]', '诗', 'shi', '', NULL, '勸人 十七 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('313ada79-1673-4c37-8182-9ff4a9549511', '勸人 十八', '勸人 十八', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["高拋不至天，低擲豈著地？日輪隱山去，回頭更覓鼻。"]', '["高拋不至天，低擲豈著地？日輪隐山去，回头更覓鼻。"]', '诗', 'shi', '', NULL, '勸人 十八 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7987502-1d73-4e95-b3dd-acaaa4ee6536', '勸人 十九', '勸人 十九', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["我今勸汝道，汝休念文字。","兼勸採樵人，努力莫相欺。"]', '["我今勸汝道，汝休念文字。","兼勸採樵人，努力莫相欺。"]', '诗', 'shi', '', NULL, '勸人 十九 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('735a57d3-7168-4bbc-917a-b9d30e417739', '勸人 二十', '勸人 二十', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["多生不出家，萬劫受辛苦。","今日捨恩愛，誓願莫回顧。"]', '["多生不出家，万劫受辛苦。","今日捨恩愛，誓願莫回顧。"]', '诗', 'shi', '', NULL, '勸人 二十 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('811e9cfb-ae1c-46cd-ae3e-ceee8d95b82c', '勸人 二十一', '勸人 二十一', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["春霜滿天寒，覽子黑漫漫。","白牛常在髑髏前，勸君審細看。"]', '["春霜满天寒，覽子黑漫漫。","白牛常在髑髏前，勸君審細看。"]', '诗', 'shi', '', NULL, '勸人 二十一 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6c80aeb-b9e4-4c7a-8c1e-8df347ed6736', '勸人 二十二', '勸人 二十二', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["報汝等知乎，真性不在途。","色身祇要閑，何用苦區區。"]', '["報汝等知乎，真性不在途。","色身祇要闲，何用苦區區。"]', '诗', 'shi', '', NULL, '勸人 二十二 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('947b6220-815c-4c69-8caa-ae811515c250', '勸人 二十三', '勸人 二十三', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["須知不從人處得，何勞晝夜苦求人。","己珠迥然越三界，不是聖人非色塵。"]', '["須知不從人处得，何勞晝夜苦求人。","己珠迥然越三界，不是聖人非色塵。"]', '诗', 'shi', '', NULL, '勸人 二十三 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ede820a-b454-4c5f-9068-242b906f00fd', '勸人 二十四', '勸人 二十四', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["天色晴明綠嶂分，萬里虛空絕點雲。","可惜時人何不悟，肯者同游此法門。","（此首又見《石倉歷代詩選》卷一一一。","）。"]', '["天色晴明綠嶂分，万里虛空絕点云。","可惜时人何不悟，肯者同游此法门。","（此首又见《石倉歷代诗選》卷一一一。","）。"]', '诗', 'shi', '', NULL, '勸人 二十四 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22b10e62-a461-4e6e-8b5e-5d65808a484b', '勸人 二十五', '勸人 二十五', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["萬里無寸草，迥迥絕烟霞。"]', '["万里無寸草，迥迥絕烟霞。"]', '诗', 'shi', '', NULL, '勸人 二十五 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d3e2714-2986-42c2-9192-08768f79f6fe', '辭曾氏', '辞曾氏', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["昔年曾許鬱多羅，直至如今未動梭。","此日且隨雲水去，誰能待得鴨成鵝。"]', '["昔年曾許鬱多羅，直至如今未动梭。","此日且隨云水去，誰能待得鴨成鵝。"]', '诗', 'shi', '', NULL, '辭曾氏 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6477cee1-7b86-4975-ad2e-d2b9c330cf1a', '贈實師伯', '贈實師伯', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["善哉道者，頓息大機。","堂堂密密，將何顯伊？","千山絕頂，萬重綠衣。","風雲抱合，我終不知。","以此浮幻，隨處徉癡。","嚴霜欲至，放髮齊眉。","僧俗不辯，懷量任疑。","曉我微功，雨勢雲飛。","。"]', '["善哉道者，頓息大機。","堂堂密密，將何显伊？","千山絕頂，万重綠衣。","风云抱合，我終不知。","以此浮幻，隨处徉癡。","嚴霜欲至，放髮齊眉。","僧俗不辯，懷量任疑。","晓我微功，雨勢云飞。","。"]', '诗', 'shi', '', NULL, '贈實師伯 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c6c567c-326e-47a5-886a-35373db65bbc', '幽州未得授戒', '幽州未得授戒', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["一十出家未是時，二十出家正是時。","今遇官壇緣未合，躘踵且作老沙彌。"]', '["一十出家未是时，二十出家正是时。","今遇官壇緣未合，躘踵且作老沙彌。"]', '诗', 'shi', '', NULL, '幽州未得授戒 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73f04b06-ca7d-4dd8-9193-9a224ba3c721', '自述', '自述', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["思量未到雪峰時，愛把浮生取次疑。","及至法門非法法，到頭無我亦無師。","（此首又見《石倉歷代詩選》卷一一一。","）。"]', '["思量未到雪峰时，愛把浮生取次疑。","及至法门非法法，到头無我亦無師。","（此首又见《石倉歷代诗選》卷一一一。","）。"]', '诗', 'shi', '', NULL, '自述 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aba26bd0-0c7a-4cf0-a77f-4fc940c7900b', '師親寫版牌云 一', '師親寫版牌云 一', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["妄身臨鏡照影，影與妄身不殊。","若欲去影留身，不知身影常虛。","身影從來不異，不得一有一無。","若擬憎凡愛聖，生死海裏常浮。"]', '["妄身臨镜照影，影與妄身不殊。","若欲去影留身，不知身影常虛。","身影從来不異，不得一有一無。","若擬憎凡愛聖，生死海裏常浮。"]', '诗', 'shi', '', NULL, '師親寫版牌云 一 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2e0e08a-25e8-414a-a241-dab851dba13e', '師親寫版牌云 二', '師親寫版牌云 二', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["欲得不招無間業，莫謗如來正法輪。","有物密救人，爭奈人不知。"]', '["欲得不招無间業，莫謗如来正法輪。","有物密救人，爭奈人不知。"]', '诗', 'shi', '', NULL, '師親寫版牌云 二 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('298fa5f5-1f5f-4c3b-8052-6a0b3d5b7040', '題枯木菴（題擬）', '題枯木菴（題擬）', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["菴前永日無狼子，磨下終年絕雀兒。","（按：原題作：「師在枯木菴坐禪，於水磨坊前晒麥，乃親題云。","」句後云：「山中至今並無狼虎，凡于磨坊前晒麥，亦無鳥雀，皆如師言。","」）。"]', '["菴前永日無狼子，磨下終年絕雀兒。","（按：原題作：「師在枯木菴坐禪，於水磨坊前晒麦，乃親題云。","」句後云：「山中至今並無狼虎，凡于磨坊前晒麦，亦無鸟雀，皆如師言。","」）。"]', '诗', 'shi', '', NULL, '題枯木菴（題擬） 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f8c1f1f-a11d-4d4c-b7b8-2f7c31440869', '題僧堂前樑', '題僧堂前樑', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["今朝不保明朝，常作千載遮頭。","（以上均見《卍續藏經》本《雪峰真覺禪師語錄》卷下。","是書附北宋王隨、孫覺等人序。","）。"]', '["今朝不保明朝，常作千載遮头。","（以上均见《卍續藏經》本《雪峰真覺禪師語錄》卷下。","是书附北宋王隨、孫覺等人序。","）。"]', '诗', 'shi', '', NULL, '題僧堂前樑 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abb4b1ce-5586-4d28-950e-cabbab8d17cb', '偈 一', '偈 一', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["心鏡明，鑑無礙，廓然瑩徹周沙界。","萬像森羅影現中，一性圓光非內外。","（見《宋鏡錄》卷十。","）。"]', '["心镜明，鑑無礙，廓然瑩徹周沙界。","万像森羅影現中，一性圓光非內外。","（见《宋镜錄》卷十。","）。"]', '诗', 'shi', '', NULL, '偈 一 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4382fa3-09ab-4264-8875-0f3b175a10fc', '偈 二', '偈 二', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["苦屈世間錯用心，低頭曲躬尋文章。","妄情牽引何年了，辜負靈臺一點光。","（見《祖堂集》卷七。","）。"]', '["苦屈世间錯用心，低头曲躬尋文章。","妄情牽引何年了，辜負靈台一点光。","（见《祖堂集》卷七。","）。"]', '诗', 'shi', '', NULL, '偈 二 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89c8ad70-9d3e-4aaf-b9aa-f295a62f747f', '偈 三', '偈 三', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["𪫧憐徒懃子，時人笑作昏。","神清如鏡像，迥然與物分。","（同前卷六。","）。"]', '["𪫧怜徒懃子，时人笑作昏。","神清如镜像，迥然與物分。","（同前卷六。","）。"]', '诗', 'shi', '', NULL, '偈 三 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24a0eab4-66f7-4aea-b15a-557a9fd605e4', '和雙峰偈', '和雙峰偈', '3f4444cc-7157-451f-8c30-9b5840d3c9a9', '唐', '["非但拋僧去，雲嶺不相關。","虛空無隔礙，放曠任縱橫。","神光迥物外，豈非秋月明。","禪子出身處，雷罷不停聲。","（同前卷七。","）。"]', '["非但拋僧去，云嶺不相关。","虛空無隔礙，放曠任縱橫。","神光迥物外，豈非秋月明。","禪子出身处，雷罷不停声。","（同前卷七。","）。"]', '诗', 'shi', '', NULL, '和雙峰偈 義存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73a58cfb-1201-4830-8961-0ba9851cacb4', '頌', '頌', '0fac687c-4626-4ef9-9038-850ba39a3c41', '唐', '["雪山養得一條虵，寄著南山意如何？","不是尋常毒惡物，參玄須得會先陁。","（見《祖堂集》卷七。","）。"]', '["雪山養得一條虵，寄著南山意如何？","不是尋常毒惡物，參玄須得會先陁。","（见《祖堂集》卷七。","）。"]', '诗', 'shi', '', NULL, '頌 暉和尚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('412dc98c-20af-496d-a491-e2d74bb9c6a5', '和暉和尚頌', '和暉和尚頌', '346076bb-4054-4f0e-b5e3-83c04a78576d', '唐', '["勸君嶮處好看虵，衝著臨時爭奈何。","欲得安身覓負物，向南看北正先陁。","（同前。","）。"]', '["勸君嶮处好看虵，衝著臨时爭奈何。","欲得安身覓負物，向南看北正先陁。","（同前。","）。"]', '诗', 'shi', '', NULL, '和暉和尚頌 光雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f20acaf-b240-4aa5-8d20-f09457eca734', '三種病人頌', '三種病人頌', '4a55aa22-52db-4702-8bdc-ab78b02e0ea2', '唐', '["奇哉大師噁盲聾，善能方便唱真宗。","爲報知音須帶會，莫將意句競來通。"]', '["奇哉大師噁盲聾，善能方便唱真宗。","爲報知音須带會，莫將意句競来通。"]', '诗', 'shi', '', NULL, '三種病人頌 道溥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e41ff0d-bf74-42b5-ac5b-bb519eb2ac7c', '示學偈', '示学偈', '4a55aa22-52db-4702-8bdc-ab78b02e0ea2', '唐', '["瞎眼善解通，聾耳却獲功。","一體歸無性，六處本來同。","我今齊舉唱。","方便示汝濃（疑應作「儂」）。","相傳佛祖印，繼續老胡宗。","（均見《祖堂集》卷十一。","）。"]', '["瞎眼善解通，聾耳却獲功。","一體归無性，六处本来同。","我今齊舉唱。","方便示汝濃（疑應作「儂」）。","相傳佛祖印，繼續老胡宗。","（均见《祖堂集》卷十一。","）。"]', '诗', 'shi', '', NULL, '示學偈 道溥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19e230ca-788d-41ea-9129-8ffc24d252bd', '偈頌六首 一', '偈頌六首 一', 'e6a55b24-bc25-439d-9564-f320342a2819', '唐', '["直下猶難會，尋言轉更賒。","擬（《景德傳燈錄》卷十八及《五燈會元》卷七作「若」）論佛與祖，特地隔天涯。","（見《祖堂集》卷十。","）。"]', '["直下猶难會，尋言轉更賒。","擬（《景德傳灯錄》卷十八及《五灯會元》卷七作「若」）論佛與祖，特地隔天涯。","（见《祖堂集》卷十。","）。"]', '诗', 'shi', '', NULL, '偈頌六首 一 神晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb5c0ab4-67e5-4174-b83a-4fde876f7ac7', '偈頌六首 二', '偈頌六首 二', 'e6a55b24-bc25-439d-9564-f320342a2819', '唐', '["有曲無絃索，宮商調不同。","若人纔和得，拍拍盡爲龍。","。"]', '["有曲無絃索，宮商調不同。","若人纔和得，拍拍尽爲龙。","。"]', '诗', 'shi', '', NULL, '偈頌六首 二 神晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce369644-1754-4f65-9c84-a5c25fdb8360', '偈頌六首 三', '偈頌六首 三', 'e6a55b24-bc25-439d-9564-f320342a2819', '唐', '["綵筆除裝色更濃，針挑瘡患理難同。","維摩昔日稱何事，迷從西土却還東。"]', '["綵笔除裝色更濃，針挑瘡患理难同。","維摩昔日稱何事，迷從西土却還东。"]', '诗', 'shi', '', NULL, '偈頌六首 三 神晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b124a72-28e3-4e23-ac55-6f1082869bf1', '偈頌六首 四', '偈頌六首 四', 'e6a55b24-bc25-439d-9564-f320342a2819', '唐', '["何事最堪依，巖中獨坐時。","路險人難到，巒高鳥不飛。"]', '["何事最堪依，巖中独坐时。","路險人难到，巒高鸟不飞。"]', '诗', 'shi', '', NULL, '偈頌六首 四 神晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5e264cd-4a48-415a-a255-1401006cfb26', '偈頌六首 五', '偈頌六首 五', 'e6a55b24-bc25-439d-9564-f320342a2819', '唐', '["白雲長滿洞，論劫未曾虧。","不話曹溪旨，焉干道者機。"]', '["白云长满洞，論劫未曾虧。","不話曹溪旨，焉干道者機。"]', '诗', 'shi', '', NULL, '偈頌六首 五 神晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac6bf4f5-c8ee-4a6e-84a9-7e07fd2ba77e', '偈頌六首 六', '偈頌六首 六', 'e6a55b24-bc25-439d-9564-f320342a2819', '唐', '["石室周圓慶已多，有人不到復如何？待封此樣呈諸友，開時祇好笑呵呵。"]', '["石室周圓慶已多，有人不到复如何？待封此樣呈諸友，开时祇好笑呵呵。"]', '诗', 'shi', '', NULL, '偈頌六首 六 神晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c914b15a-c4eb-4e25-b55d-e649f3d45f20', '十八郎殿下送綵毬上於方丈頂掛便請偈', '十八郎殿下送綵毬上於方丈頂掛便請偈', 'e6a55b24-bc25-439d-9564-f320342a2819', '唐', '["衆綵裁成已，工多妙最殊。","收歸方丈裏，長翫一明珠。"]', '["衆綵裁成已，工多妙最殊。","收归方丈裏，长翫一明珠。"]', '诗', 'shi', '', NULL, '十八郎殿下送綵毬上於方丈頂掛便請偈 神晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c03f6219-ec22-4767-8f7c-37d54be405e0', '十八郎殿下又送偈上國師兼請和師乃答之', '十八郎殿下又送偈上国師兼請和師乃答之', 'e6a55b24-bc25-439d-9564-f320342a2819', '唐', '["建化開遮假立名，無名之說亦難停。","其中薦得非關識，朗月當空不自明。","北京秀長稱爲澤，南派傳宗祖諱能。","黃卷暫詮呼作性，教外須參有別行。","（以上八首均見《古尊宿語錄》卷三七《鼓山先興聖國師和尚法堂玄要廣集》。","）。"]', '["建化开遮假立名，無名之说亦难停。","其中薦得非关識，朗月當空不自明。","北京秀长稱爲澤，南派傳宗祖諱能。","黄卷暫詮呼作性，教外須參有別行。","（以上八首均见《古尊宿語錄》卷三七《鼓山先兴聖国師和尚法堂玄要廣集》。","）。"]', '诗', 'shi', '', NULL, '十八郎殿下又送偈上國師兼請和師乃答之 神晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('119e825e-634e-4f03-b771-c932073d8052', '題所居屋壁（題擬）', '題所居屋壁（題擬）', 'e6a55b24-bc25-439d-9564-f320342a2819', '唐', '["白道從茲速改張，休來顯現作妖祥。","定祛邪行歸真見，必得超凡入聖鄉。","（見《五燈會元》卷七。","）。"]', '["白道從茲速改張，休来显現作妖祥。","定祛邪行归真见，必得超凡入聖乡。","（见《五灯會元》卷七。","）。"]', '诗', 'shi', '', NULL, '題所居屋壁（題擬） 神晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fdd7cfa-2202-4130-979b-27e39571dba9', '', '', '078f3594-e083-4c00-b428-d6c060f98125', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 王十八郎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('355a1ae2-524c-4ebb-991f-a437ea1902d3', '上鼓山國師偈兼請師和之（題擬）', '上鼓山国師偈兼請師和之（題擬）', '078f3594-e083-4c00-b428-d6c060f98125', '唐', '["無形無本亦無名，日用驅驅不暫停。","對面向人多不識，縱橫自在轉分明。","權時來寄君家宅，萬種千般是事能。","認取當來真本性，一時拋棄事皆行。","（同前。","）。"]', '["無形無本亦無名，日用驱驱不暫停。","对面向人多不識，縱橫自在轉分明。","權时来寄君家宅，万種千般是事能。","認取當来真本性，一时拋棄事皆行。","（同前。","）。"]', '诗', 'shi', '', NULL, '上鼓山國師偈兼請師和之（題擬） 王十八郎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7c0630f-9383-4349-aff8-e746eb68c0c4', '見挑燈偈（題擬）', '见挑灯偈（題擬）', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["一靈孤燈當門懸，擬欲挑來歷劫昏。","山聲朴直人難見，此中會得處處全。"]', '["一靈孤灯當门懸，擬欲挑来歷劫昏。","山声朴直人难见，此中會得处处全。"]', '诗', 'shi', '', NULL, '見挑燈偈（題擬） 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6625f6f5-2fc6-4061-b014-7a0fd3d0a2bc', '在靈峰時爲後生造偈（題擬）', '在靈峰时爲後生造偈（題擬）', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["素面相呈猶不識，更添脂粉競鬪看。","這裏若論玄與實，與吾如隔萬重山。","（均見《祖堂集》卷十。","）。"]', '["素面相呈猶不識，更添脂粉競鬪看。","這裏若論玄與實，與吾如隔万重山。","（均见《祖堂集》卷十。","）。"]', '诗', 'shi', '', NULL, '在靈峰時爲後生造偈（題擬） 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b23b9be-5549-4a63-8914-d212f79c0bb8', '贈泉州宏則和尚（題擬）', '贈泉州宏則和尚（題擬）', 'c0a29737-30d9-4148-8ae9-245658078c5a', '唐', '["莫怪我來偏禮足，蕭宮無個似吾師。","（見鄭方坤《五代詩話》卷一、《全閩詩話》卷一引《閩書》。","）。"]', '["莫怪我来偏禮足，蕭宮無個似吾師。","（见鄭方坤《五代诗話》卷一、《全閩诗話》卷一引《閩书》。","）。"]', '诗', 'shi', '', NULL, '贈泉州宏則和尚（題擬） 王延彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b40f654-43bd-4384-97f2-e24dfed1daec', '上長慶和尚偈（題擬）', '上长慶和尚偈（題擬）', 'c0a29737-30d9-4148-8ae9-245658078c5a', '唐', '["世人悟道非從耳，耳患雖加道亦分。","靈鷲一機迦葉會，吾師傳得豈關聞。","（《祖堂集》卷十。","）。"]', '["世人悟道非從耳，耳患雖加道亦分。","靈鷲一機迦葉會，吾師傳得豈关闻。","（《祖堂集》卷十。","）。"]', '诗', 'shi', '', NULL, '上長慶和尚偈（題擬） 王延彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe0f4002-83a5-48be-892a-d57f339f397d', '寄圭峯寂公', '寄圭峯寂公', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["屈指閑思癸丑年，共師曾聽翠微泉。","高梧疎冷月纔上，古屋荒涼人未眠。","別後青雲雖寄跡，亂餘白髮欲垂肩。","無端貧病蓮峯下，一半鄉心屬暮蟬。","（影印本《詩淵》第一冊第七三六頁。","）。"]', '["屈指闲思癸丑年，共師曾听翠微泉。","高梧疎冷月纔上，古屋荒涼人未眠。","別後青云雖寄跡，亂餘白髮欲垂肩。","無端貧病蓮峯下，一半乡心屬暮蟬。","（影印本《诗淵》第一冊第七三六頁。","）。"]', '诗', 'shi', '', NULL, '寄圭峯寂公 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c6d23de-8331-4f84-b680-0c845897d677', '酬韋二十二行次見寄', '酬韋二十二行次见寄', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["獨觸離腸雪滿襟，晚來惆悵兩難任。","早知上馬同千里，且合携觴更一斟。","曩眷已堅金石志，新詩重壯歲寒心。","他時掛壁塵冠在，不爲閑人取次尋。","（影印本《詩淵》第二冊第八七三頁。","）。"]', '["独觸離腸雪满襟，晚来惆悵兩难任。","早知上马同千里，且合携觴更一斟。","曩眷已堅金石志，新诗重壯歲寒心。","他时掛壁塵冠在，不爲闲人取次尋。","（影印本《诗淵》第二冊第八七三頁。","）。"]', '诗', 'shi', '', NULL, '酬韋二十二行次見寄 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('757aee39-2b11-4b66-b2b5-b858918226ae', '文會詠箏柱子', '文會詠箏柱子', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["散木今何幸，良工不棄捐。","力微慙一柱，林薄仰羣絃。","且願聲相應，寧辭迹屢遷。","知音如見賞，雅調爲君傳。","（同前第一三○九頁。","）。"]', '["散木今何幸，良工不棄捐。","力微慙一柱，林薄仰羣絃。","且願声相應，寧辞迹屢遷。","知音如见賞，雅調爲君傳。","（同前第一三○九頁。","）。"]', '诗', 'shi', '', NULL, '文會詠箏柱子 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('122a1802-53b1-4142-a267-df266b9c0afd', '題河陰崔少府素幛', '題河陰崔少府素幛', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["真玉不顯文，至人不逞迹。","君見華堂幛，轉覺虛室白。","曠然絕氛滓，潤色惟粉澤。","皎若朗月昇，皓如繁霜積。","清晨捲簾望，秋天橫半壁。","晝景當戶闚，晴雲拂瑤席。","非無丹青妙，點污吾所惜。","世事巧亂真，我將世情隔。","自持純素質，可悅神仙客。","何必玩畫屏，留連假泉石。","（同前第一三八九頁。","）。"]', '["真玉不显文，至人不逞迹。","君见华堂幛，轉覺虛室白。","曠然絕氛滓，潤色惟粉澤。","皎若朗月昇，皓如繁霜積。","清晨捲簾望，秋天橫半壁。","晝景當戶闚，晴云拂瑤席。","非無丹青妙，点污吾所惜。","世事巧亂真，我將世情隔。","自持純素質，可悅神仙客。","何必玩畫屏，留連假泉石。","（同前第一三八九頁。","）。"]', '诗', 'shi', '', NULL, '題河陰崔少府素幛 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b47911f-1317-410c-9292-70be404d9b9c', '送人歸覲南海', '送人归覲南海', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["迢迢南越路，送子意難分。","雁背三湘月，家遙五嶺雲。","舶經秋海見，角向晚城聞。","想個問安後，新詩獨不羣。","（同前第六冊第四三八八頁。","）。"]', '["迢迢南越路，送子意难分。","雁背三湘月，家遙五嶺云。","舶經秋海见，角向晚城闻。","想個问安後，新诗独不羣。","（同前第六冊第四三八八頁。","）。"]', '诗', 'shi', '', NULL, '送人歸覲南海 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edeb0173-ef6c-4f26-a9c0-32ab06bf0f96', '送劉光載歸寧', '送劉光載归寧', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["少年才子喜還家，滿袖新詩敵綺霞。","襟袖涼生歸馬病，關河秋曉早鴻斜。","趨庭雖未驚丹桂，問絹何妨賦《白華》。","莫爲時危翻自滯，迴頭一步是星槎。","（同前。","）。"]', '["少年才子喜還家，满袖新诗敵綺霞。","襟袖涼生归马病，关河秋晓早鴻斜。","趨庭雖未驚丹桂，问絹何妨賦《白华》。","莫爲时危翻自滯，迴头一步是星槎。","（同前。","）。"]', '诗', 'shi', '', NULL, '送劉光載歸寧 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('674787d3-cbf5-4a48-b085-04a7ec017b5e', '頌', '頌', 'abfcc1b5-615c-44ef-aa96-b2a64ee14607', '唐', '["山僧一衲衣，展似衆人見。","雲水清理兩條（《五燈會元》作「兩條分」），莫教露針線。","（《景德傳燈錄》卷十七、《五燈會元》卷七。","）。"]', '["山僧一衲衣，展似衆人见。","云水清理兩條（《五灯會元》作「兩條分」），莫教露針線。","（《景德傳灯錄》卷十七、《五灯會元》卷七。","）。"]', '诗', 'shi', '', NULL, '頌 嚴禪師 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('817738bb-72ff-490a-bafa-f61445b104eb', '', '', '666a9001-3712-4924-9a50-f1e42ee40605', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 慧救 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66f848e0-016f-42b2-8f1c-5969864d287c', '曜日頌', '曜日頌', '666a9001-3712-4924-9a50-f1e42ee40605', '唐', '["見物明明絕見塵，聞聲浩浩亦非因。","宗師真示無聞見，未曉徒勞見月新。","（《祖堂集》卷十一。","）。"]', '["见物明明絕见塵，闻声浩浩亦非因。","宗師真示無闻见，未晓徒勞见月新。","（《祖堂集》卷十一。","）。"]', '诗', 'shi', '', NULL, '曜日頌 慧救 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59464be1-8260-43ce-939a-85e677ba21d1', '送靈雲和尚頌（題擬）', '送靈云和尚頌（題擬）', '666a9001-3712-4924-9a50-f1e42ee40605', '唐', '["諦當恒然直古今，未徹見聞實甚深。","現現運轉三十載，春盡萎花未君心。","（《祖堂集》卷十九。","）。"]', '["諦當恒然直古今，未徹见闻實甚深。","現現運轉三十載，春尽萎花未君心。","（《祖堂集》卷十九。","）。"]', '诗', 'shi', '', NULL, '送靈雲和尚頌（題擬） 慧救 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7c6a657-fca4-4b82-b4d5-2ee71da1a20f', '深村', '深村', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["甘向深村固不材，猶勝摧折傍塵埃。","清宵玩月唯紅葉，永日關門但綠苔。","幽院菊荒同寂寞，野橋僧去獨裴回。","隔籬逢叟遙相賀，佇看芳田膏雨來。","（《四庫全書》本《韓內翰別集》。","）（按：《全唐詩》卷六八二收此詩，末句缺四字，今重錄。","）。"]', '["甘向深村固不材，猶勝摧折傍塵埃。","清宵玩月唯紅葉，永日关门但綠苔。","幽院菊荒同寂寞，野橋僧去独裴回。","隔籬逢叟遙相賀，佇看芳田膏雨来。","（《四庫全书》本《韓內翰別集》。","）（按：《全唐诗》卷六八二收此诗，末句缺四字，今重錄。","）。"]', '诗', 'shi', '', NULL, '深村 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7dc1990-b61e-4fdc-b558-1ba4f2263c4c', '□明', '□明', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["迢迢恩義吹區分。","（《斷腸詩集前集》卷五《秋日雜書二首》鄭元佐注引。","）。"]', '["迢迢恩義吹區分。","（《斷腸诗集前集》卷五《秋日杂书二首》鄭元佐注引。","）。"]', '诗', 'shi', '', NULL, '□明 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a5588d5-47c9-42f8-9d3d-7208c52328e4', '', '', '7acbc895-0fa1-4ee5-8d1b-32e4effec9e3', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 王審知 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a24623f2-2da3-41ab-9118-d584a4dd09c8', '與僧對句（題擬）', '與僧对句（題擬）', '7acbc895-0fa1-4ee5-8d1b-32e4effec9e3', '唐', '["鉤偷荳蔻花。","（審知。","）日動瓏葱（左加王）。","（僧。","見《吟窗雜錄》卷三十八。","）。"]', '["鉤偷荳蔻花。","（審知。","）日动瓏葱（左加王）。","（僧。","见《吟窗杂錄》卷三十八。","）。"]', '诗', 'shi', '', NULL, '與僧對句（題擬） 王審知 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebc5e081-99ad-4689-bd88-5cdb9ec89c78', '題所居', '題所居', 'e13b86ca-ea24-47ed-aefc-6113cbedf27c', '唐', '["青山木笏尚初官，未老金魚是等閒。","世上幾多名將相，門前誰有此溪山。","市樓晚日紅高下，客艇春波綠往還。","人過小橋頻指點，全家都在畫圖間。","（見《嘉靖建陽縣志》卷七、周亮工《閩小紀》卷二）（按：《四庫全書》本《福建通志》卷七七題作《望考亭》。","）。"]', '["青山木笏尚初官，未老金鱼是等閒。","世上幾多名將相，门前誰有此溪山。","市楼晚日紅高下，客艇春波綠往還。","人過小橋頻指点，全家都在畫圖间。","（见《嘉靖建陽縣志》卷七、周亮工《閩小紀》卷二）（按：《四庫全书》本《福建通志》卷七七題作《望考亭》。","）。"]', '诗', 'shi', '', NULL, '題所居 黃子稜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11d108f2-012b-471b-9b8b-7779fa2d7d09', '示執坐禪者頌', '示執坐禪者頌', '2c577b11-750e-443f-90e0-97d50ffdcef4', '唐', '["大道分明絕點塵，何須長坐始相親。","遇緣儻解無非是，處憒那能有故新。","散誕肯齊支遁侶，逍遙曷與慧休鄰。","或遊泉石或闤闠，可謂煙霞物外人。","（按：《閩詩錄丙集》卷十九錄此詩作：「大道分明絕點塵，何須枯坐始相親。","杖藜日涉溪山趣，便是煙霞物外人。","」）。"]', '["大道分明絕点塵，何須长坐始相親。","遇緣儻解無非是，处憒那能有故新。","散誕肯齊支遁侶，逍遙曷與慧休鄰。","或游泉石或闤闠，可謂煙霞物外人。","（按：《閩诗錄丙集》卷十九錄此诗作：「大道分明絕点塵，何須枯坐始相親。","杖藜日涉溪山趣，便是煙霞物外人。","」）。"]', '诗', 'shi', '', NULL, '示執坐禪者頌 省澄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df3d1508-512b-41c4-8d1d-5a4cd6dbd254', '示坐禪方便頌', '示坐禪方便頌', '2c577b11-750e-443f-90e0-97d50ffdcef4', '唐', '["四威儀內坐爲先，澄慮身心漸坦然。","瞥爾有緣隨濁界，當須莫續是天年。","脩持只話（《五燈會元》作「秪學」）從功路，至理寧論在那邊。","一切時中常管帶，因緣相湊豁通玄。","（以上二首均見《景德傳燈錄》卷二九、《五燈會元》卷八。","）。"]', '["四威儀內坐爲先，澄慮身心漸坦然。","瞥爾有緣隨濁界，當須莫續是天年。","脩持只話（《五灯會元》作「秪学」）從功路，至理寧論在那邊。","一切时中常管带，因緣相湊豁通玄。","（以上二首均见《景德傳灯錄》卷二九、《五灯會元》卷八。","）。"]', '诗', 'shi', '', NULL, '示坐禪方便頌 省澄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('143a219a-cc54-42fc-b4d5-f68e2d92f4e7', '頌三首 一', '頌三首 一', '2c577b11-750e-443f-90e0-97d50ffdcef4', '唐', '["佛日沖天閑霧開，覺城東際象王迴。","善財五衆承當得，鶖子雖逢似不來。"]', '["佛日沖天闲霧开，覺城东際象王迴。","善財五衆承當得，鶖子雖逢似不来。"]', '诗', 'shi', '', NULL, '頌三首 一 省澄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6da06fb-bc27-443a-b601-a6962107b83c', '頌三首 二', '頌三首 二', '2c577b11-750e-443f-90e0-97d50ffdcef4', '唐', '["大士梁天請講開，始登蓮座躡梯迴。","皇情未曉志公說，大士《金剛》已講來。"]', '["大士梁天請講开，始登蓮座躡梯迴。","皇情未晓志公说，大士《金剛》已講来。"]', '诗', 'shi', '', NULL, '頌三首 二 省澄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eab4fc15-2306-4cc8-b680-4912ca7f6b2d', '頌三首 三', '頌三首 三', '2c577b11-750e-443f-90e0-97d50ffdcef4', '唐', '["吳坂當年塔未開，宋雲葱嶺見師迴。","手攜隻履分明箇，後代如何密薦來。","（見《祖堂集》卷十三。","）。"]', '["吳坂當年塔未开，宋云葱嶺见師迴。","手携隻履分明箇，後代如何密薦来。","（见《祖堂集》卷十三。","）。"]', '诗', 'shi', '', NULL, '頌三首 三 省澄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40f8eb4b-d360-4b74-bbed-956735735e84', '答國師', '答国師', '2c577b11-750e-443f-90e0-97d50ffdcef4', '唐', '["仰山嚙鏃話，擬議都難會。","指擬益後來，言損這邊在。","（《祖堂集》卷十八。","）。"]', '["仰山嚙鏃話，擬議都难會。","指擬益後来，言損這邊在。","（《祖堂集》卷十八。","）。"]', '诗', 'shi', '', NULL, '答國師 省澄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75fab832-bfce-448b-8fab-728ff2138c4a', '長慶和尚讚', '长慶和尚讚', '2c577b11-750e-443f-90e0-97d50ffdcef4', '唐', '["緇黃深鄭重，格峻實難當。","盡機相見處，立下閉僧堂。","（同前卷十。","）。"]', '["緇黄深鄭重，格峻實难當。","尽機相见处，立下閉僧堂。","（同前卷十。","）。"]', '诗', 'shi', '', NULL, '長慶和尚讚 省澄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71926b01-bec3-4f3f-8709-f29e60a77dcf', '', '', '441619ad-d503-49e6-9751-564564eded46', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 如體 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cba13298-13f4-44ce-a015-6cd5adca0485', '古曲偈（《祖堂集》卷十一作《雄頌》）', '古曲偈（《祖堂集》卷十一作《雄頌》）', '441619ad-d503-49e6-9751-564564eded46', '唐', '["古曲發聲雄，今古唱還同（《五燈會元》作「今時韻亦同」）。","若論第一拍（《五燈會元》作「指」），祖佛盡迷蹤。","（見《祖堂集》卷十、卷十一、《五燈會元》卷七。","）。"]', '["古曲發声雄，今古唱還同（《五灯會元》作「今时韻亦同」）。","若論第一拍（《五灯會元》作「指」），祖佛尽迷蹤。","（见《祖堂集》卷十、卷十一、《五灯會元》卷七。","）。"]', '诗', 'shi', '', NULL, '古曲偈（《祖堂集》卷十一作《雄頌》） 如體 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23217d42-8699-418d-975a-7bcd39074c30', '偈 一', '偈 一', '13bc0178-da74-4743-ad1c-4ab6ca7eb438', '唐', '["雪後始知松柏操，雲收方見濟淮（《五燈會元》作「河」）分。","不因世主令（《五燈會元》作「教」）還俗，那辨鷄羣與鶴羣。","多年塵土（《五燈會元》作「事」）謾騰騰，雖著伽黎（《五燈會元》作「方袍」）未是僧。","今日歸來酬本志，不妨留髮候然燈。","（《五燈會元》作「儀」）雖變道常存，混俗心源亦不昏。","試讀善財巡禮偈，當時豈例是（《五燈會元》作「作」）沙門。","（見《禪林僧寶傳》卷十、《五燈會元》卷十四。","）。"]', '["雪後始知松柏操，云收方见濟淮（《五灯會元》作「河」）分。","不因世主令（《五灯會元》作「教」）還俗，那辨鷄羣與鹤羣。","多年塵土（《五灯會元》作「事」）謾腾腾，雖著伽黎（《五灯會元》作「方袍」）未是僧。","今日归来酬本志，不妨留髮候然灯。","（《五灯會元》作「儀」）雖变道常存，混俗心源亦不昏。","試读善財巡禮偈，當时豈例是（《五灯會元》作「作」）沙门。","（见《禪林僧寶傳》卷十、《五灯會元》卷十四。","）。"]', '诗', 'shi', '', NULL, '偈 一 慧忠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbb70885-32ee-423f-8216-f92f151fa1e7', '送士濂弟之京', '送士濂弟之京', '13bc0178-da74-4743-ad1c-4ab6ca7eb438', '唐', '["行色翩翩入帝都，壯懷此去莫躊躇。","昔曾故國登高第，今向新朝再上書。","汝負才猷堪濟世，我慚衰朽合閒居。","[鴒]（鴿）原今日常相望，衣錦還鄉常有餘。","（見光緒廿六年刊翁昭泰纂《浦城縣志》卷三九引《章氏會譜》。","）（按：題下原注：「士濂，得象祖。","」宋祁《景文集》卷五九《文憲章公墓誌銘》：「曾祖仁嵩，仕李昪爲駕部郎中。","……祖士廉，汀州寧化令。","」）。"]', '["行色翩翩入帝都，壯懷此去莫躊躇。","昔曾故国登高第，今向新朝再上书。","汝負才猷堪濟世，我慚衰朽合閒居。","[鴒]（鴿）原今日常相望，衣錦還乡常有餘。","（见光緒廿六年刊翁昭泰纂《浦城縣志》卷三九引《章氏會譜》。","）（按：題下原注：「士濂，得象祖。","」宋祁《景文集》卷五九《文憲章公墓誌銘》：「曾祖仁嵩，仕李昪爲駕部郎中。","……祖士廉，汀州寧化令。","」）。"]', '诗', 'shi', '', NULL, '送士濂弟之京 慧忠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0917b245-9ccf-4591-8537-f9170ba79f2d', '南澗寺閣', '南澗寺閣', '661fd5de-df6f-42f7-aeea-2153f0d62c1e', '唐', '["上閣便見海，入門方是山。","塔高端似筆，城轉曲如環。","（見《輿地紀勝》卷一二八《福州》。","）。"]', '["上閣便见海，入门方是山。","塔高端似笔，城轉曲如环。","（见《輿地紀勝》卷一二八《福州》。","）。"]', '诗', 'shi', '', NULL, '南澗寺閣 王滌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23670fde-f37f-4873-9353-af3a5256d1e8', '行至雙溪口午炊主人開甕求詩作', '行至雙溪口午炊主人开甕求诗作', '66dc6ac4-3169-40c0-98d2-e76b172f894e', '唐', '["地僻雙溪合，村深邸舍稀。","主人如舊識，稚子覓新詩。","洗杓開春醖，淘粳作午炊。","春風吹酒醒，琴劍又追隨。"]', '["地僻雙溪合，村深邸舍稀。","主人如旧識，稚子覓新诗。","洗杓开春醖，淘粳作午炊。","春风吹酒醒，琴劍又追隨。"]', '诗', 'shi', '', NULL, '行至雙溪口午炊主人開甕求詩作 詹敦仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('978e2354-d939-44b6-8f29-daa3233ffd78', '歐陽長官見迓約余買鄰作此奉呈', '歐陽长官见迓約余買鄰作此奉呈', '66dc6ac4-3169-40c0-98d2-e76b172f894e', '唐', '["一識荆州面，令人意氣舒。","知心真我輩，遂性即吾廬。","佛耳雲堪掃，湖山水可漁。","明朝整琴劍，踏雪醉騎驢。","。"]', '["一識荆州面，令人意氣舒。","知心真我輩，遂性即吾廬。","佛耳云堪掃，湖山水可漁。","明朝整琴劍，踏雪醉騎驢。","。"]', '诗', 'shi', '', NULL, '歐陽長官見迓約余買鄰作此奉呈 詹敦仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e22167ee-f965-4208-8501-03a017cb21b6', '父子聯韻詩', '父子聯韻诗', '66dc6ac4-3169-40c0-98d2-e76b172f894e', '唐', '["夜靜月華明，（仁。","）秋深露氣清。","（琲。","）園林消溽暑，（仁。","）山水送寒聲。","（琲。","）菊富陶無酒，（仁。","）蓴肥翰可羹。","（琲。","）人生貴自適，（仁。","）世利不須營。","（琲。","）漫舞衣饒冷，（仁。","）狂歌酒易傾。","（琲。","）歡酬兒與父，（仁。","）今古夢還醒。","（琲。","）笑眼看毛鳳，（仁。","）長懷念鶺鴒。","（琲。","）干戈時已定，（仁。","）款款話平生。","（琲。","）（均見《閩詩錄乙集》卷四。","）。"]', '["夜静月华明，（仁。","）秋深露氣清。","（琲。","）园林消溽暑，（仁。","）山水送寒声。","（琲。","）菊富陶無酒，（仁。","）蓴肥翰可羹。","（琲。","）人生貴自適，（仁。","）世利不須營。","（琲。","）漫舞衣饒冷，（仁。","）狂歌酒易傾。","（琲。","）歡酬兒與父，（仁。","）今古梦還醒。","（琲。","）笑眼看毛鳳，（仁。","）长懷念鶺鴒。","（琲。","）干戈时已定，（仁。","）款款話平生。","（琲。","）（均见《閩诗錄乙集》卷四。","）。"]', '诗', 'shi', '', NULL, '父子聯韻詩 詹敦仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1756e341-72b4-4f47-a5af-af8b830f5002', '贈陳文亮（題擬）', '贈陳文亮（題擬）', 'a562277e-6bc8-42e0-ae64-ab07910d9e50', '唐', '["聞學湯休長鬢髭，罷脩禪頌不披緇。","龍盂虎錫安何處，象簡銀魚得幾時。","宗炳社拋雲一榻，李膺門醉酒千巵。","莫言誰管你閑事，今日塵中復是誰？","（周本淳校點本《詩話總龜》卷三九引《雅言系述》。","）。"]', '["闻学湯休长鬢髭，罷脩禪頌不披緇。","龙盂虎錫安何处，象簡銀鱼得幾时。","宗炳社拋云一榻，李膺门醉酒千巵。","莫言誰管你闲事，今日塵中复是誰？","（周本淳校点本《诗話總龟》卷三九引《雅言系述》。","）。"]', '诗', 'shi', '', NULL, '贈陳文亮（題擬） 文彧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d650a682-5b1b-41a8-b980-cef2da4fbd7f', '引陳文亮（題擬）', '引陳文亮（題擬）', 'a562277e-6bc8-42e0-ae64-ab07910d9e50', '唐', '["不知冥漠下，今似鷓鴣無？","（同前。","）。"]', '["不知冥漠下，今似鷓鴣無？","（同前。","）。"]', '诗', 'shi', '', NULL, '引陳文亮（題擬） 文彧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ce37fbe-9c8d-4d67-b3bc-5ac7c6456fa3', '', '', '2cd40d41-3727-43f2-b6df-1d3fce1d9541', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 陳文亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ae0ab08-4be1-4c4a-b714-e109db9ff702', '代遷客吟鷓鴣詩', '代遷客吟鷓鴣诗', '2cd40d41-3727-43f2-b6df-1d3fce1d9541', '唐', '["毛羽錦生光，江南是你鄉。","四山聲欲合，遷客路猶長。","相應隈叢竹，低飛近夕陽。","就中汨羅岸，非細斷人膓。","（同前。","）。"]', '["毛羽錦生光，江南是你乡。","四山声欲合，遷客路猶长。","相應隈叢竹，低飞近夕陽。","就中汨羅岸，非細斷人膓。","（同前。","）。"]', '诗', 'shi', '', NULL, '代遷客吟鷓鴣詩 陳文亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('893f7e13-908d-44a4-8523-75536057a602', '爲僧時作（題擬）', '爲僧时作（題擬）', '2cd40d41-3727-43f2-b6df-1d3fce1d9541', '唐', '["誰管你閑事，塵中自有人。","（同前。","）。"]', '["誰管你闲事，塵中自有人。","（同前。","）。"]', '诗', 'shi', '', NULL, '爲僧時作（題擬） 陳文亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('add5bc6b-cfc9-49e4-b097-708133b4ab22', '句', '句', '2cd40d41-3727-43f2-b6df-1d3fce1d9541', '唐', '["草鋪春□濶，兵偃塞垣操。","（《增修詩話總龜》卷十六引《古今詩話》。","）。"]', '["草鋪春□濶，兵偃塞垣操。","（《增修诗話總龟》卷十六引《古今诗話》。","）。"]', '诗', 'shi', '', NULL, '句 陳文亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('602e8f3b-b857-4250-87df-cf346865ea80', '句', '句', '5aac325d-4142-4298-8d58-48492c3c53c5', '唐', '["島山斷雲垂極浦。","（《江湖小集》卷六紹嵩《江浙紀行集句詩》引。","）。"]', '["島山斷云垂極浦。","（《江湖小集》卷六紹嵩《江浙紀行集句诗》引。","）。"]', '诗', 'shi', '', NULL, '句 楊鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1117e441-568a-4ddb-9e71-bb0a6d9032ca', '', '', 'c9d02e23-39e1-4ed6-9965-c4891475d0b4', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 玄應 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df1df9c4-9274-4a09-adf3-159e98b6cc7e', '臨寂示漳州刺史陳文顥偈（題擬）', '臨寂示漳州刺史陳文顥偈（題擬）', 'c9d02e23-39e1-4ed6-9965-c4891475d0b4', '唐', '["今年六十六，世壽有延促。","無生火熾然，有爲薪不續。","出谷與歸源，一時俱備足。","（《小傳》卷二十四、《五燈會元》卷八。","）。"]', '["今年六十六，世壽有延促。","無生火熾然，有爲薪不續。","出谷與归源，一时俱備足。","（《小傳》卷二十四、《五灯會元》卷八。","）。"]', '诗', 'shi', '', NULL, '臨寂示漳州刺史陳文顥偈（題擬） 玄應 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43141c29-dc40-49f0-bdfb-2a7a8093e0dd', '答冥使（題擬）', '答冥使（題擬）', '8e46dbeb-d200-4ccd-abaf-07789352ba0c', '唐', '["三年過了又三年，閱遍《華嚴》滿五千。","功德完時珍重去，何勞使者上高田。","（同治《仙遊縣志》卷四十五。","）。"]', '["三年過了又三年，閱遍《华嚴》满五千。","功德完时珍重去，何勞使者上高田。","（同治《仙游縣志》卷四十五。","）。"]', '诗', 'shi', '', NULL, '答冥使（題擬） 定御 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ab487b7-eb13-49f5-9e1a-8cc6e36ef10d', '汀州定光南安巖詩二首（題擬） 一', '汀州定光南安巖诗二首（題擬） 一', 'ac6977d3-20d7-4655-80b1-35dd37e884a5', '唐', '["石聳靈巖接太虛，百千年稱定光居。","未知天上何方有，應是人間別地無。"]', '["石聳靈巖接太虛，百千年稱定光居。","未知天上何方有，應是人间別地無。"]', '诗', 'shi', '', NULL, '汀州定光南安巖詩二首（題擬） 一 鄭元弼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb02b57a-03db-4ea9-9525-7160279d008e', '汀州定光南安巖詩二首（題擬） 二', '汀州定光南安巖诗二首（題擬） 二', 'ac6977d3-20d7-4655-80b1-35dd37e884a5', '唐', '["香風影裏迎新魄，梵貝聲中見落暉。","自幸勞生名利役，不能來此共忘機。","路入雲山幾萬層，豁然巖宇勢崢嶸。","地從物外囂塵斷，天到壺中日月明。","（見《輿地紀勝》卷一三二《汀州》。","）（按：《輿地紀勝》收二詩，列宋郭祥正詩前，署「鄭弼」，應即鄭元弼。","同書卷一三五《輿化軍》有其傳云：「鄭元弼，仙遊人。","唐昭宗景福二年獻《白巖集》十卷，載《唐藝文志》。","遷御史中丞。","天復中𧊲伏於仙遊之白巖。","」可證。","惟此傳全部誤錄其父良士事跡，不免疏謬。","《仙遊志》卷四載鄭氏父子事跡甚詳，可參看。","）。"]', '["香风影裏迎新魄，梵貝声中见落暉。","自幸勞生名利役，不能来此共忘機。","路入云山幾万層，豁然巖宇勢崢嶸。","地從物外囂塵斷，天到壺中日月明。","（见《輿地紀勝》卷一三二《汀州》。","）（按：《輿地紀勝》收二诗，列宋郭祥正诗前，署「鄭弼」，應即鄭元弼。","同书卷一三五《輿化軍》有其傳云：「鄭元弼，仙游人。","唐昭宗景福二年獻《白巖集》十卷，載《唐藝文志》。","遷御史中丞。","天复中𧊲伏於仙游之白巖。","」可證。","惟此傳全部誤錄其父良士事跡，不免疏謬。","《仙游志》卷四載鄭氏父子事跡甚詳，可參看。","）。"]', '诗', 'shi', '', NULL, '汀州定光南安巖詩二首（題擬） 二 鄭元弼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51a864e6-5201-4f55-8b5a-e8f9e515ff54', '夜覩豺虎奔至契如庵前自然馴遶因有詩（題擬）', '夜覩豺虎奔至契如庵前自然馴遶因有诗（題擬）', '8c07c2ad-c545-4770-a1d5-5589dd8df8d2', '唐', '["行不等閑行，誰知去住情。","一餐猶未飽，萬戶勿聊生。","非道應難伏，空拳莫與爭。","龍吟雲起處，閑嘯兩三聲。","（見《五燈會元》卷八。","）。"]', '["行不等闲行，誰知去住情。","一餐猶未飽，万戶勿聊生。","非道應难伏，空拳莫與爭。","龙吟云起处，闲嘯兩三声。","（见《五灯會元》卷八。","）。"]', '诗', 'shi', '', NULL, '夜覩豺虎奔至契如庵前自然馴遶因有詩（題擬） 清豁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97de461e-d911-4e82-9a6a-70c1f12e97a8', '天字謎', '天字謎', 'a7725ee6-8da4-46e6-b60b-9799636ce0cf', '唐', '["露頭更一日，真是艷陽根。","（見《說郛》卷六一《清異錄》。","）。"]', '["露头更一日，真是艷陽根。","（见《说郛》卷六一《清異錄》。","）。"]', '诗', 'shi', '', NULL, '天字謎 韋添 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1423cd5a-2ecb-4703-b938-63b033f34794', '', '', '333e2fb5-2d84-4f27-8238-f78f94620aff', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 錢熙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26bedca3-b150-49c1-9f77-29ef6d906898', '清源山（題擬）', '清源山（題擬）', '333e2fb5-2d84-4f27-8238-f78f94620aff', '唐', '["巍峨堆壓郡城陰，秀出天涯（《泉州府志》作「崖」）幾萬尋。","翠影倒時吞半郭，嵐光凝處滴疎林。","（見《古今圖書集成·山川典》卷一八五《泉山部》、同治庚午年刊黃任等纂《泉州府志》卷六。","）。"]', '["巍峨堆壓郡城陰，秀出天涯（《泉州府志》作「崖」）幾万尋。","翠影倒时吞半郭，嵐光凝处滴疎林。","（见《古今圖书集成·山川典》卷一八五《泉山部》、同治庚午年刊黄任等纂《泉州府志》卷六。","）。"]', '诗', 'shi', '', NULL, '清源山（題擬） 錢熙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e48853c2-a8fe-4811-8e0f-5d6e05219ccf', '龍首山', '龙首山', '333e2fb5-2d84-4f27-8238-f78f94620aff', '唐', '["殘年仍置閏，五日恰逢春。","攜酒客不賞，敲門僧不嗔。","雙松如拱立，萬井自橫廹。","精舍故盤礴，元規塵上人。","（同治《泉州府志》卷六）。"]', '["殘年仍置閏，五日恰逢春。","携酒客不賞，敲门僧不嗔。","雙松如拱立，万井自橫廹。","精舍故盤礴，元規塵上人。","（同治《泉州府志》卷六）。"]', '诗', 'shi', '', NULL, '龍首山 錢熙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4f4366c-16f0-466b-9032-8aea903736e8', '九日溪偶成', '九日溪偶成', '333e2fb5-2d84-4f27-8238-f78f94620aff', '唐', '["漁家深處住。","鷗鷺泊柴扉。","雨過山（《清源文獻》作「莎」）迷徑，潮來風滿衣。","岸幽分遠景，波冷漾清（《清源文獻》作「晴」）暉。","却憶曾遊賞，嚴陵有舊磯。","（見同書卷七、《宋詩紀事》卷四引《清源文獻》）（按：《輿地紀勝》、《全芳備祖》、《皇朝事實類苑》引《楊文公談苑》尚存熙詩多首，似皆入宋後作，茲不錄。","）。"]', '["漁家深处住。","鷗鷺泊柴扉。","雨過山（《清源文獻》作「莎」）迷徑，潮来风满衣。","岸幽分远景，波冷漾清（《清源文獻》作「晴」）暉。","却憶曾游賞，嚴陵有旧磯。","（见同书卷七、《宋诗紀事》卷四引《清源文獻》）（按：《輿地紀勝》、《全芳備祖》、《皇朝事實類苑》引《楊文公談苑》尚存熙诗多首，似皆入宋後作，茲不錄。","）。"]', '诗', 'shi', '', NULL, '九日溪偶成 錢熙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7a56af8-ebb5-481a-bdda-3b2e867a667f', '添撰享太廟樂章 敬宗廟奏', '添撰享太廟乐章 敬宗廟奏', '143e4f44-795c-4f88-ab3a-f2ef5351efe2', '唐', '["大孝顯慶，景運應時。","德合天地，威戢蠻夷。","神呈福祉，歲有經□。","無私之禮，□□□□。","（《大唐郊祀錄》卷九）。"]', '["大孝显慶，景運應时。","德合天地，威戢蠻夷。","神呈福祉，歲有經□。","無私之禮，□□□□。","（《大唐郊祀錄》卷九）。"]', '诗', 'shi', '', NULL, '添撰享太廟樂章 敬宗廟奏 張連 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('235ee47e-f1da-4064-ae77-17b3b7f8f27e', '添撰享太廟樂章 文宗廟奏', '添撰享太廟乐章 文宗廟奏', '143e4f44-795c-4f88-ab3a-f2ef5351efe2', '唐', '["赫爾昭代，顯應元亨。","祥符史牒，德振文明。","風調雨順，海晏河清。","應延大寶，千秋化成。","（同前）。"]', '["赫爾昭代，显應元亨。","祥符史牒，德振文明。","风調雨順，海晏河清。","應延大寶，千秋化成。","（同前）。"]', '诗', 'shi', '', NULL, '添撰享太廟樂章 文宗廟奏 張連 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79dddbf0-eed5-4ccb-9afa-ecb15eba81c8', '補迎神奏永和之舞九變第二奏', '補迎神奏永和之舞九变第二奏', 'cee21fad-afab-4ab6-ab9c-2cca867cf74d', '唐', '["說祝於室，焫蕭燃脂。","几筵斯設，妥以皇詩。","雲韶清越，絳服離披。","僾然如此，永感孝思。","（《大唐郊祀錄》卷九）。"]', '["说祝於室，焫蕭燃脂。","几筵斯設，妥以皇诗。","云韶清越，絳服離披。","僾然如此，永感孝思。","（《大唐郊祀錄》卷九）。"]', '诗', 'shi', '', NULL, '補迎神奏永和之舞九變第二奏 陳致雍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18393895-2e85-4cfe-95ed-6cca891295da', '偈頌（幷序○序爲南嶽齊己撰） 一', '偈頌（幷序○序爲南嶽齊己撰） 一', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["夫人學道莫貪求，萬事無心道合頭。","無心體得（《景德傳燈錄》卷二九作「始體」）無心道，體得無心道也（《景德傳燈錄》作「亦」）休。"]', '["夫人学道莫貪求，万事無心道合头。","無心體得（《景德傳灯錄》卷二九作「始體」）無心道，體得無心道也（《景德傳灯錄》作「亦」）休。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 一 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('514663a9-8554-4bfd-98bd-fe1c82246387', '偈頌（幷序○序爲南嶽齊己撰） 二', '偈頌（幷序○序爲南嶽齊己撰） 二', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["學道先須且學貧，學貧貧後道方親。","一朝體得成貧道，道用還如貧底人。"]', '["学道先須且学貧，学貧貧後道方親。","一朝體得成貧道，道用還如貧底人。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 二 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e698d0f-a881-452c-a5ac-21c5e807a996', '偈頌（幷序○序爲南嶽齊己撰） 三', '偈頌（幷序○序爲南嶽齊己撰） 三', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["學道蒙師指（斯二一六五卷作「止」）却閑，無中有路隱人間。","直饒（《景德傳燈錄》卷二九作「饒君」）講得（《祖堂集》卷八作「時人盡講」、斯二一六五卷作「饒君會得」）千經論，一句臨機（《祖堂集》、斯二一六五卷作「時」）下口難。","。"]', '["学道蒙師指（斯二一六五卷作「止」）却闲，無中有路隐人间。","直饒（《景德傳灯錄》卷二九作「饒君」）講得（《祖堂集》卷八作「时人尽講」、斯二一六五卷作「饒君會得」）千經論，一句臨機（《祖堂集》、斯二一六五卷作「时」）下口难。","。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 三 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81acb8a1-e523-4df1-a678-c18be9995cf1', '偈頌（幷序○序爲南嶽齊己撰） 四', '偈頌（幷序○序爲南嶽齊己撰） 四', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["學道先須立自身，直教行處不生塵。","僧真不假居巖（《祖堂集》作「俱言」）室，到處無心即在人。"]', '["学道先須立自身，直教行处不生塵。","僧真不假居巖（《祖堂集》作「俱言」）室，到处無心即在人。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 四 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf87793a-065d-471f-a89a-0f9c5da59ce9', '偈頌（幷序○序爲南嶽齊己撰） 五', '偈頌（幷序○序爲南嶽齊己撰） 五', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["學道先須有悟由，還如曾鬬快龍舟。","雖然舊閣閑（《傳燈錄》作「於」）田地，一度贏求方始休。","（又見《僧寶傳》卷九。","）。"]', '["学道先須有悟由，還如曾鬬快龙舟。","雖然旧閣闲（《傳灯錄》作「於」）田地，一度贏求方始休。","（又见《僧寶傳》卷九。","）。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 五 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abb8162f-b3ee-4520-9c54-eaacab1e7e33', '偈頌（幷序○序爲南嶽齊己撰） 六', '偈頌（幷序○序爲南嶽齊己撰） 六', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["學道先須息萬機，將機學道轉生疑。","此門廣大無遮障，學者雖多達者稀。"]', '["学道先須息万機，將機学道轉生疑。","此门廣大無遮障，学者雖多達者稀。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 六 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cc25e03-73c2-452d-9aa8-649f6c71b3fe', '偈頌（幷序○序爲南嶽齊己撰） 七', '偈頌（幷序○序爲南嶽齊己撰） 七', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["一得無心便道情（《景德傳燈錄》卷二九作「心」），六門休歇不勞形。","有緣不是余朋友，無用雙眉却弟兄。"]', '["一得無心便道情（《景德傳灯錄》卷二九作「心」），六门休歇不勞形。","有緣不是余朋友，無用雙眉却弟兄。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 七 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1c196e7-ef0c-479f-8be0-0387098b25c9', '偈頌（幷序○序爲南嶽齊己撰） 八', '偈頌（幷序○序爲南嶽齊己撰） 八', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["一得無心便豁空，祇因先聖祖門通。","箇中若向三乘學，萬劫無因得遇逢。"]', '["一得無心便豁空，祇因先聖祖门通。","箇中若向三乘学，万劫無因得遇逢。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 八 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc038b95-b2f4-4b35-8840-2c1f897a9be7', '偈頌（幷序○序爲南嶽齊己撰） 九', '偈頌（幷序○序爲南嶽齊己撰） 九', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["自體如如任運常，因茲行歇在三湘。","雙眉無用是毫相，說處無分舌廣長。"]', '["自體如如任運常，因茲行歇在三湘。","雙眉無用是毫相，说处無分舌廣长。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 九 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('460f77ab-9c64-4f82-93db-b2ef7414f9fd', '偈頌（幷序○序爲南嶽齊己撰） 十', '偈頌（幷序○序爲南嶽齊己撰） 十', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["自小從師學祖宗，閑華猶似纏人蜂。","僧真不假栖（《景德傳燈錄》卷二九作「居」）雲外，得後無心色亦空（《景德傳燈錄》作「知無色自空」。","）。"]', '["自小從師学祖宗，闲华猶似纏人蜂。","僧真不假栖（《景德傳灯錄》卷二九作「居」）云外，得後無心色亦空（《景德傳灯錄》作「知無色自空」。","）。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 十 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('984efbda-2271-4ce0-ad36-b6cd28e9c458', '偈頌（幷序○序爲南嶽齊己撰） 十一', '偈頌（幷序○序爲南嶽齊己撰） 十一', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["得聖超凡不作聲，臥龍長怖（斯二一六五卷作「布」）碧潭清。","人生若得長（斯卷作「常」）如此，大地那能留一名。"]', '["得聖超凡不作声，臥龙长怖（斯二一六五卷作「布」）碧潭清。","人生若得长（斯卷作「常」）如此，大地那能留一名。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 十一 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e687a0cd-156a-4d14-9729-a132b00672ef', '偈頌（幷序○序爲南嶽齊己撰） 十二', '偈頌（幷序○序爲南嶽齊己撰） 十二', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["得道還同未得人（《景德傳燈錄》卷二九作「悟了還同未悟人」），心無勝負自安神。"]', '["得道還同未得人（《景德傳灯錄》卷二九作「悟了還同未悟人」），心無勝負自安神。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 十二 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8105bbf2-fdf0-47bd-928d-52d83c263f6e', '偈頌（幷序○序爲南嶽齊己撰） 十三', '偈頌（幷序○序爲南嶽齊己撰） 十三', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["心空不及道空安，道與心空狀一般。","參玄不是道空士，一乍相逢不易看。","（又見《祖堂集》卷二十、《景德傳燈錄》卷二九）。"]', '["心空不及道空安，道與心空狀一般。","參玄不是道空士，一乍相逢不易看。","（又见《祖堂集》卷二十、《景德傳灯錄》卷二九）。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 十三 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf200ae5-48f8-4041-bceb-598b808a68ab', '偈頌（幷序○序爲南嶽齊己撰） 十四', '偈頌（幷序○序爲南嶽齊己撰） 十四', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["此生不息息何時，息在今生共要知。","心息仙因（《景德傳燈錄》卷二九作「只緣」）無妄想，妄空（《景德傳燈錄》作「除」）心息是休時。"]', '["此生不息息何时，息在今生共要知。","心息仙因（《景德傳灯錄》卷二九作「只緣」）無妄想，妄空（《景德傳灯錄》作「除」）心息是休时。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 十四 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43c986ee-1be1-41f1-a2ab-39e2f5824040', '偈頌（幷序○序爲南嶽齊己撰） 十五', '偈頌（幷序○序爲南嶽齊己撰） 十五', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["劫火曾將無氣吹，不勞心力當時萎。","人天不見風塵起，怖息無招各自歸。","。"]', '["劫火曾將無氣吹，不勞心力當时萎。","人天不见风塵起，怖息無招各自归。","。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 十五 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('228fef27-ae89-4cc6-9ef9-bef76a4b1948', '偈頌（幷序○序爲南嶽齊己撰） 十六', '偈頌（幷序○序爲南嶽齊己撰） 十六', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["人若無心稱道情，覷見（《祖堂集》卷八作「識得」）無明道已明。","人能弘道道能顯，道在人中人自寧。"]', '["人若無心稱道情，覷见（《祖堂集》卷八作「識得」）無明道已明。","人能弘道道能显，道在人中人自寧。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 十六 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8539d46f-8577-4235-af71-42f874977ef3', '偈頌（幷序○序爲南嶽齊己撰） 十七', '偈頌（幷序○序爲南嶽齊己撰） 十七', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["何事朝愁與暮愁，少年不學老還羞。","驪珠不是驪龍惜，自是時人不解求。"]', '["何事朝愁與暮愁，少年不学老還羞。","驪珠不是驪龙惜，自是时人不解求。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 十七 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d69e9b23-4f01-441b-a45a-0d43e41ef7eb', '偈頌（幷序○序爲南嶽齊己撰） 十八', '偈頌（幷序○序爲南嶽齊己撰） 十八', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["了得心源處處安，何須終日對林巒。","玉向火中燒轉潤，蓮華在水葉長乾。"]', '["了得心源处处安，何須終日对林巒。","玉向火中燒轉潤，蓮华在水葉长乾。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 十八 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53094029-075b-4f61-8ab9-45e15a8f7db4', '偈頌（幷序○序爲南嶽齊己撰） 十九', '偈頌（幷序○序爲南嶽齊己撰） 十九', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["掃地煎茶及針把，更無餘事可留心。"]', '["掃地煎茶及針把，更無餘事可留心。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 十九 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdf61475-6e70-4d11-8eec-47ae8b7ba12e', '偈頌（幷序○序爲南嶽齊己撰） 二十', '偈頌（幷序○序爲南嶽齊己撰） 二十', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["或居城郭或居山，得道無心在處閑。","實似小兒歸父母，身衣隨分補遮寒。"]', '["或居城郭或居山，得道無心在处闲。","實似小兒归父母，身衣隨分補遮寒。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 二十 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a943b20f-1cb1-46d1-ad52-29bc18525a0a', '偈頌（幷序○序爲南嶽齊己撰） 二十一', '偈頌（幷序○序爲南嶽齊己撰） 二十一', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["道情六用如眉用，用處如眉始可觀。","人見道時如寂寞，人情全是道情安。"]', '["道情六用如眉用，用处如眉始可观。","人见道时如寂寞，人情全是道情安。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 二十一 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('004a2f19-0437-4d4f-ad42-0fd032d98f6c', '偈頌（幷序○序爲南嶽齊己撰） 二十二', '偈頌（幷序○序爲南嶽齊己撰） 二十二', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["擬學論情實苦哉，疑心不斷妄難摧。","未了攜囊須且去，得閑無事却肯伊。"]', '["擬学論情實苦哉，疑心不斷妄难摧。","未了携囊須且去，得闲無事却肯伊。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 二十二 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0816932-f6e6-495a-b0d4-274528eb3112', '偈頌（幷序○序爲南嶽齊己撰） 二十三', '偈頌（幷序○序爲南嶽齊己撰） 二十三', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["四氣吹成物不虛，可憐青葉下垂珠。","雖然種得無心寶，一任傍人恣意須。"]', '["四氣吹成物不虛，可怜青葉下垂珠。","雖然種得無心寶，一任傍人恣意須。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 二十三 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6765e15d-7916-4f6a-9e05-25599ffea48a', '偈頌（幷序○序爲南嶽齊己撰） 二十四', '偈頌（幷序○序爲南嶽齊己撰） 二十四', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["世人無心不能治，致禍愁生累及眉。","一朝體得心無事，眉放毫光自不知。"]', '["世人無心不能治，致禍愁生累及眉。","一朝體得心無事，眉放毫光自不知。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 二十四 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6b7c612-b318-44ee-9fc9-a016e38b3418', '偈頌（幷序○序爲南嶽齊己撰） 二十五', '偈頌（幷序○序爲南嶽齊己撰） 二十五', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["僧房閴寂夏修持，閉戶疎人怪亦知。","儂家自有同風事，千里無來却肯伊。"]', '["僧房閴寂夏修持，閉戶疎人怪亦知。","儂家自有同风事，千里無来却肯伊。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 二十五 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f94100e7-a803-4584-a1fc-667451ec9ffa', '偈頌（幷序○序爲南嶽齊己撰） 二十六', '偈頌（幷序○序爲南嶽齊己撰） 二十六', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["臨窗不覺寸陰移，火急修行早是遲。","白日祇陪人事過，園林那得道成時。"]', '["臨窗不覺寸陰移，火急修行早是遲。","白日祇陪人事過，园林那得道成时。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 二十六 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5728316f-ee67-4171-835c-01e2e12026a0', '偈頌（幷序○序爲南嶽齊己撰） 二十七', '偈頌（幷序○序爲南嶽齊己撰） 二十七', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["緣覺（《景德傳燈錄》卷二九作「菩薩」）聲聞未盡空，人天來往訪真宗。","爭如（《景德傳燈錄》作「知」）佛是無疑士，端坐無心祇麽通。"]', '["緣覺（《景德傳灯錄》卷二九作「菩薩」）声闻未尽空，人天来往訪真宗。","爭如（《景德傳灯錄》作「知」）佛是無疑士，端坐無心祇麽通。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 二十七 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52e3f8a3-36f7-416c-a233-35132aced2a8', '偈頌（幷序○序爲南嶽齊己撰） 二十八', '偈頌（幷序○序爲南嶽齊己撰） 二十八', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["頂相擬求終不見，應緣同谷不違方。","此門別處無尋路，祇有休心更廝當。"]', '["頂相擬求終不见，應緣同谷不違方。","此门別处無尋路，祇有休心更廝當。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 二十八 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb6b3fd7-f00a-465e-a8d2-259c1079711c', '偈頌（幷序○序爲南嶽齊己撰） 二十九', '偈頌（幷序○序爲南嶽齊己撰） 二十九', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["三事無憂樂道情，且陪雲水不求名。","任渠更作千般解，體自無暇不染青。"]', '["三事無憂乐道情，且陪云水不求名。","任渠更作千般解，體自無暇不染青。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 二十九 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95deae69-7a70-443b-bc96-c726ac09c99b', '偈頌（幷序○序爲南嶽齊己撰） 三十', '偈頌（幷序○序爲南嶽齊己撰） 三十', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["將心除妄妄難忘，不體玄微事轉忙。","未了祇言如來秘，覺後方知不覆藏。","。"]', '["將心除妄妄难忘，不體玄微事轉忙。","未了祇言如来秘，覺後方知不覆藏。","。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 三十 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a4e6c72-8662-41bf-b867-5a6ccfecdb9f', '偈頌（幷序○序爲南嶽齊己撰） 三十一', '偈頌（幷序○序爲南嶽齊己撰） 三十一', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["道者（《傳燈錄》作「學道」）無端學畫龍，元來未得筆頭蹤。","一朝體得真龍後，始覺平生（《傳燈錄》作「方覺從前」）枉用功。"]', '["道者（《傳灯錄》作「学道」）無端学畫龙，元来未得笔头蹤。","一朝體得真龙後，始覺平生（《傳灯錄》作「方覺從前」）枉用功。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 三十一 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cedf130-5eb4-46f0-afcc-13fe178c6f8e', '偈頌（幷序○序爲南嶽齊己撰） 三十二', '偈頌（幷序○序爲南嶽齊己撰） 三十二', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["凡有含生共一塵，先聖精勤早出倫。","彼既丈夫我亦爾，誰遣他春我不春。"]', '["凡有含生共一塵，先聖精勤早出倫。","彼既丈夫我亦爾，誰遣他春我不春。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 三十二 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('318b2b48-17df-4d7f-84e5-28f64ff66fa9', '偈頌（幷序○序爲南嶽齊己撰） 三十三', '偈頌（幷序○序爲南嶽齊己撰） 三十三', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["毫釐有差千里隔，剎那一悟祖師齊。","玄微須向玄中體，道用還教道者知。"]', '["毫釐有差千里隔，剎那一悟祖師齊。","玄微須向玄中體，道用還教道者知。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 三十三 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f17bcd21-6f65-4a07-8ef0-cc5ab7b9a4c7', '偈頌（幷序○序爲南嶽齊己撰） 三十四', '偈頌（幷序○序爲南嶽齊己撰） 三十四', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["參玄道者莫因循（《祖堂集》卷八作「參尋玄道莫因修」），學處須教皂白分。","千聖從來無異路，妄緣機智有多門（《祖堂集》作「聞」）。"]', '["參玄道者莫因循（《祖堂集》卷八作「參尋玄道莫因修」），学处須教皂白分。","千聖從来無異路，妄緣機智有多门（《祖堂集》作「闻」）。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 三十四 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89b9832f-7753-43c4-a4b7-365038aae436', '偈頌（幷序○序爲南嶽齊己撰） 三十五', '偈頌（幷序○序爲南嶽齊己撰） 三十五', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["向前吳氏學丹青，不體僧[繇]（瑤）事不精。","畫馬不成驢亦失，時人盡笑枉平生。"]', '["向前吳氏学丹青，不體僧[繇]（瑤）事不精。","畫马不成驢亦失，时人尽笑枉平生。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 三十五 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e9c6511-ff21-4873-8219-440c57bb5adc', '偈頌（幷序○序爲南嶽齊己撰） 三十六', '偈頌（幷序○序爲南嶽齊己撰） 三十六', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["粉壁朱門事豈繁，高牆扃戶住如山。","莫言城郭無休士，人若無心在處閑。"]', '["粉壁朱门事豈繁，高牆扃戶住如山。","莫言城郭無休士，人若無心在处闲。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 三十六 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c86e628f-69e3-4322-a3c2-43b875dae2a8', '偈頌（幷序○序爲南嶽齊己撰） 三十七', '偈頌（幷序○序爲南嶽齊己撰） 三十七', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["儉用貴圖延日月，補衣還免到人間。","無心道者方如此，未得無心也大難。"]', '["儉用貴圖延日月，補衣還免到人间。","無心道者方如此，未得無心也大难。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 三十七 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32abb755-5e1f-4618-8cac-a3ae89f953ab', '偈頌（幷序○序爲南嶽齊己撰） 三十八', '偈頌（幷序○序爲南嶽齊己撰） 三十八', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["冷月霜天道者孤，一堂禪侶守寒爐。","衲衣穿處冰侵骨，夜坐更深炭也無。"]', '["冷月霜天道者孤，一堂禪侶守寒爐。","衲衣穿处冰侵骨，夜坐更深炭也無。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 三十八 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b520b74-9df2-4855-a898-f4169b1c0fa9', '偈頌（幷序○序爲南嶽齊己撰） 三十九', '偈頌（幷序○序爲南嶽齊己撰） 三十九', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["萬般施設不如常，又不驚人又久長。","如常恰似秋風至，無意涼人人自涼。","（又見《祖堂集》卷八）。"]', '["万般施設不如常，又不驚人又久长。","如常恰似秋风至，無意涼人人自涼。","（又见《祖堂集》卷八）。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 三十九 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c1aa12c-07f8-415c-b3a8-a0a52a6ed63f', '偈頌（幷序○序爲南嶽齊己撰） 四十', '偈頌（幷序○序爲南嶽齊己撰） 四十', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["膝袴斑闌火炙成，渾身破碎不能驚。","山房獨坐眼極樂，豁然無事暢人情。"]', '["膝袴斑闌火炙成，渾身破碎不能驚。","山房独坐眼極乐，豁然無事暢人情。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 四十 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2a30d72-90cf-4436-9c2d-f53d11494bfe', '偈頌（幷序○序爲南嶽齊己撰） 四十一', '偈頌（幷序○序爲南嶽齊己撰） 四十一', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["一室一牀居物外，一瓶一鉢寄生涯。","門前縱有通村路，是我何曾識一家。"]', '["一室一牀居物外，一瓶一鉢寄生涯。","门前縱有通村路，是我何曾識一家。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 四十一 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36cbce1b-3552-4147-ba5a-0edbdece9e91', '偈頌（幷序○序爲南嶽齊己撰） 四十二', '偈頌（幷序○序爲南嶽齊己撰） 四十二', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["昔生未了今須了，此生度取累此身。","古佛未悟同今者，悟了今人即古人。"]', '["昔生未了今須了，此生度取累此身。","古佛未悟同今者，悟了今人即古人。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 四十二 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b72b0da6-c480-4edd-9acc-0e3bca21cc8e', '偈頌（幷序○序爲南嶽齊己撰） 四十三', '偈頌（幷序○序爲南嶽齊己撰） 四十三', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["木食草衣心似月，一生無念復無涯。","時人若問居何處，淥水青山是我家。"]', '["木食草衣心似月，一生無念复無涯。","时人若问居何处，淥水青山是我家。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 四十三 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40b45894-9c1c-42f9-ad07-62e1ecfc96a7', '偈頌（幷序○序爲南嶽齊己撰） 四十四', '偈頌（幷序○序爲南嶽齊己撰） 四十四', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["朝看花開滿樹紅，暮觀花落樹還空。","若將華比人間事，花與人間事一同。"]', '["朝看花开满樹紅，暮观花落樹還空。","若將华比人间事，花與人间事一同。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 四十四 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ab7a2bd-f1fd-418b-adce-197a128d070e', '偈頌（幷序○序爲南嶽齊己撰） 四十五', '偈頌（幷序○序爲南嶽齊己撰） 四十五', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["柳色含煙山花笑，鶯啼林下幾人知？","後生正好尋玄路，莫棄光陰虛度時。","。"]', '["柳色含煙山花笑，鶯啼林下幾人知？","後生正好尋玄路，莫棄光陰虛度时。","。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 四十五 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c877171d-1242-4240-b826-2e7be122672d', '偈頌（幷序○序爲南嶽齊己撰） 四十六', '偈頌（幷序○序爲南嶽齊己撰） 四十六', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["志慕空門誓不休，莫將閑事掛心頭。","白雲便是修行伴，從聽時光去不留。"]', '["志慕空门誓不休，莫將闲事掛心头。","白云便是修行伴，從听时光去不留。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 四十六 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e456658-96b2-4375-b281-ffda80adf9b1', '偈頌（幷序○序爲南嶽齊己撰） 四十七', '偈頌（幷序○序爲南嶽齊己撰） 四十七', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["知身是幻不求名，浮漚出沒幾時生。","借問雲山學道者，此去修行早晚成。"]', '["知身是幻不求名，浮漚出沒幾时生。","借问云山学道者，此去修行早晚成。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 四十七 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5419a820-25a2-4603-a207-b629f494641b', '偈頌（幷序○序爲南嶽齊己撰） 四十八', '偈頌（幷序○序爲南嶽齊己撰） 四十八', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["在夢那知夢是虛，覺來方覺夢中無。","迷時恰似夢中士，悟後還同睡起夫。"]', '["在梦那知梦是虛，覺来方覺梦中無。","迷时恰似梦中士，悟後還同睡起夫。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 四十八 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f740b55-c8f3-4c62-b51e-b6dfb2dcfcbc', '偈頌（幷序○序爲南嶽齊己撰） 四十九', '偈頌（幷序○序爲南嶽齊己撰） 四十九', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["迷人未了勸盲聾，土上加泥更一重。","了（《景德傳燈錄》卷二九作「悟」）人有意如迷意，只在迷中迷不逢。"]', '["迷人未了勸盲聾，土上加泥更一重。","了（《景德傳灯錄》卷二九作「悟」）人有意如迷意，只在迷中迷不逢。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 四十九 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38f254ff-a9a9-4b25-8e8b-69b611b80451', '偈頌（幷序○序爲南嶽齊己撰） 五十', '偈頌（幷序○序爲南嶽齊己撰） 五十', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["人情濃厚道情微，道用人情世豈知。","空有人情無道用，人情能得幾多時？","（又見《景德傳燈錄》卷二九）。"]', '["人情濃厚道情微，道用人情世豈知。","空有人情無道用，人情能得幾多时？","（又见《景德傳灯錄》卷二九）。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 五十 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('944e4d92-7594-4579-9e10-a7e5cbf28bc4', '偈頌（幷序○序爲南嶽齊己撰） 五十一', '偈頌（幷序○序爲南嶽齊己撰） 五十一', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["成佛人稀念佛多，念來歲久却成魔。","君今欲得易（《傳燈錄》作「自」）成佛，無念之心（《傳燈錄》作「人」）不較多。"]', '["成佛人稀念佛多，念来歲久却成魔。","君今欲得易（《傳灯錄》作「自」）成佛，無念之心（《傳灯錄》作「人」）不較多。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 五十一 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0fe2480-168e-456c-b597-6d48796835d5', '偈頌（幷序○序爲南嶽齊己撰） 五十二', '偈頌（幷序○序爲南嶽齊己撰） 五十二', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["家具摐摐一老翁，眉間長髮白怱怱。","心休意息從何有，祇爲心頭萬事空。"]', '["家具摐摐一老翁，眉间长髮白怱怱。","心休意息從何有，祇爲心头万事空。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 五十二 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fa73e1e-e534-447e-86b4-c22c678192ca', '偈頌（幷序○序爲南嶽齊己撰） 五十三', '偈頌（幷序○序爲南嶽齊己撰） 五十三', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["二時粥飯隨長短，三界休求也大精。","世間大有多求者，直至無常不稱情。"]', '["二时粥飯隨长短，三界休求也大精。","世间大有多求者，直至無常不稱情。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 五十三 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03e55f70-7b9c-478c-84a4-d304652e9e6a', '偈頌（幷序○序爲南嶽齊己撰） 五十四', '偈頌（幷序○序爲南嶽齊己撰） 五十四', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["未了及（《祖堂集》卷八作「之」）時親遍禮，不須（《祖堂集》作「應」）端坐守清貧。","直似羅睺羅（《祖堂集》作「行」）密行，爭（《祖堂集》作「豈」）如迦葉不聞聞。"]', '["未了及（《祖堂集》卷八作「之」）时親遍禮，不須（《祖堂集》作「應」）端坐守清貧。","直似羅睺羅（《祖堂集》作「行」）密行，爭（《祖堂集》作「豈」）如迦葉不闻闻。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 五十四 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89a17ab7-c57e-4faa-9e99-df9969a75d43', '偈頌（幷序○序爲南嶽齊己撰） 五十五', '偈頌（幷序○序爲南嶽齊己撰） 五十五', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["若教求道似求名，世上無人道不成。","心靜道場何曾到，世間塵路等閑行。"]', '["若教求道似求名，世上無人道不成。","心静道場何曾到，世间塵路等闲行。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 五十五 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a0cfdb7-869a-4960-89da-f36e12c25df2', '偈頌（幷序○序爲南嶽齊己撰） 五十六', '偈頌（幷序○序爲南嶽齊己撰） 五十六', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["杉松直拔映峰巒，一色長青道者看。","四氣盛衰無變異，豈同凡木有多般。"]', '["杉松直拔映峰巒，一色长青道者看。","四氣盛衰無变異，豈同凡木有多般。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 五十六 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d912d56-65ef-4899-af5c-dffec044a28d', '偈頌（幷序○序爲南嶽齊己撰） 五十七', '偈頌（幷序○序爲南嶽齊己撰） 五十七', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["就中慈母感兒情，失便哀啼處處驚。","門市人多非是母，雖然觀矚淚還盈。","母來尋見兒還見，當下回顏不作聲。"]', '["就中慈母感兒情，失便哀啼处处驚。","门市人多非是母，雖然观矚泪還盈。","母来尋见兒還见，當下回顏不作声。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 五十七 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('334681ef-1c97-4e3d-a46e-e4bc7b4413ca', '偈頌（幷序○序爲南嶽齊己撰） 五十八', '偈頌（幷序○序爲南嶽齊己撰） 五十八', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["眉間豪相燄光身，事見爭如理見親。","事有只因於理有，理慈（《景德傳燈錄》卷二九作「權」）方便化天人。","一朝大悟俱消却，方得名爲無事人。","。"]', '["眉间豪相燄光身，事见爭如理见親。","事有只因於理有，理慈（《景德傳灯錄》卷二九作「權」）方便化天人。","一朝大悟俱消却，方得名爲無事人。","。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 五十八 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e4f84ab-9d38-4a25-b018-9e13a6c000ac', '偈頌（幷序○序爲南嶽齊己撰） 五十九', '偈頌（幷序○序爲南嶽齊己撰） 五十九', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["沙門莫苦遠祇桓，身四威儀且自觀。","蓬若出麻終不直，僧離清衆太無端。","從前上古諸先德，盡向叢林裏獲安。"]', '["沙门莫苦远祇桓，身四威儀且自观。","蓬若出麻終不直，僧離清衆太無端。","從前上古諸先德，尽向叢林裏獲安。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 五十九 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a710f0d-6144-49c7-89d6-f04db355383c', '偈頌（幷序○序爲南嶽齊己撰） 六十', '偈頌（幷序○序爲南嶽齊己撰） 六十', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["人天須假像行持，無像無形世豈知？","空生體得巖中坐，華雨由來責見遲。","三乘欲學如斯事，直似空生方始知。"]', '["人天須假像行持，無像無形世豈知？","空生體得巖中坐，华雨由来責见遲。","三乘欲学如斯事，直似空生方始知。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 六十 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23da6c8a-24d5-4462-b62a-2ac1a4b9e05f', '偈頌（幷序○序爲南嶽齊己撰） 六十一', '偈頌（幷序○序爲南嶽齊己撰） 六十一', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["一切名山到因脚，辛苦年深與襪著。","如今年老不能行，手裏把箇破木杓。","破木杓，俵與衆生甘露藥。","衆生喫了盡惺惺，一切昏迷皆失却。"]', '["一切名山到因脚，辛苦年深與襪著。","如今年老不能行，手裏把箇破木杓。","破木杓，俵與衆生甘露藥。","衆生喫了尽惺惺，一切昏迷皆失却。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 六十一 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7ecb079-ad48-4ae5-ab0c-603e9b975cfa', '偈頌（幷序○序爲南嶽齊己撰） 六十二', '偈頌（幷序○序爲南嶽齊己撰） 六十二', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["無端遣問墨池邊，染得身衣黑似煙。","却去上流清處洗，身心用盡亦如然。","令教脫却重披素，不免依前著淨緣。","染淨二途俱不了，到頭須得自心玄。"]', '["無端遣问墨池邊，染得身衣黑似煙。","却去上流清处洗，身心用尽亦如然。","令教脫却重披素，不免依前著淨緣。","染淨二途俱不了，到头須得自心玄。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 六十二 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c748bb34-0f35-4b27-9466-76c68458168d', '偈頌（幷序○序爲南嶽齊己撰） 六十三', '偈頌（幷序○序爲南嶽齊己撰） 六十三', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["擬住城隍守不非，見雲生處又思歸。","三間茅舍喜猶在，九帶青蘿尚遶圍。","松柏近栽方始盛，槿花秋首未嘗萎。"]', '["擬住城隍守不非，见云生处又思归。","三间茅舍喜猶在，九带青蘿尚遶圍。","松柏近栽方始盛，槿花秋首未嘗萎。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 六十三 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1fd8619-2014-4787-8bb6-be5e1246907c', '偈頌（幷序○序爲南嶽齊己撰） 六十四', '偈頌（幷序○序爲南嶽齊己撰） 六十四', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["自從知如覺無明，一衲隨緣祇麽行。","被人駡辱無心諍，見說無爲上擬爭。","祇合守愚居暗室，又緣緇素要分明。","爲報往來參學者，得師無意始無生。"]', '["自從知如覺無明，一衲隨緣祇麽行。","被人駡辱無心諍，见说無爲上擬爭。","祇合守愚居暗室，又緣緇素要分明。","爲報往来參学者，得師無意始無生。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 六十四 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a1162fc-6be4-48cc-ae60-dcda3a64f19c', '偈頌（幷序○序爲南嶽齊己撰） 六十五', '偈頌（幷序○序爲南嶽齊己撰） 六十五', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["微微細雨下多時，百卉抽枝長不知。","正化叵興民自贍，叵興民贍亦如斯。","天觀萬物如芻狗，有覆無心更望伊。","不因無事在林在，爭覺王侯有此資。"]', '["微微細雨下多时，百卉抽枝长不知。","正化叵兴民自贍，叵兴民贍亦如斯。","天观万物如芻狗，有覆無心更望伊。","不因無事在林在，爭覺王侯有此資。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 六十五 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('083a761a-46af-4bd1-acdf-314315ecc088', '偈頌（幷序○序爲南嶽齊己撰） 六十六', '偈頌（幷序○序爲南嶽齊己撰） 六十六', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["備米柴茶是事殷，茅茨蓬戶不驚人。","晨朝有粥齋時飯，資我如常任運身。","冬至息心隨分過，春來量力事須懃。","支持若得今生度，來世還如無事人。","。"]', '["備米柴茶是事殷，茅茨蓬戶不驚人。","晨朝有粥斋时飯，資我如常任運身。","冬至息心隨分過，春来量力事須懃。","支持若得今生度，来世還如無事人。","。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 六十六 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fdb0e76-cded-4456-837d-3eeab1328277', '偈頌（幷序○序爲南嶽齊己撰） 六十七', '偈頌（幷序○序爲南嶽齊己撰） 六十七', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["學道如鑽火，逢煙且莫休。","直待金星現，歸家始到頭。"]', '["学道如鑽火，逢煙且莫休。","直待金星現，归家始到头。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 六十七 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5bb3046-4d16-42ce-aba7-5e1bdfea549d', '偈頌（幷序○序爲南嶽齊己撰） 六十八', '偈頌（幷序○序爲南嶽齊己撰） 六十八', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["閻浮有大寶，見少得人稀。","若人將獻我，成佛一餉時。"]', '["閻浮有大寶，见少得人稀。","若人將獻我，成佛一餉时。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 六十八 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55002bb5-1ac5-45a7-98bf-7139cebaea8b', '偈頌（幷序○序爲南嶽齊己撰） 六十九', '偈頌（幷序○序爲南嶽齊己撰） 六十九', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["悟則一餉時，能了萬劫疑。","若人萬劫疑，不了一餉時。"]', '["悟則一餉时，能了万劫疑。","若人万劫疑，不了一餉时。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 六十九 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c58b6633-f5ef-45c9-844a-4761ee904275', '偈頌（幷序○序爲南嶽齊己撰） 七十', '偈頌（幷序○序爲南嶽齊己撰） 七十', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["不了萬劫疑，古德豈論之。","爲報參玄士，須懷悔底時。"]', '["不了万劫疑，古德豈論之。","爲報參玄士，須懷悔底时。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 七十 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3244febc-c086-4b0a-9bf7-1c21946352e0', '偈頌（幷序○序爲南嶽齊己撰） 七十一', '偈頌（幷序○序爲南嶽齊己撰） 七十一', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["尋牛須訪迹，學道訪無心。","迹在牛還在，無心道易尋。"]', '["尋牛須訪迹，学道訪無心。","迹在牛還在，無心道易尋。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 七十一 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f0a38a7-f9c0-49d8-8e0a-d5c1e2ec3f18', '偈頌（幷序○序爲南嶽齊己撰） 七十二', '偈頌（幷序○序爲南嶽齊己撰） 七十二', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["唯念門前樹，能容鳥泊栖（《景德傳燈錄》卷二九作「飛」）。","來者無心喚，騰身不慕歸。","若人心似樹，與道不相違。"]', '["唯念门前樹，能容鸟泊栖（《景德傳灯錄》卷二九作「飞」）。","来者無心喚，腾身不慕归。","若人心似樹，與道不相違。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 七十二 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7391f696-404c-412e-b01f-49fb84f547d9', '偈頌（幷序○序爲南嶽齊己撰） 七十三', '偈頌（幷序○序爲南嶽齊己撰） 七十三', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["夜寒宜向火，護衆到天明。","日出身溫暖，心惺思更惺。"]', '["夜寒宜向火，護衆到天明。","日出身溫暖，心惺思更惺。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 七十三 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbaa678d-2a57-408f-a6d1-77920fdb3439', '偈頌（幷序○序爲南嶽齊己撰） 七十四', '偈頌（幷序○序爲南嶽齊己撰） 七十四', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["豈是無干意，多求失道情。","我見多求者，年高事不成。"]', '["豈是無干意，多求失道情。","我见多求者，年高事不成。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 七十四 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f133a646-7a7d-4eda-89f1-6571eeffb958', '偈頌（幷序○序爲南嶽齊己撰） 七十五', '偈頌（幷序○序爲南嶽齊己撰） 七十五', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["老似臨江樹，風搖枝必危。","岸崩隨水去，入海勿人追。"]', '["老似臨江樹，风搖枝必危。","岸崩隨水去，入海勿人追。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 七十五 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6651441-1841-498e-8837-c70ed78b0f2f', '偈頌（幷序○序爲南嶽齊己撰） 七十六', '偈頌（幷序○序爲南嶽齊己撰） 七十六', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["道死如枯木，波濤豈更違。","時人雖不顧，能歇海盲龜。"]', '["道死如枯木，波濤豈更違。","时人雖不顧，能歇海盲龟。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 七十六 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd55c8e7-14f8-4022-a73d-d4a4054505a6', '偈頌（幷序○序爲南嶽齊己撰） 七十七', '偈頌（幷序○序爲南嶽齊己撰） 七十七', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["新創三間舍，多泥慮有風。","門前無貴客，拙意懶迎逢。"]', '["新創三间舍，多泥慮有风。","门前無貴客，拙意懶迎逢。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 七十七 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bfa9fb5-56ff-470e-bcb7-c925945276fe', '偈頌（幷序○序爲南嶽齊己撰） 七十八', '偈頌（幷序○序爲南嶽齊己撰） 七十八', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["飯喫隨時食，心穿獨自縫。","若人來問我，招手報伊聾。"]', '["飯喫隨时食，心穿独自縫。","若人来问我，招手報伊聾。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 七十八 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6eb48d9f-c376-4e2e-9d72-0ea19acd2731', '偈頌（幷序○序爲南嶽齊己撰） 七十九', '偈頌（幷序○序爲南嶽齊己撰） 七十九', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["十月夜明深，山寒冷徹心。","棄緣求大道，一衲更無衾。"]', '["十月夜明深，山寒冷徹心。","棄緣求大道，一衲更無衾。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 七十九 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4bd3891-0eb9-470f-b467-4cdcb7fce41e', '偈頌（幷序○序爲南嶽齊己撰） 八十', '偈頌（幷序○序爲南嶽齊己撰） 八十', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["體得如來意，知無寒暑侵。","悟無成佛者，一一盡無心。"]', '["體得如来意，知無寒暑侵。","悟無成佛者，一一尽無心。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 八十 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99ea3bb5-446e-4f73-b053-bb7fc2326e90', '偈頌（幷序○序爲南嶽齊己撰） 八十一', '偈頌（幷序○序爲南嶽齊己撰） 八十一', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["破布裹聞身，無言可示人。","居山山得樂，住郭郭還欣。"]', '["破布裹闻身，無言可示人。","居山山得乐，住郭郭還欣。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 八十一 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3c6aa26-7557-4f68-959a-da6e0c04371f', '偈頌（幷序○序爲南嶽齊己撰） 八十二', '偈頌（幷序○序爲南嶽齊己撰） 八十二', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["體得無生意，朝朝近古人。","若也更不會，雖樂苦臨身。","。"]', '["體得無生意，朝朝近古人。","若也更不會，雖乐苦臨身。","。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 八十二 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f20c6c0-aa7c-4c6c-ad56-192840db3306', '偈頌（幷序○序爲南嶽齊己撰） 八十三', '偈頌（幷序○序爲南嶽齊己撰） 八十三', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["唯念深秋扇，臨冬轉就閑。","銀裝將物裹，篾作插簷間。"]', '["唯念深秋扇，臨冬轉就闲。","銀裝將物裹，篾作插簷间。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 八十三 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c58149cd-4d62-41d4-9302-b9c397c28949', '偈頌（幷序○序爲南嶽齊己撰） 八十四', '偈頌（幷序○序爲南嶽齊己撰） 八十四', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["祇爲因無用，方能伴住山。","不因無用後，伴我住應難。"]', '["祇爲因無用，方能伴住山。","不因無用後，伴我住應难。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 八十四 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd1df6e4-bf02-4055-b9eb-22d362a20fb8', '偈頌（幷序○序爲南嶽齊己撰） 八十五', '偈頌（幷序○序爲南嶽齊己撰） 八十五', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["柱杖行低道，逢溪澡潄多。","平田偏樂坐，人命可經過。"]', '["柱杖行低道，逢溪澡潄多。","平田偏乐坐，人命可經過。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 八十五 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b967cd9d-8df4-4c5e-bb34-e2e4b2345029', '偈頌（幷序○序爲南嶽齊己撰） 八十六', '偈頌（幷序○序爲南嶽齊己撰） 八十六', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["守道身心息，資緣豈撓他。","除非僧次外，歸寺補袈裟。"]', '["守道身心息，資緣豈撓他。","除非僧次外，归寺補袈裟。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 八十六 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49684fb9-6d66-4514-8779-e28dc0febe9e', '偈頌（幷序○序爲南嶽齊己撰） 八十七', '偈頌（幷序○序爲南嶽齊己撰） 八十七', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["覺倦燒爐火，安鐺便煮茶。","就中無一事，唯有野僧家。"]', '["覺倦燒爐火，安鐺便煮茶。","就中無一事，唯有野僧家。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 八十七 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d58a8163-6d40-4af3-9c1c-c149e5fb3fe0', '偈頌（幷序○序爲南嶽齊己撰） 八十八', '偈頌（幷序○序爲南嶽齊己撰） 八十八', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["一念心清淨，蓮華處處開。","一華一淨土，一土一如來。"]', '["一念心清淨，蓮华处处开。","一华一淨土，一土一如来。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 八十八 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b209a59-cc22-4957-a96e-8072738e02aa', '偈頌（幷序○序爲南嶽齊己撰） 八十九', '偈頌（幷序○序爲南嶽齊己撰） 八十九', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["頭戴朝生菌，身披補破衣。","見貧人可可，同道乃方知。"]', '["头戴朝生菌，身披補破衣。","见貧人可可，同道乃方知。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 八十九 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93fc8780-1256-4046-97ca-49bf7938ca31', '偈頌（幷序○序爲南嶽齊己撰） 九十', '偈頌（幷序○序爲南嶽齊己撰） 九十', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["龍牙山裏龍，形非世間色。","世上畫龍人，巧巧描不得。","唯有識龍人，一見便心息。"]', '["龙牙山裏龙，形非世间色。","世上畫龙人，巧巧描不得。","唯有識龙人，一见便心息。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 九十 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('840bd1cd-978f-4378-b6b9-88149597b23b', '偈頌（幷序○序爲南嶽齊己撰） 九十一', '偈頌（幷序○序爲南嶽齊己撰） 九十一', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["西來意未明，徒學諸知見。","不識本真性，契道即懸遠。"]', '["西来意未明，徒学諸知见。","不識本真性，契道即懸远。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 九十一 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa8c2f89-7891-42a1-89e7-5b1ed2d95cce', '偈頌（幷序○序爲南嶽齊己撰） 九十二', '偈頌（幷序○序爲南嶽齊己撰） 九十二', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["若能明實相，豈用陳知見。","一念了自心，開佛諸知見。"]', '["若能明實相，豈用陳知见。","一念了自心，开佛諸知见。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 九十二 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4eb24d7-dc8c-4f78-a379-8f55d37fd133', '偈頌（幷序○序爲南嶽齊己撰） 九十三', '偈頌（幷序○序爲南嶽齊己撰） 九十三', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["寄語諸仁者，復以何爲懷。","達道見自性，自性即如來。"]', '["寄語諸仁者，复以何爲懷。","達道见自性，自性即如来。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 九十三 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16d8217d-d932-4259-8f6e-0be5a12a273e', '偈頌（幷序○序爲南嶽齊己撰） 九十四', '偈頌（幷序○序爲南嶽齊己撰） 九十四', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["天真元具足，修證轉差迴。","棄本却逐末，祇守一場獃。","（以上九十五首，均見《卍續藏經》本宋釋子昇、如祐編《禪門諸祖師偈頌》卷上之上。","）。"]', '["天真元具足，修證轉差迴。","棄本却逐末，祇守一場獃。","（以上九十五首，均见《卍續藏經》本宋釋子昇、如祐編《禪门諸祖師偈頌》卷上之上。","）。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 九十四 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a6e9b99-6953-4fe5-84c2-ca7d3666e76b', '偈頌（幷序○序爲南嶽齊己撰） 九十五', '偈頌（幷序○序爲南嶽齊己撰） 九十五', '5366ac2c-2fca-41e1-985e-4d07b44f2fbb', '唐', '["君若隨緣得似風，吹沙走石不勞功。","但於事上通無事，見色聞聲不用聾。","（《禪林僧寶傳》卷九《龍牙居遁禪師》）。"]', '["君若隨緣得似风，吹沙走石不勞功。","但於事上通無事，见色闻声不用聾。","（《禪林僧寶傳》卷九《龙牙居遁禪師》）。"]', '诗', 'shi', '', NULL, '偈頌（幷序○序爲南嶽齊己撰） 九十五 居遁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abc077d9-c7a1-43e1-81d1-508b2876fe2d', '贈天昕禪老', '贈天昕禪老', '413ffeeb-5b46-4910-aa64-37a334739302', '唐', '["翰苑營嘉致，到來山意深。","會茶多野客，啼竹半沙禽。","雪溜懸危石，棋燈射遠林。","言詩素非苦，虛答侍臣心。","（《詩淵》第一冊第三八四頁）。"]', '["翰苑營嘉致，到来山意深。","會茶多野客，啼竹半沙禽。","雪溜懸危石，棋灯射远林。","言诗素非苦，虛答侍臣心。","（《诗淵》第一冊第三八四頁）。"]', '诗', 'shi', '', NULL, '贈天昕禪老 虛中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d01c9b5-603e-47c1-8abf-e03fff5b6732', '送鴈', '送鴈', '413ffeeb-5b46-4910-aa64-37a334739302', '唐', '["雲夢[千]（午）（從《詩學指南》本改）行去，瀟湘一夜空。"]', '["云梦[千]（午）（從《诗学指南》本改）行去，瀟湘一夜空。"]', '诗', 'shi', '', NULL, '送鴈 虛中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ace8923-5a40-4da6-a107-f8a1bcd3452c', '聽琴', '听琴', '413ffeeb-5b46-4910-aa64-37a334739302', '唐', '["古調俗不樂，正[聲]（身）（從《詩學指南》本改）君自知。"]', '["古調俗不乐，正[声]（身）（從《诗学指南》本改）君自知。"]', '诗', 'shi', '', NULL, '聽琴 虛中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84d0d19e-3137-48a5-acb2-62c78ee95096', '喜友人及第', '喜友人及第', '413ffeeb-5b46-4910-aa64-37a334739302', '唐', '["碧霄章句絕離手，紫府神仙盡點頭。","（均見《吟窗雜錄》卷十四正字王玄《詩中旨格》）。"]', '["碧霄章句絕離手，紫府神仙尽点头。","（均见《吟窗杂錄》卷十四正字王玄《诗中旨格》）。"]', '诗', 'shi', '', NULL, '喜友人及第 虛中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35e4d3f0-7b02-47a6-a816-124232715aa8', '還丹口訣', '還丹口訣', '39836aad-8688-41ed-9e14-295a9e6ce1a1', '唐', '["求仙覓黃芽，須得真鉛花。","並是自成者，乃可作所砂。","重飛服一粒，騰空入碧霞。","周遊天地外，處處是仙家。","（《大還丹照鑑》。","原署「玄黃子」）。"]', '["求仙覓黄芽，須得真鉛花。","並是自成者，乃可作所砂。","重飞服一粒，腾空入碧霞。","周游天地外，处处是仙家。","（《大還丹照鑑》。","原署「玄黄子」）。"]', '诗', 'shi', '', NULL, '還丹口訣 戴偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb75a5f5-9120-4508-a36e-c00d71b4dbfc', '頌', '頌', '61ec0f7d-7be4-4953-9d9b-b9582e178340', '唐', '["南臺靜坐一鑪香，亘（一作「終」）日凝然萬事忘（一作「慮亡」）。","不是息心除忘想，都緣無事可思量。","（見《景德傳燈錄》卷二十四，注一作者爲《五燈會元》卷八之異文。","）。"]', '["南台静坐一鑪香，亘（一作「終」）日凝然万事忘（一作「慮亡」）。","不是息心除忘想，都緣無事可思量。","（见《景德傳灯錄》卷二十四，注一作者爲《五灯會元》卷八之異文。","）。"]', '诗', 'shi', '', NULL, '頌 守安 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('609e47f6-22b0-4261-8955-12da2cb20e07', '讚鏡燈頌', '讚镜灯頌', 'de420f21-8d34-4007-9385-55909a5041a9', '唐', '["偉哉真智士，能開方便津。","一燈明一體，十鏡現十身。","身身相暵涉，燈燈作{牙丿=丶}因。","層層身土廣，重重理事渕。","儼覩微塵佛，等逢毗目仙。","海印從茲顯，帝綱義由詮。","一塵說法界，一切塵亦然。","五藴十八界，寂用體俱全。","圓光含鏡像，一異不可宣。","達斯無㝵境，無那法報圓。"]', '["偉哉真智士，能开方便津。","一灯明一體，十镜現十身。","身身相暵涉，灯灯作{牙丿=丶}因。","層層身土廣，重重理事渕。","儼覩微塵佛，等逢毗目仙。","海印從茲显，帝綱義由詮。","一塵说法界，一切塵亦然。","五藴十八界，寂用體俱全。","圓光含镜像，一異不可宣。","達斯無㝵境，無那法報圓。"]', '诗', 'shi', '', NULL, '讚鏡燈頌 惟勁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e347820e-ab17-47fb-9461-27ad49d74ce7', '述象骨偈', '述象骨偈', 'de420f21-8d34-4007-9385-55909a5041a9', '唐', '["象骨雄雄舉世尊，統盡乾坤是一門。","詞鋒未接承當好，莫待言教句裏傳。","擬議終成山海隔，擗面渾機直下全。","更欲會他泥牛吼，審細須聽木馬嘶（末字疑誤）。"]', '["象骨雄雄舉世尊，統尽乾坤是一门。","词鋒未接承當好，莫待言教句裏傳。","擬議終成山海隔，擗面渾機直下全。","更欲會他泥牛吼，審細須听木马嘶（末字疑誤）。"]', '诗', 'shi', '', NULL, '述象骨偈 惟勁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9823c41-3ca4-4aef-a0f3-43230d447964', '學道頌', '学道頌', 'de420f21-8d34-4007-9385-55909a5041a9', '唐', '["學道如攢火，逢煙且莫休。","直得金星現，歸家始到頭。","（以上三首均見《祖堂集》卷十一）。"]', '["学道如攢火，逢煙且莫休。","直得金星現，归家始到头。","（以上三首均见《祖堂集》卷十一）。"]', '诗', 'shi', '', NULL, '學道頌 惟勁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('126322a2-0d8f-483a-8622-739f4fbe706e', '覺地頌', '覺地頌', 'de420f21-8d34-4007-9385-55909a5041a9', '唐', '["略明覺地名同異，起復初終互換生。","性海首建增名號，妙覺還依性覺明。","體覺俱含於明妙，明覺妙覺並雙行。","妙覺覺妙元明體，全成無漏一真精。","明覺覺明明所了，或因了相失元明。","明妙二覺宗體決，體覺性覺二同明。","湛覺圓圓無增減，此中無佛與衆生。","不覺始終非了了，不聞迷悟豈惺惺。","是稱心地如來藏，亦無覺照及無生。","非生非滅真如海，湛然常住名無名。","太虛未覺生霞點，豈聞微塵有漏聲。","空漚匪離於覺海，動寂元是一真明。","覺明體爾含靈燄，覺明逐燄致虧盈。","差之不返名無覺，會之復本始覺生。","本覺由因始覺生，正覺還依合覺明。","由地二種成差互，遂令渾作賴邪名。","具含染淨雙歧路，覺明含處異途萌。","性起無生不動智，不離覺體本圓成。","性起轉覺翻生所，遂令有漏墮迷盲。","無明因愛相滋潤，名色根本相次生。","七識轉處蒙圓鏡，五六生時蔽覺明。","觸受有取相依起，生老病死繼續行。","業識茫茫沒苦海，徇流浩浩逐飄零。","大聖慈悲興救濟，一聲用處出三聲。","智身由從法身起，行身還約智身生。","智行二身融無二，還歸一體本來平。","萬有齊含真海印，一心普現總圓明。","湛光燄燄何依止，空性蕩蕩無所停。","處處示生無生相，處處示滅無滅形。","珠鏡頓印無來往，浮雲聚散勿常程。","出沒任真同水月，應緣如響化羣情。","衆生性地元無染，只緣浮妄翳真精。","不了五陰如空聚，豈知四大若乾城。","我慢癡山高屹屹，無明欲海杳溟溟。","每逐旃陁憍誑友，常隨猛獸作悲鳴。","自性轉識翻爲幻，自心幻境自心驚。","了此幻性同陽燄，空花識浪復圓成。","太虛忽覺浮雲散，始覺虛空本自清，今古湛然常皎瑩，不得古今凡聖名。","（見《景德傳燈錄》卷二十九）。"]', '["略明覺地名同異，起复初終互換生。","性海首建增名號，妙覺還依性覺明。","體覺俱含於明妙，明覺妙覺並雙行。","妙覺覺妙元明體，全成無漏一真精。","明覺覺明明所了，或因了相失元明。","明妙二覺宗體決，體覺性覺二同明。","湛覺圓圓無增減，此中無佛與衆生。","不覺始終非了了，不闻迷悟豈惺惺。","是稱心地如来藏，亦無覺照及無生。","非生非滅真如海，湛然常住名無名。","太虛未覺生霞点，豈闻微塵有漏声。","空漚匪離於覺海，动寂元是一真明。","覺明體爾含靈燄，覺明逐燄致虧盈。","差之不返名無覺，會之复本始覺生。","本覺由因始覺生，正覺還依合覺明。","由地二種成差互，遂令渾作賴邪名。","具含染淨雙歧路，覺明含处異途萌。","性起無生不动智，不離覺體本圓成。","性起轉覺翻生所，遂令有漏墮迷盲。","無明因愛相滋潤，名色根本相次生。","七識轉处蒙圓镜，五六生时蔽覺明。","觸受有取相依起，生老病死繼續行。","業識茫茫沒苦海，徇流浩浩逐飄零。","大聖慈悲兴救濟，一声用处出三声。","智身由從法身起，行身還約智身生。","智行二身融無二，還归一體本来平。","万有齊含真海印，一心普現總圓明。","湛光燄燄何依止，空性蕩蕩無所停。","处处示生無生相，处处示滅無滅形。","珠镜頓印無来往，浮云聚散勿常程。","出沒任真同水月，應緣如响化羣情。","衆生性地元無染，只緣浮妄翳真精。","不了五陰如空聚，豈知四大若乾城。","我慢癡山高屹屹，無明欲海杳溟溟。","每逐旃陁憍誑友，常隨猛獸作悲鳴。","自性轉識翻爲幻，自心幻境自心驚。","了此幻性同陽燄，空花識浪复圓成。","太虛忽覺浮云散，始覺虛空本自清，今古湛然常皎瑩，不得古今凡聖名。","（见《景德傳灯錄》卷二十九）。"]', '诗', 'shi', '', NULL, '覺地頌 惟勁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b74fc70-6dd0-4d45-9716-2624ced10d70', '田家', '田家', '4948b49a-edd7-47ad-a807-0b3c50b2af26', '唐', '["高原耕種罷，牽犢負薪歸。","深夜一爐火，渾家身上衣。","（見《竹莊詩話》卷二十引《禁臠》）（按：昭禹，《竹莊詩話》誤作「禹昭」。","）。"]', '["高原耕種罷，牽犢負薪归。","深夜一爐火，渾家身上衣。","（见《竹莊诗話》卷二十引《禁臠》）（按：昭禹，《竹莊诗話》誤作「禹昭」。","）。"]', '诗', 'shi', '', NULL, '田家 劉昭禹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12150916-d0ab-4cdf-94b0-b90090324297', '謝秦王', '謝秦王', '7a8c5552-605a-4888-8eb7-a8b483d85551', '唐', '["三千里外拋漁艇，二十人前折桂枝。","（見《增修詩話總龜》卷三六引《青瑣集》）（〖1〗《青瑣集》云：「王仲舉，營道人，母嘗夢挾仲舉入月。","仲舉修進業，長興〖化〗二年赴舉，謁秦王登第，後有詩謝秦王）（曰〖略〗。","太平興國中，仲舉有子曰嗣全，亦中進士第，乃挾兩子入月之祥。","」以《五代史補》卷二載何仲舉事跡參證，知「王仲舉」爲「何仲舉」之誤。","二書所載及第年有異，未詳孰是。","）。"]', '["三千里外拋漁艇，二十人前折桂枝。","（见《增修诗話總龟》卷三六引《青瑣集》）（〖1〗《青瑣集》云：「王仲舉，營道人，母嘗梦挾仲舉入月。","仲舉修進業，长兴〖化〗二年赴舉，謁秦王登第，後有诗謝秦王）（曰〖略〗。","太平兴国中，仲舉有子曰嗣全，亦中進士第，乃挾兩子入月之祥。","」以《五代史補》卷二載何仲舉事跡參證，知「王仲舉」爲「何仲舉」之誤。","二书所載及第年有異，未詳孰是。","）。"]', '诗', 'shi', '', NULL, '謝秦王 何仲舉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a915a9a-f8e2-4534-9543-56468a0c2b03', '遊零陵見父題壁感而成詩（題擬）', '游零陵见父題壁感而成诗（題擬）', '9cce097a-9c37-4b99-9857-f4258047f21d', '唐', '["下馬連聲叩竹門，主人何事感遺恩。","迴頭泣向兒童道，重見甘棠舊子孫。","（見《增修詩話總龜前集》卷二十五引《青瑣後集》）（〖1〗《青瑣後集》：「廖齊父爽直嘗爲永州刺史。","齊後遊零陵，於民間見父題壁，感而成詩曰〖略〗。","」清鄧顯鶴輯《沅湘耆舊集》卷八定此詩作者爲廖偃，其說謂「偃父圖曾爲永州刺史，後偃遊零陵，於民間見父題壁，感而成詩。","」偃事跡詳陸氏《南唐書》卷八、《十國春秋》卷七四。","祖爽，父匡圖。","匡圖，宋人避諱或省「匡」字，《十國春秋》卷七三載其仕歷，未任永州刺史。","其父爽事跡附匡圖傳，初仕南漢，後舉族奔楚，馬氏表爽爲永州刺史。","此詩非廖偃作。","爽子今知有二人，即匡圖、匡齊。","因知此詩爲匡齊作。","《青瑣後集》所謂「廖齊父爽直嘗爲永州刺史」，「齊」字上因避諱略去「匡」字，與匡圖同例。","「爽直」之「直」字爲衍文。","）。"]', '["下马連声叩竹门，主人何事感遺恩。","迴头泣向兒童道，重见甘棠旧子孫。","（见《增修诗話總龟前集》卷二十五引《青瑣後集》）（〖1〗《青瑣後集》：「廖齊父爽直嘗爲永州刺史。","齊後游零陵，於民间见父題壁，感而成诗曰〖略〗。","」清鄧显鹤輯《沅湘耆旧集》卷八定此诗作者爲廖偃，其说謂「偃父圖曾爲永州刺史，後偃游零陵，於民间见父題壁，感而成诗。","」偃事跡詳陸氏《南唐书》卷八、《十国春秋》卷七四。","祖爽，父匡圖。","匡圖，宋人避諱或省「匡」字，《十国春秋》卷七三載其仕歷，未任永州刺史。","其父爽事跡附匡圖傳，初仕南漢，後舉族奔楚，马氏表爽爲永州刺史。","此诗非廖偃作。","爽子今知有二人，即匡圖、匡齊。","因知此诗爲匡齊作。","《青瑣後集》所謂「廖齊父爽直嘗爲永州刺史」，「齊」字上因避諱略去「匡」字，與匡圖同例。","「爽直」之「直」字爲衍文。","）。"]', '诗', 'shi', '', NULL, '遊零陵見父題壁感而成詩（題擬） 廖匡齊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c1a3719-d36f-4957-817d-910983d913e2', '待月', '待月', '702cbcfc-11e7-4fd8-9ce8-cebd8dccc088', '唐', '["一片月生海，幾家人上樓。","（見《吟窗雜錄》卷十四正字王玄《詩中旨格》）。"]', '["一片月生海，幾家人上楼。","（见《吟窗杂錄》卷十四正字王玄《诗中旨格》）。"]', '诗', 'shi', '', NULL, '待月 廖凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4aa77cc2-7e64-4f71-b4ef-77e36c1ec102', '雲居寺（題擬）', '云居寺（題擬）', '702cbcfc-11e7-4fd8-9ce8-cebd8dccc088', '唐', '["遠水微茫轉，前山次第卑。","（見宋陳田夫《南嶽總勝集》卷中）。"]', '["远水微茫轉，前山次第卑。","（见宋陳田夫《南嶽總勝集》卷中）。"]', '诗', 'shi', '', NULL, '雲居寺（題擬） 廖凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2a3cd65-46d7-42e8-944c-779b5f3fa05d', '句 一', '句 一', '702cbcfc-11e7-4fd8-9ce8-cebd8dccc088', '唐', '["直待素秋霜色裏。","（宋史鑄《百菊集譜》卷六集句引）。"]', '["直待素秋霜色裏。","（宋史鑄《百菊集譜》卷六集句引）。"]', '诗', 'shi', '', NULL, '句 一 廖凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8470bc42-a153-48e5-9290-e1b64f3c6602', '句 二', '句 二', '702cbcfc-11e7-4fd8-9ce8-cebd8dccc088', '唐', '["千山景象通。","（《江湖小集》卷四紹嵩《江浙紀行集句詩》引）。"]', '["千山景象通。","（《江湖小集》卷四紹嵩《江浙紀行集句诗》引）。"]', '诗', 'shi', '', NULL, '句 二 廖凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5f7da36-432f-4a16-b445-4a81d40d7351', '句 三', '句 三', '702cbcfc-11e7-4fd8-9ce8-cebd8dccc088', '唐', '["春色遍空明。","（同前）。"]', '["春色遍空明。","（同前）。"]', '诗', 'shi', '', NULL, '句 三 廖凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb09632a-a748-4fb8-b1e4-b78a17dc68e1', '望早日', '望早日', 'fcbefced-44bb-46e8-ba08-8730df7b9398', '唐', '["纔分天地色，便禁虎狼心。","（見《吟窗雜錄》卷十四正字王玄《詩中旨格》）。"]', '["纔分天地色，便禁虎狼心。","（见《吟窗杂錄》卷十四正字王玄《诗中旨格》）。"]', '诗', 'shi', '', NULL, '望早日 何景山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93beb1ad-0604-4ba9-92e1-c4b7f8cc5aa6', '', '', 'd8ab7258-b7b2-4b43-bd52-946998d1a5ea', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 李觀象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf23a2c5-4041-4acd-a341-abeb942446bd', '紙帳詩', '紙帳诗', 'd8ab7258-b7b2-4b43-bd52-946998d1a5ea', '唐', '["清懸四面剡溪霜，高臥梅花月半牀。","花甕有天春不老，瑤臺無夜月生香。","覺來虛白神光發，睡去清閑好夢長。","一枕總無塵土氣，何妨留我白雲鄉。","（《堅瓠甲集》卷一）。"]', '["清懸四面剡溪霜，高臥梅花月半牀。","花甕有天春不老，瑤台無夜月生香。","覺来虛白神光發，睡去清闲好梦长。","一枕總無塵土氣，何妨留我白云乡。","（《堅瓠甲集》卷一）。"]', '诗', 'shi', '', NULL, '紙帳詩 李觀象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c16186c8-d855-4a7d-a2d2-b133304f73b7', '桃源（題擬）', '桃源（題擬）', 'dfd1a25f-acb4-4295-b9e3-eb41e0ba58c2', '唐', '["鎖斷桃源一窟春，避秦日月無歸處。","（見《輿地紀勝》卷六八《常德府》）。"]', '["鎖斷桃源一窟春，避秦日月無归处。","（见《輿地紀勝》卷六八《常德府》）。"]', '诗', 'shi', '', NULL, '桃源（題擬） 徐仲雅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8a9d764-ad55-4300-a8f0-bb4cbdd1f28a', '東華觀偃松（補序）', '东华观偃松（補序）', 'dfd1a25f-acb4-4295-b9e3-eb41e0ba58c2', '唐', '["空（按：此詩已收《全唐詩》卷七六二。","此序爲節文。","）。"]', '["空（按：此诗已收《全唐诗》卷七六二。","此序爲節文。","）。"]', '诗', 'shi', '', NULL, '東華觀偃松（補序） 徐仲雅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('841cb0e3-15dc-4290-bbef-815ce73bb9f5', '孤雁', '孤雁', 'bd4920ce-3ccd-46e3-badb-ab29633fc294', '唐', '["葦岸風吹雨，沙汀月照霜。","還同我兄弟，零落不成行。","（見《能改齋漫錄》卷八。","全詩八句，此爲後四句。","）。"]', '["葦岸风吹雨，沙汀月照霜。","還同我兄弟，零落不成行。","（见《能改斋漫錄》卷八。","全诗八句，此爲後四句。","）。"]', '诗', 'shi', '', NULL, '孤雁 蔣鈞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('454fcc52-8720-4211-a443-d473c588e641', '題花鈿', '題花鈿', 'e310aedb-83b8-4627-a62f-d8eaded5f374', '唐', '["傅粉銷金翦翠霞，黛煙濃處添鉛華。","也知曾伴姮娥笑，將來村裏賣誰家。"]', '["傅粉銷金翦翠霞，黛煙濃处添鉛华。","也知曾伴姮娥笑，將来村裏賣誰家。"]', '诗', 'shi', '', NULL, '題花鈿 盧承丘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29e5b8b5-3606-44f8-9e17-536f61efd63f', '題渡頭船', '題渡头船', 'e310aedb-83b8-4627-a62f-d8eaded5f374', '唐', '["刳木功成濟往還，古溪殘照下前山。","看看向晚人來少，猶自須來覓見錢。","（見《增修詩話總龜前集》卷一引《雅言系述》）。"]', '["刳木功成濟往還，古溪殘照下前山。","看看向晚人来少，猶自須来覓见錢。","（见《增修诗話總龟前集》卷一引《雅言系述》）。"]', '诗', 'shi', '', NULL, '題渡頭船 盧承丘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81220e1f-9f7f-4df7-a59c-8da4f235f5a0', '詠鷺鷥詩', '詠鷺鷥诗', 'a6382313-a6af-48d3-bfda-9f3f9d378d16', '唐', '["滄海獨深處，鱸魚銜得時。","（見《類說》卷二十二《荆湖近事》。","《澠水燕談錄》卷十作「滄浪最深處，鱸魚初得時。","」）。"]', '["滄海独深处，鱸鱼銜得时。","（见《類说》卷二十二《荆湖近事》。","《澠水燕談錄》卷十作「滄浪最深处，鱸鱼初得时。","」）。"]', '诗', 'shi', '', NULL, '詠鷺鷥詩 張仲達 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1517854-01a8-44b4-a338-bd0225dab792', '寄黃損', '寄黄損', 'ed3c6be5-7336-4f5b-8c37-962f95bf6378', '唐', '["莊周指我悟榮生，買得衡山十里青。","却許野禽棲竹徑，不教凡客扣柴扃。","橫琴獨坐泉圍石，倚棹長吟月滿汀。","珍重零陵舊知己，菱花時把照星星。","（周本淳校點本《詩話總龜》卷二八引《雅言系述》。","《南嶽總勝集》卷中「兜率寺」條引「買得衡州十里青」一句，謂廖處士作。","）。"]', '["莊周指我悟榮生，買得衡山十里青。","却許野禽棲竹徑，不教凡客扣柴扃。","橫琴独坐泉圍石，倚棹长吟月满汀。","珍重零陵旧知己，菱花时把照星星。","（周本淳校点本《诗話總龟》卷二八引《雅言系述》。","《南嶽總勝集》卷中「兜率寺」條引「買得衡州十里青」一句，謂廖处士作。","）。"]', '诗', 'shi', '', NULL, '寄黃損 廖匡圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68415385-d8d5-420f-af5b-2c359f2252da', '贈藴上人', '贈藴上人', '611cab53-8b6a-4421-896d-4cec83f6777b', '唐', '["佛法詩名更誰繼，未聞隨分謁侯王。","洗盂秋澗日華動，搗藥夜堂雲氣香。","苔蘚亂青封疊石，杉松濃影過空牆。","若非火岳□□地，那得吾師住久長。","（周本淳校點本《詩話總龜》卷二八引《雅言系述》。","）。"]', '["佛法诗名更誰繼，未闻隨分謁侯王。","洗盂秋澗日华动，捣藥夜堂云氣香。","苔蘚亂青封叠石，杉松濃影過空牆。","若非火岳□□地，那得吾師住久长。","（周本淳校点本《诗話總龟》卷二八引《雅言系述》。","）。"]', '诗', 'shi', '', NULL, '贈藴上人 王正己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b767de3a-0931-4963-a042-816c61a7f693', '贈廖融', '贈廖融', '611cab53-8b6a-4421-896d-4cec83f6777b', '唐', '["湖南雖不就卑官，高臥深雲道自安。","病起坐當秋閣迥，酒醒吟對夜濤寒。","爐中藥熟分僧服，榻上琴閑借我彈。","幸遇清朝有良鑒，退身爭忍似方干。","（同前）。"]', '["湖南雖不就卑官，高臥深云道自安。","病起坐當秋閣迥，酒醒吟对夜濤寒。","爐中藥熟分僧服，榻上琴闲借我彈。","幸遇清朝有良鑒，退身爭忍似方干。","（同前）。"]', '诗', 'shi', '', NULL, '贈廖融 王正己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f192bd75-0b2d-41a1-96c1-942ce062ef70', '句', '句', '611cab53-8b6a-4421-896d-4cec83f6777b', '唐', '["未可輕樗櫟，尤能濟雪霜。","（同前卷二一引《零陵總記》，云爲王正詩，王正當即王正己之誤。","）。"]', '["未可轻樗櫟，尤能濟雪霜。","（同前卷二一引《零陵總記》，云爲王正诗，王正當即王正己之誤。","）。"]', '诗', 'shi', '', NULL, '句 王正己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f41644ff-f21c-4d56-9cf8-7f45c3f2980a', '贈王正己（題擬）', '贈王正己（題擬）', '591f3ab0-45b6-47e0-ab6a-667e7a0d1137', '唐', '["吟高鄙俗流，傲逸訪巢由。","古寺尋僧飯，寒巖衣鹿裘。","園桃山鼠嚙，崖蜜獵人偷。","遂這箇清性，浮生不苟求。","（周本淳校本《詩話總龜》卷二八引《雅言系述》）。"]', '["吟高鄙俗流，傲逸訪巢由。","古寺尋僧飯，寒巖衣鹿裘。","园桃山鼠嚙，崖蜜獵人偷。","遂這箇清性，浮生不苟求。","（周本淳校本《诗話總龟》卷二八引《雅言系述》）。"]', '诗', 'shi', '', NULL, '贈王正己（題擬） 廖融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a24be971-e3aa-4ec5-8b78-33c7ba02467f', '贈狄渙', '贈狄渙', '591f3ab0-45b6-47e0-ab6a-667e7a0d1137', '唐', '["高臥白雲鄉，崖泉對閣涼。","守貧無屬道，多病數求方。","耕犢驚雷斃，寒蕪入圃荒。","如何帝未夢，吟若頂鋪霜。","（同前）（按：王正己、廖衡等人爲五代末至宋初居住於湖南衡山一帶的詩人，今可考知諸人事跡均已入宋，然歷來皆視爲五代作者，故仍予以收錄。","）。"]', '["高臥白云乡，崖泉对閣涼。","守貧無屬道，多病數求方。","耕犢驚雷斃，寒蕪入圃荒。","如何帝未梦，吟若頂鋪霜。","（同前）（按：王正己、廖衡等人爲五代末至宋初居住於湖南衡山一带的诗人，今可考知諸人事跡均已入宋，然歷来皆視爲五代作者，故仍予以收錄。","）。"]', '诗', 'shi', '', NULL, '贈狄渙 廖融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36c75500-0d12-4fb5-95dd-7a9f015bf59d', '遊般若寺上方', '游般若寺上方', 'b2980800-dccb-497c-9b8c-a43b76034bdf', '唐', '["榔粟步溪光，隨雲到上方。","經秋禪客病，積雨石樓荒。","古蘚糜鹿跡，陰崖松檜香。","平生豁所思，吟嘯倚蒼蒼。","（見《吟窗雜錄》卷十三桂林淳大師《詩評》引）（按：此詩署廖處士作，當爲廖匡圖、廖凝、廖融等人中之一人。","未審孰是，姑仍分列。","）。"]', '["榔粟步溪光，隨云到上方。","經秋禪客病，積雨石楼荒。","古蘚糜鹿跡，陰崖松檜香。","平生豁所思，吟嘯倚蒼蒼。","（见《吟窗杂錄》卷十三桂林淳大師《诗評》引）（按：此诗署廖处士作，當爲廖匡圖、廖凝、廖融等人中之一人。","未審孰是，姑仍分列。","）。"]', '诗', 'shi', '', NULL, '遊般若寺上方 廖處士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83adc5f5-3830-4c0d-9a25-c8a7aec9442f', '偈 一', '偈 一', '788046e6-0e89-48c9-888d-270b3258a5ba', '唐', '["梁山一曲歌，格外人難和。","十載訪知音，未嘗逢一箇。"]', '["梁山一曲歌，格外人难和。","十載訪知音，未嘗逢一箇。"]', '诗', 'shi', '', NULL, '偈 一 緣觀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6203ae0-f071-47e8-9790-3a50a2c605f6', '偈 二', '偈 二', '788046e6-0e89-48c9-888d-270b3258a5ba', '唐', '["紅焰藏吾身，何須塔廟新。","有人相肯重，灰裏邈全真。","（《景德傳燈錄》卷二四、《五燈會元》卷十四。","）。"]', '["紅焰藏吾身，何須塔廟新。","有人相肯重，灰裏邈全真。","（《景德傳灯錄》卷二四、《五灯會元》卷十四。","）。"]', '诗', 'shi', '', NULL, '偈 二 緣觀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08e4df9e-d4ca-4e2d-b959-5ddbff95c2f1', '偈', '偈', '22c3946a-967c-40c1-89d1-38e58f089ef5', '唐', '["妙哉三下板，諸德（《五燈會元》作「知識」）盡來參。","既善分時節，吾今不再三。","（《景德傳燈錄》卷二二、《五燈會元》卷十五。","）。"]', '["妙哉三下板，諸德（《五灯會元》作「知識」）尽来參。","既善分时節，吾今不再三。","（《景德傳灯錄》卷二二、《五灯會元》卷十五。","）。"]', '诗', 'shi', '', NULL, '偈 啓柔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5e32596-f21a-4833-9feb-31d9f45f7392', '偈', '偈', '678ef352-63e9-489f-b70c-ff76136757d2', '唐', '["駿馬機前異，遊人肘後懸。","既參雲外客，試爲老僧看。","（《景德傳燈錄》卷二十三、《五燈會元》卷十五）。"]', '["駿马機前異，游人肘後懸。","既參云外客，試爲老僧看。","（《景德傳灯錄》卷二十三、《五灯會元》卷十五）。"]', '诗', 'shi', '', NULL, '偈 豐禪師 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85e3286c-88c8-4995-b64d-4c889f520ca2', '贈程明甫', '贈程明甫', '3d4601fc-f34c-487c-83be-b89ad8921a8e', '唐', '["古縣枕前灘，官閑道自安。","執杯山鳥唱，曬藥野猿看。","石縫橫琴筆，槎根插釣竿。","不知陶靖節，早晚入雲端。"]', '["古縣枕前灘，官闲道自安。","執杯山鸟唱，曬藥野猿看。","石縫橫琴笔，槎根插釣竿。","不知陶靖節，早晚入云端。"]', '诗', 'shi', '', NULL, '贈程明甫 王鼎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('813defd5-79bc-4571-9780-ba1de8e1e35f', '贈僧', '贈僧', '3d4601fc-f34c-487c-83be-b89ad8921a8e', '唐', '["出齋猿獻果，烹茗鳥啣薪。"]', '["出斋猿獻果，烹茗鸟啣薪。"]', '诗', 'shi', '', NULL, '贈僧 王鼎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7190bb5-0bee-4c88-9662-95ee468733c1', '又題', '又題', '3d4601fc-f34c-487c-83be-b89ad8921a8e', '唐', '["風落桂枝總鶴去，水流山果向人來。"]', '["风落桂枝總鹤去，水流山果向人来。"]', '诗', 'shi', '', NULL, '又題 王鼎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5008271e-e2dc-4a64-bb71-5a05be914a16', '送僧', '送僧', '3d4601fc-f34c-487c-83be-b89ad8921a8e', '唐', '["孤雲蹤跡都無定，出個青山入個山。","（均見周校本《詩話總龜》卷四六引《雅言雜載》）。"]', '["孤云蹤跡都無定，出個青山入個山。","（均见周校本《诗話總龟》卷四六引《雅言杂載》）。"]', '诗', 'shi', '', NULL, '送僧 王鼎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb3fb60c-de9b-424b-bc86-c8faf4fa1254', '', '', '47bc4507-a19c-4f19-91dc-d1e9196c6834', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 程嵩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6b65b36-8b04-4355-827f-207483b30104', '八十後作（題擬）', '八十後作（題擬）', '47bc4507-a19c-4f19-91dc-d1e9196c6834', '唐', '["雖無事業傳千古，却得安閑過一生。","（同前引《雲齋廣錄》）。"]', '["雖無事業傳千古，却得安闲過一生。","（同前引《云斋廣錄》）。"]', '诗', 'shi', '', NULL, '八十後作（題擬） 程嵩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aed460d6-1260-4a45-9ba6-25ce93b80cfe', '頌', '頌', '476b0907-cf6b-4df7-af8f-acc021ca63fe', '唐', '["我有神珠一顆，久被塵勞關鏁。","今朝塵盡光生，照破山河萬朵。","（《五燈會元》卷六）。"]', '["我有神珠一顆，久被塵勞关鏁。","今朝塵尽光生，照破山河万朵。","（《五灯會元》卷六）。"]', '诗', 'shi', '', NULL, '頌 郁山主 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0bf6ce8-e689-464b-bdd4-a0ad03700a67', '郁山主贊', '郁山主贊', '57339990-5b04-495b-a2ea-d7205adb6e30', '唐', '["百尺竿頭曾進步，溪橋一踏沒山河。","從茲不出茶川上，吟嘯無非囉哩囉。","（同前）。"]', '["百尺竿头曾進步，溪橋一踏沒山河。","從茲不出茶川上，吟嘯無非囉哩囉。","（同前）。"]', '诗', 'shi', '', NULL, '郁山主贊 雲端和尚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81860ff4-cfb6-4953-94e1-16a30bf73bc4', '頌', '頌', '32739e77-29f9-468c-b82c-92b014e8b8e0', '唐', '["天地指前徑，時人莫彊移。","箇中生解會，眉上更安眉。","（《景德傳燈錄》卷二三、《五燈會元》卷十五）。"]', '["天地指前徑，时人莫彊移。","箇中生解會，眉上更安眉。","（《景德傳灯錄》卷二三、《五灯會元》卷十五）。"]', '诗', 'shi', '', NULL, '頌 璘禪師 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98cb8d49-1ac8-4b8d-ade5-f94672aaa59b', '偏參三昧歌', '偏參三昧歌', '129d7c8c-13bf-4b1d-ab84-2c630d6e0562', '唐', '["天崖海角參知識，徧恣惠我全提力。","師乃呵余退步追，省躬廓爾從茲息。","覩諸方，垂帶直，善財得處難藏匿。","棒頭喝下露幽奇，縱去奪來看殊特。","趙州關，雪嶺陟，築廅峰前驗虛實。","據證靈由闢萬機，揮祖刃，開三域，卷舒重重孰西委？","休呈識意謾猜揣，納子攢眉碧眼咦。","黃河倒逆崑崙觜。","溈山牛，道吾唱，馬師奮迅呈圓相。","執水投針作後規，把鏡持幡看先匠。","廣陵歌，誰繼唱？擬續宮商調難況。","石人慍色下鞭撾，水馬奔嘶梵天上。","麗水金，蘭田玉，祝融峰攢湘浪蹙。","滿月澄溪松韻清，雲縱龍騰好觀矚。","（見《景德傳燈錄》卷三十）。"]', '["天崖海角參知識，徧恣惠我全提力。","師乃呵余退步追，省躬廓爾從茲息。","覩諸方，垂带直，善財得处难藏匿。","棒头喝下露幽奇，縱去奪来看殊特。","趙州关，雪嶺陟，築廅峰前驗虛實。","據證靈由闢万機，揮祖刃，开三域，卷舒重重孰西委？","休呈識意謾猜揣，納子攢眉碧眼咦。","黄河倒逆崑崙觜。","溈山牛，道吾唱，马師奮迅呈圓相。","執水投針作後規，把镜持幡看先匠。","廣陵歌，誰繼唱？擬續宮商調难況。","石人慍色下鞭撾，水马奔嘶梵天上。","丽水金，蘭田玉，祝融峰攢湘浪蹙。","满月澄溪松韻清，云縱龙腾好观矚。","（见《景德傳灯錄》卷三十）。"]', '诗', 'shi', '', NULL, '偏參三昧歌 道尋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65e0d37f-a437-48ae-b24b-e92408b0f388', '登臨湟樓', '登臨湟楼', '80f685ac-0463-4d7b-bc4a-38d7f026a579', '唐', '["浮世自無閒日月，高樓長有好山川。"]', '["浮世自無閒日月，高楼长有好山川。"]', '诗', 'shi', '', NULL, '登臨湟樓 陳用拙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e2423dd-3f08-49a0-b0b7-8699421c51d8', '送史長沙', '送史长沙', '80f685ac-0463-4d7b-bc4a-38d7f026a579', '唐', '["人說洞庭波浪險（《廣東通志》、《南漢書》作「惡」），使君自有，（《廣東通志》、《南漢書》作「身是」）濟川舟。","（見《小草齋詩話》卷四、《粤詩蒐逸》卷一引《連州志》、鄭方坤《五代詩話》卷二、同治《廣東通志》卷三○三、梁廷柟《南漢書》卷十）。"]', '["人说洞庭波浪險（《廣东通志》、《南漢书》作「惡」），使君自有，（《廣东通志》、《南漢书》作「身是」）濟川舟。","（见《小草斋诗話》卷四、《粤诗蒐逸》卷一引《連州志》、鄭方坤《五代诗話》卷二、同治《廣东通志》卷三○三、梁廷柟《南漢书》卷十）。"]', '诗', 'shi', '', NULL, '送史長沙 陳用拙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f780070-51f1-43c0-aed9-a07a8a21b4b7', '殿試茘枝詩', '殿試茘枝诗', '80f685ac-0463-4d7b-bc4a-38d7f026a579', '唐', '["露濕臙脂拂眼明，紅袍千裹畫難成。","佳人勝盡盤中味，天意偏教嶺外生。","橘柚遠慚登貢籍，鹽梅應合共和羹。","金門若得栽培地，須占人間第一名。","（見清汪森輯《粤西詩載》卷十三）。"]', '["露濕臙脂拂眼明，紅袍千裹畫难成。","佳人勝尽盤中味，天意偏教嶺外生。","橘柚远慚登貢籍，鹽梅應合共和羹。","金门若得栽培地，須占人间第一名。","（见清汪森輯《粤西诗載》卷十三）。"]', '诗', 'shi', '', NULL, '殿試茘枝詩 陳用拙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80d662ea-fd25-48ce-90dd-69eae4845986', '贈劍客', '贈劍客', 'c018fc2a-1fdb-4a62-a894-f62bb5bbfb7a', '唐', '["杯酒會雲林，扶邦志亦深。","晶瑩三尺劍，決烈一生心。","見死尋常事，聞冤即往尋。","荆軻不了處，扼腕到如今。","（周本淳校本《詩話總龜》卷二八引《雅言系述》）。"]', '["杯酒會云林，扶邦志亦深。","晶瑩三尺劍，決烈一生心。","见死尋常事，闻冤即往尋。","荆軻不了处，扼腕到如今。","（周本淳校本《诗話總龟》卷二八引《雅言系述》）。"]', '诗', 'shi', '', NULL, '贈劍客 黃損 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f4c2f8a-8910-47a7-9dfd-aea58bb9d35a', '大鵬山（題擬）', '大鵬山（題擬）', 'c018fc2a-1fdb-4a62-a894-f62bb5bbfb7a', '唐', '["山清神骨水澄心，到此方知勝二林。","（見《輿地紀勝》卷九二《連州》）。"]', '["山清神骨水澄心，到此方知勝二林。","（见《輿地紀勝》卷九二《連州》）。"]', '诗', 'shi', '', NULL, '大鵬山（題擬） 黃損 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f2327a3-9cb5-45f8-9a44-815d42b3e2c4', '月夜江行', '月夜江行', '64a7aa35-78cf-41b7-8fc4-65169d8a0411', '唐', '["欹枕臥拋千嶂月，卸帆閑却一溪風。","（《輿地紀勝》卷一二三《賀州》）。"]', '["欹枕臥拋千嶂月，卸帆闲却一溪风。","（《輿地紀勝》卷一二三《賀州》）。"]', '诗', 'shi', '', NULL, '月夜江行 林楚材 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('067a2547-a476-46da-9520-324eb65d5fe1', '', '', '913ef381-84a8-4ee2-940f-8013b337313d', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 文偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f860e03a-846b-41c5-b651-0f17d3f05cc4', '十二時偈 一', '十二时偈 一', '913ef381-84a8-4ee2-940f-8013b337313d', '唐', '["半夜子，命似懸絲猶未許。","因緣契會剎那間，了了分明一無氣。"]', '["半夜子，命似懸絲猶未許。","因緣契會剎那间，了了分明一無氣。"]', '诗', 'shi', '', NULL, '十二時偈 一 文偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('835effb9-9a6a-4f0e-8d07-f960cf063f25', '十二時偈 二', '十二时偈 二', '913ef381-84a8-4ee2-940f-8013b337313d', '唐', '["鷄鳴丑，一歲孫兒大哮吼。","實相圓明不思議，三世法身藏北斗。"]', '["鷄鳴丑，一歲孫兒大哮吼。","實相圓明不思議，三世法身藏北斗。"]', '诗', 'shi', '', NULL, '十二時偈 二 文偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('391ca6fa-fbee-41ca-a8bf-e41afe49ff09', '十二時偈 三', '十二时偈 三', '913ef381-84a8-4ee2-940f-8013b337313d', '唐', '["平旦寅，三昧圓光證法身。","大千世界掌中收，色透髑髏誰得親。"]', '["平旦寅，三昧圓光證法身。","大千世界掌中收，色透髑髏誰得親。"]', '诗', 'shi', '', NULL, '十二時偈 三 文偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f569f3b6-464b-4ef0-95fa-b37379c7ae1a', '十二時偈 四', '十二时偈 四', '913ef381-84a8-4ee2-940f-8013b337313d', '唐', '["日出卯，嘿說心傳道實教。","心心相印息無心，玄妙之中無拙巧。"]', '["日出卯，嘿说心傳道實教。","心心相印息無心，玄妙之中無拙巧。"]', '诗', 'shi', '', NULL, '十二時偈 四 文偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ae26b49-2e41-46ef-b744-8e61a80586f3', '十二時偈 五', '十二时偈 五', '913ef381-84a8-4ee2-940f-8013b337313d', '唐', '["食時辰，恒沙世界眼中人。","萬法皆從一法生，一法靈光誰是隣。"]', '["食时辰，恒沙世界眼中人。","万法皆從一法生，一法靈光誰是隣。"]', '诗', 'shi', '', NULL, '十二時偈 五 文偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3f59992-50d8-43e0-b083-96114b7517e6', '十二時偈 六', '十二时偈 六', '913ef381-84a8-4ee2-940f-8013b337313d', '唐', '["禺中巳，分明歷歷不相似。","靈源獨曜少人逢，達者方知無所慮。"]', '["禺中巳，分明歷歷不相似。","靈源独曜少人逢，達者方知無所慮。"]', '诗', 'shi', '', NULL, '十二時偈 六 文偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3854b54f-fc30-4755-9b13-34611a16e024', '十二時偈 七', '十二时偈 七', '913ef381-84a8-4ee2-940f-8013b337313d', '唐', '["日中午，一部笙歌誰解儛。","逍遙頓入達無生，晝夜法螺擊法皷。"]', '["日中午，一部笙歌誰解儛。","逍遙頓入達無生，晝夜法螺擊法皷。"]', '诗', 'shi', '', NULL, '十二時偈 七 文偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bbabbc9-249a-4a06-b747-e17b0308c5f3', '十二時偈 八', '十二时偈 八', '913ef381-84a8-4ee2-940f-8013b337313d', '唐', '["日昳未，灌頂醍醐㝡上味。","一切諸佛及菩提，唯佛知之貴中貴。"]', '["日昳未，灌頂醍醐㝡上味。","一切諸佛及菩提，唯佛知之貴中貴。"]', '诗', 'shi', '', NULL, '十二時偈 八 文偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20041280-0682-4092-ba8d-c00b1e2dae34', '十二時偈 九', '十二时偈 九', '913ef381-84a8-4ee2-940f-8013b337313d', '唐', '["晡時申，三壇等施{牙丿=丶}爲賓。","無漏果圓一念修，六度同歸淨土因。"]', '["晡时申，三壇等施{牙丿=丶}爲賓。","無漏果圓一念修，六度同归淨土因。"]', '诗', 'shi', '', NULL, '十二時偈 九 文偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c5517c7-26e2-4fe5-b346-406b7a132230', '十二時偈 十', '十二时偈 十', '913ef381-84a8-4ee2-940f-8013b337313d', '唐', '["日入酉，玄人莫向途中走。","黃葉浮漚賺殺人，命盡慞惶是了手。"]', '["日入酉，玄人莫向途中走。","黄葉浮漚賺殺人，命尽慞惶是了手。"]', '诗', 'shi', '', NULL, '十二時偈 十 文偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5b939db-0295-4586-99ae-78c3b96e3069', '十二時偈 十一', '十二时偈 十一', '913ef381-84a8-4ee2-940f-8013b337313d', '唐', '["黃昏戌，把火尋牛是底物。","素躰相呈却道非，奴郎不弁誰受屈。"]', '["黄昏戌，把火尋牛是底物。","素躰相呈却道非，奴郎不弁誰受屈。"]', '诗', 'shi', '', NULL, '十二時偈 十一 文偃 shi');
